#include <stdlib.h>
#include <string.h>

char* copy_array_of_strings(const char** in, int count) {
    if (in == NULL || count <= 0) {
        return NULL;
    }

    size_t total_length = 0;
    for (int i = 0; i < count; ++i) {
        total_length += strlen(in[i]) + 1; // +1 for the null terminator
    }

    char* result = malloc(total_length);
    if (result == NULL) {
        return NULL;
    }

    char* ptr = result;
    for (int i = 0; i < count; ++i) {
        strcpy(ptr, in[i]);
        ptr += strlen(in[i]) + 1;
    }

    return result;
}
