#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct Transaction {
    int id;
    time_t timestamp;
    double weighted_sum;
};

struct Metrics {
    int total_transactions;
    int filtered_transactions;
    double max_weighted_sum;
    int max_weighted_sum_id;
};

void update_metrics(struct Metrics *metrics) {
    metrics->total_transactions++;
}

int filter_transactions(struct Transaction transactions[], int num_transactions, struct Metrics *metrics) {
    time_t current_time = time(NULL);
    double max_weighted_sum = -1;
    int max_weighted_sum_id = -1;
    int filtered_count = 0;

    for (int i = 0; i < num_transactions; i++) {
        if ((current_time - transactions[i].timestamp) <= 3) {
            update_metrics(metrics);
            metrics->filtered_transactions++;
            if (transactions[i].weighted_sum > max_weighted_sum) {
                max_weighted_sum = transactions[i].weighted_sum;
                max_weighted_sum_id = transactions[i].id;
            }
        }
    }

    metrics->max_weighted_sum = max_weighted_sum;
    metrics->max_weighted_sum_id = max_weighted_sum_id;
    return filtered_count;
}

int main() {
    struct Transaction transactions[] = {
        {1, time(NULL) - 2, 5.0},
        {2, time(NULL) - 4, 3.0},
        {3, time(NULL) - 5, 7.0}
    };
    int num_transactions = sizeof(transactions) / sizeof(transactions[0]);
    struct Metrics metrics = {0, 0, 0, 0};

    filter_transactions(transactions, num_transactions, &metrics);

    printf("Total Transactions: %d\n", metrics.total_transactions);
    printf("Filtered Transactions: %d\n", metrics.filtered_transactions);
    printf("Max Weighted Sum: %.2f (Transaction ID: %d)\n", metrics.max_weighted_sum, metrics.max_weighted_sum_id);

    return 0;
}
