#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char **lines;
    int num_lines;
} TextFile;

TextFile *readTextFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    TextFile *textFile = (TextFile *)malloc(sizeof(TextFile));
    textFile->lines = NULL;
    textFile->num_lines = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        textFile->num_lines++;
        textFile->lines = (char **)realloc(textFile->lines, textFile->num_lines * sizeof(char *));
        textFile->lines[textFile->num_lines - 1] = strdup(buffer);
    }

    fclose(file);
    return textFile;
}

void freeTextFile(TextFile *textFile) {
    for (int i = 0; i < textFile->num_lines; i++) {
        free(textFile->lines[i]);
    }
    free(textFile->lines);
    free(textFile);
}

void printCommaSeparatedFormat(TextFile *textFile) {
    for (int i = 0; i < textFile->num_lines; i++) {
        char *line = textFile->lines[i];
        float lastTwoSum = 0.0f;
        int count = 0;
        char *token = strtok(line, " \t\n");
        while (token != NULL) {
            printf("%s", token);
            if (count == textFile->num_lines - 1) {
                lastTwoSum += atof(token);
            }
            token = strtok(NULL, " \t\n");
            count++;
            if (token != NULL) {
                printf(",");
            }
        }
        if (count > 2) {
            printf(",%.2f", lastTwoSum / 2);
        }
        printf("\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    TextFile *textFile = readTextFile(argv[1]);
    if (!textFile) {
        return EXIT_FAILURE;
    }

    printCommaSeparatedFormat(textFile);

    freeTextFile(textFile);
    return EXIT_SUCCESS;
}
