#include <stdlib.h>

typedef struct BSTNode {
    int offset;
    struct BSTNode *left, *right;
} BSTNode;

BSTNode* createNode(int offset) {
    BSTNode* newNode = (BSTNode*)malloc(sizeof(BSTNode));
    if (newNode == NULL) {
        return NULL; // Allocation failed
    }
    newNode->offset = offset;
    newNode->left = newNode->right = NULL;
    return newNode;
}

BSTNode* insert(BSTNode* root, int offset) {
    if (root == NULL) {
        return createNode(offset);
    }
    if (offset < root->offset) {
        root->left = insert(root->left, offset);
    } else if (offset > root->offset) {
        root->right = insert(root->right, offset);
    }
    return root;
}

BSTNode* search(BSTNode* root, int offset) {
    if (root == NULL || root->offset == offset) {
        return root;
    }
    if (offset < root->offset) {
        return search(root->left, offset);
    } else {
        return search(root->right, offset);
    }
}
