#include <stdio.h>
#include <stdlib.h>
#include "tiffio.h"

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TIFFInfo;

TIFFInfo parseTIFF(const char *filename) {
    TIFFInfo info;
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    uint16 photometric;
    TIFFGetField(tiff, TIFFTAG_PHOTOMETRIC, &photometric);

    info.bitsPerSample = 0;
    info.samplesPerPixel = 0;
    info.extraSamples = 0;

    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &info.bitsPerSample) != 1) {
        fprintf(stderr, "Error reading bits per sample\n");
        exit(EXIT_FAILURE);
    }

    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &info.samplesPerPixel) != 1) {
        fprintf(stderr, "Error reading samples per pixel\n");
        exit(EXIT_FAILURE);
    }

    if (photometric == PHOTOMETRIC_YCBCR || photometric == PHOTOMETRIC_CIELAB) {
        info.extraSamples = 1; // YCbCr or CIELab has an extra sample for chroma/lightness
    } else if (photometric == PHOTOMETRIC_SEPARATED) {
        uint16 samplesPerPixel;
        TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
        info.extraSamples = samplesPerPixel - info.samplesPerPixel; // Extra samples for separated color channels
    }

    if (info.bitsPerSample != 1 && info.bitsPerSample != 2 && info.bitsPerSample != 4 && info.bitsPerSample != 8 && info.bitsPerSample != 16) {
        fprintf(stderr, "Unsupported bits per sample: %d\n", info.bitsPerSample);
        exit(EXIT_FAILURE);
    }

    TIFFClose(tiff);
    return info;
}
