#define ERROR_CODE -1
#define SUCCESS_CODE 0

int dns_resolve(const char *hostname, u_char ip[4]) {
    struct hostent *host;
    struct in_addr addr;

    // Perform DNS resolution
    if ((host = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return ERROR_CODE;
    }

    // Check if the host entry is valid and has an IP address
    if (host->h_addrtype != AF_INET || host->h_length != sizeof(struct in_addr)) {
        fprintf(stderr, "Invalid host entry\n");
        return ERROR_CODE;
    }

    // Copy the IP address to the u_char array
    memcpy(ip, host->h_addr_list[0], sizeof(struct in_addr));

    return SUCCESS_CODE;
