#include <arpa/inet.h>

#define BUFSIZE 1024

void receive_file(const char *filename, const char *mode) {
    int sock;
    struct sockaddr_in server_addr;
    FILE *file;
    char buffer[BUFSIZE];
    ssize_t bytes_received;

    // Create socket
    if ((sock = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        return;
    }

    // Define server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345); // Server port (example)
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr); // Server IP address (localhost for example)

    // Send filename and mode to server
    sendto(sock, filename, strlen(filename), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    sendto(sock, mode, strlen(mode), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));

    // Open the file to write
    if ((file = fopen(filename, "wb")) == NULL) {
        perror("File opening failed");
        close(sock);
        return;
    }

    // Receive and write data to file
    while ((bytes_received = recvfrom(sock, buffer, BUFSIZE, 0, NULL, NULL)) > 0) {
        if (fwrite(buffer, 1, bytes_received, file) != bytes_received) {
            perror("File writing failed");
            break;
        }
    }

    // Clean up
    fclose(file);
    close(sock);

    if (bytes_received < 0) {
        perror("Receive error");
    }
}
