                outputfile = optarg;
                break;
            case 'c':
                cs = 1;
                break;
            case 'm':
                manpage = 1;
                break;
            case 'a':
                // Handle --manpage option if needed
                break;
            default:
                print_usage();
                return 1;
        }
    }

    if (optind < argc) {
        inputfile = argv[optind];
    } else {
        print_usage();
        return 1;
    }

    if (!inputfile) {
        printf("No input file provided.\n");
        print_usage();
        return 1;
    }

    FILE *file = fopen(inputfile, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
    }

    fclose(file);

    printf("Number of lines: %d\n", line_count);

    return 0;
}
