#include <stdlib.h>
#include <string.h>

// Function to dynamically allocate memory for an array and copy a given input array into the allocated memory
int* expand_and_copy(const int* input_array, size_t input_size, size_t prepend, size_t append) {
    // Calculate the new required size of the array
    size_t new_size = input_size + prepend + append;

    // Allocate memory for the new array
    int* new_array = (int*)malloc(new_size * sizeof(int));
    if (new_array == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy the input array into the new array at the start position
    memcpy(new_array + prepend, input_array, input_size * sizeof(int));

    return new_array;
}
