#include <stdio.h>
#include <string.h>
#include <ctype.h>

typedef enum {
    TOKEN_UNKNOWN = 0,
    TOKEN_ID,
    TOKEN_INT,
    TOKEN_FLOAT,
    TOKEN_STRING,
    TOKEN_UNFINISHED_STR,
    TOKEN_TEMPLATE_LITERAL,
    TOKEN_UNFINISHED_TEMPLATE_LITERAL,
    TOKEN_REGEX,
    TOKEN_UNFINISHED_REGEX,
    TOKEN_UNFINISHED_COMMENT,
    // Add other tokens as needed
} TokenType;

TokenType getNextToken(const char **input) {
    while (isspace(**input)) (*input)++; // Skip whitespace

    if (**input == '\0') return TOKEN_UNKNOWN; // End of input

    if (isalpha(**input)) { // Identifier or keyword
        const char *start = *input;
        while (isalnum(**input) || **input == '_') (*input)++;
        return TOKEN_ID;
    }

    if (isdigit(**input)) { // Number
        const char *start = *input;
        int hasDecimal = 0;
        while (isdigit(**input) || **input == '.') {
            if (**input == '.') hasDecimal = 1;
            (*input)++;
        }
        return hasDecimal ? TOKEN_FLOAT : TOKEN_INT;
    }

    // Handle other tokens like strings, comments, etc.
    switch (**input) {
        case '"':
            (*input)++;
            if (strchr(*input, '"')) return TOKEN_STRING;
            else return TOKEN_UNFINISHED_STR;
        // Add cases for other tokens like template literals, regex, etc.
        default:
            (*input)++; // Move to the next character
            return TOKEN_UNKNOWN;
    }
}

int main() {
    const char *input = "var x = 123;";
    TokenType token;
    do {
        token = getNextToken(&input);
        printf("Token: %d\n", token);
    } while (token != TOKEN_UNKNOWN);
    return 0;
}
