void parse_ip_packet(const u_char *packet, int length) {
    const u_char *ptr = packet;
    
    while (length > 0) {
        if (length < 2) {
            printf("Packet too short to contain an option header.\n");
            return;
        }
        
        int opt = ptr[0];
        int len = ptr[1];
        
        if (len > length) {
            printf("Option length exceeds remaining packet length.\n");
            return;
        }
        
        printf("\nOption type: 0x%02x, Length: %d\n", opt, len);
        
        switch (opt) {
            case 0: // End of options (no-operation option)
                return;
                
            default:
                printf("Unknown option type.\n");
                break;
        }
        
        ptr += len;
        length -= len;
    }
}
