// Function to calculate the average size of a dataset and allocate an array for distribution
double* calculate_average_size(int *data, int num_blocks, int items_per_block, int reserved_size) {
    // Calculate total number of elements including reserved space
    int total_elements = num_blocks * items_per_block + reserved_size;
    
    // Allocate memory for the distribution array
    double* distribution = (double*)malloc(total_elements * sizeof(double));
    if (!distribution) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    
    // Calculate average size of the dataset and store in the distribution array
    double sum = 0.0;
    for (int i = 0; i < num_blocks * items_per_block; i++) {
        sum += data[i];
    }
    
    double average = sum / (num_blocks * items_per_block);
    
    // Fill the distribution array with the average size and reserved space for random characters
    for (int i = 0; i < num_blocks * items_per_block; i++) {
        distribution[i] = data[i];
    }
    for (int i = num_blocks * items_per_block; i < total_elements; i++) {
        distribution[i] = average; // or some other value representing reserved space
    }
    
    return distribution;
}
