    pid_t child_pid;
    int status;

    printf("Enter a sentence: ");
    fgets(sentence, sizeof(sentence), stdin);
    sentence[strcspn(sentence, "\n")] = 0; // Remove newline character

    child_pid = fork();
    if (child_pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (child_pid == 0) {
        analyze_sentence(sentence);
        exit(EXIT_SUCCESS);
    } else {
        waitpid(child_pid, &status, 0);
        printf("Child process finished.\n");
    }

    return 0;
}
