#include <stdio.h>
#include <string.h>
#include <ctype.h>

int parse_font_specification(char* spec) {
    // Skip leading hyphens
    while (*spec == '-') {
        spec++;
    }

    // Check if the string is empty after skipping hyphens
    if (*spec == '\0') {
        return 0; // Invalid font specification
    }

    char face[128] = "";
    char style[32] = "";
    int size = -1;

    // Parse the font type face
    int i = 0;
    while (*spec && *spec != '-' && !isdigit(*spec)) {
        face[i++] = *spec++;
    }
    face[i] = '\0';

    // Parse the font style
    if (*spec == '-') spec++; // Skip the hyphen
    i = 0;
    while (*spec && *spec != '-' && isspace(*spec)) {
        style[i++] = *spec++;
    }
    style[i] = '\0';

    // Parse the font size
    if (*spec == '-') spec++; // Skip the hyphen
    char* endptr;
    size = strtol(spec, &endptr, 10);
    if (endptr == spec) {
        return 0; // Invalid size
    }

    // Check for any remaining characters after parsing
    while (*spec && *spec != '-') {
        spec++;
    }

    // If there are no remaining characters, the specification is valid
    if (*spec == '\0') {
        return 1; // Valid font specification
    } else {
        return 0; // Invalid font specification
    }
}
