typedef struct Scheduler {
    pthread_t *threads;
    int num_threads;
    int *suspension_thresholds;
    int *cpu_assignments;
    pthread_mutex_t mutex;
} Scheduler;

Scheduler* init_scheduler(int num_threads, void* (*thread_func)(void*), int *suspension_thresholds) {
    Scheduler *sched = (Scheduler *)malloc(sizeof(Scheduler));
    sched->num_threads = num_threads;
    sched->threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    sched->suspension_thresholds = (int *)malloc(num_threads * sizeof(int));
    sched->cpu_assignments = (int *)malloc(num_threads * sizeof(int));

    for (int i = 0; i < num_threads; i++) {
        sched->suspension_thresholds[i] = suspension_thresholds[i];
    }

    pthread_mutex_init(&sched->mutex, NULL);

    for (int i = 0; i < num_threads; i++) {
        int result = pthread_create(&sched->threads[i], NULL, thread_func, &sched->suspension_thresholds[i]);
        if (result != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    return sched;
}

void* example_thread_func(void *arg) {
    int *threshold = (int *)arg;
    while (*threshold > 0) {
        // Simulate thread activity
        printf("Thread running with threshold: %d\n", *threshold);
        (*threshold)--;
    }
    return NULL;
}

int main() {
    int suspension_thresholds[] = {5, 10, 7};
    Scheduler *sched = init_scheduler(3, example_thread_func, suspension_thresholds);

    // Wait for threads to finish (simulated)
    for (int i = 0; i < 3; i++) {
        pthread_join(sched->threads[i], NULL);
    }

    free(sched->threads);
    free(sched->suspension_thresholds);
    free(sched->cpu_assignments);
    pthread_mutex_destroy(&sched->mutex);
    free(sched);

