typedef struct {
    char *stack;
    size_t stack_size;
    size_t top;
} Stack;

void init_stack(Stack *s, size_t size) {
    s->stack = (char *)malloc(size);
    if (!s->stack) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    s->stack_size = size;
    s->top = 0;
}

void push_to_stack(Stack *s, char c) {
    if (s->top >= s->stack_size) {
        fprintf(stderr, "Stack overflow\n");
        exit(EXIT_FAILURE);
    }
    s->stack[s->top++] = c;
}

char pop_from_stack(Stack *s) {
    if (s->top == 0) {
        fprintf(stderr, "Stack underflow\n");
        exit(EXIT_FAILURE);
    }
    return s->stack[--s->top];
}

void process_input(const char *input) {
