#include <stdlib.h>

void *create_pollset(size_t initial_size) {
    void *pollset = malloc(initial_size);
    if (!pollset) {
        return NULL; // Allocation failed
    }
    size_t current_size = initial_size;

    while (1) {
        void *new_pollset = realloc(pollset, current_size * 2);
        if (new_pollset) {
            pollset = new_pollset;
            current_size *= 2;
        } else {
            // Reallocation failed, free the previous allocation and return NULL
            free(pollset);
            return NULL;
        }
    }
}
