#include <stdlib.h>
#include <string.h>
#include <stdio.h>

void* xcalloc(size_t num, size_t size) {
    size_t res;
    if (check_mul_overflow(num, size, &res))
        abort();

    void *ptr = malloc(res);
    if (ptr) {
        memset(ptr, '\0', res);
    }
    return ptr;
}

int check_mul_overflow(size_t a, size_t b, size_t *result) {
    // Check for overflow
    if (b != 0 && a > SIZE_MAX / b) {
        return 1;
    }
    *result = a * b;
    return 0;
}

