int** create_symmetric_matrix(size_t size) {
    // Calculate the total number of elements in the matrix
    size_t num_elements = (size * (size + 1)) / 2;

    // Allocate memory for the values array
    double* values = (double*)xcalloc(num_elements, sizeof(double));
    if (!values) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Allocate memory for the matrix pointers
    int** matrix = (int**)malloc(size * sizeof(int*));
    if (!matrix) {
        free(values);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Calculate the starting index of each row in the values array
    size_t offset = 0;
    for (size_t i = 0; i < size; ++i) {
        matrix[i] = (int*)(values + offset);
        offset += (size - i);
    }

    return matrix;
}
