char *format_bytes(char *buf, size_t l, unsigned long long bytes) {
    static const char *suffixes[] = {"B", "K", "M", "G", "T"};
    double value;
    int i;

    if (bytes == 0) {
        strncpy(buf, "0 B", l);
        buf[l - 1] = '\0';
        return buf;
    }

    value = bytes;
    i = 0;

    while (value >= 1024.0 && i < 5) {
        value /= 1024.0;
        i++;
    }

    if (i == 0) {
        snprintf(buf, l, "%llu B", bytes);
    } else {
        snprintf(buf, l, "%.1f %s", value, suffixes[i]);
    }

    return buf;
}
