char* generate_shared_secret(const char* input_string, time_t timestamp, const char* entropy) {
    // Convert the current time to a string
    char time_str[26];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

    // Concatenate the input string, timestamp, and entropy into one string
    char* data = (char*)malloc(strlen(input_string) + strlen(time_str) + strlen(entropy) + 1);
