int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    int line_count = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }

    // Check for the last line if it doesn't end with a newline character
    rewind(file); // Rewind to the beginning of the file
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') {
            line_count++;
            break; // Exit after counting one more line for the last newline character
        }
    }

    printf("Number of lines: %d\n", line_count);

    fclose(file);
    return 0;
}
