void encrypt_data(const unsigned char *key, int key_len, unsigned char *data, int data_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error
        return;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    int outlen = 0;
    if (EVP_EncryptUpdate(ctx, data, &outlen, data, data_len) != 1) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    int final_len = 0;
    if (EVP_EncryptFinal_ex(ctx, data + outlen, &final_len) != 1) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    outlen += final_len;
    data_len = outlen;

    EVP_CIPHER_CTX_free(ctx);
}
