function register_class($class_name, $extension_directory, $zend_class_entry) {
    // Register INI entries for the extension
    zend_register_ini_entries($extension_directory);

    // Set up object handlers to disable cloning for the new class
    zend_object_handlers_t handlers;
    memset(&handlers, 0, sizeof(zend_object_handlers_t));
    handlers.clone_obj = NULL;

    // Register the new class with the given name
    zend_class_entry *ce = zend_register_internal_class_ex((const char *)class_name, NULL, (zend_uint)0);
    if (!ce) {
        return;
    }

    // Set up object handlers for the new class
    ce->handlers = &handlers;
}
