#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

void dns_name_to_ip(const char *dns_name, char ip_octal[16]) {
    struct addrinfo hints, *res, *p;
    int status;
    void *addr;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Use AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(dns_name, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;

        if (p->ai_family == AF_INET) {
            addr = &(ipv4->sin_addr);
            inet_ntop(AF_INET, addr, ip_octal, INET_ADDRSTRLEN);
        } else {
            addr = &(ipv6->sin6_addr);
            inet_ntop(AF_INET6, addr, ip_octal, INET6_ADDRSTRLEN);
        }
    }

    freeaddrinfo(res);
}

int main() {
    const char *dns_name = "example.com";
    char ip_octal[16];

    dns_name_to_ip(dns_name, ip_octal);
    printf("IP address for %s is: %s\n", dns_name, ip_octal);

    return 0;
}
