#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    int hours;
    int minutes;
    int seconds;
} Time;

int parse_time_component(const char **str) {
    int value = 0;
    while (isdigit(**str)) {
        value = value * 10 + (*(*str)++ - '0');
    }
    return value;
}

int parse_time(const char *input, Time *time) {
    const char *ptr = input;
    
    // Parse hours
    time->hours = parse_time_component(&ptr);
    if (*ptr != ':') return 0; // Invalid format if no colon after hours
    ptr++;
    
    // Parse minutes
    time->minutes = parse_time_component(&ptr);
    if (*ptr != ':') return 0; // Invalid format if no colon after minutes
    ptr++;
    
    // Parse seconds
    time->seconds = parse_time_component(&ptr);
    
    // Check for valid time components
    if (time->hours < 0 || time->hours > 23) return 0;
    if (time->minutes < 0 || time->minutes > 59) return 0;
    if (time->seconds < 0 || time->seconds > 59) return 0;
    
    // Skip any remaining whitespace and check for end of string
    while (isspace(*ptr)) ptr++;
    if (*ptr != '\0') return 0; // Extra characters after valid time
    
    return 1;
}

int main() {
    const char *input = "The time is 12:34:56.";
    Time parsed_time;
    
