struct record {
    int data;
};

struct knode {
    struct record rec;
    struct knode *next;
};

void *setup_queue(int size, int order) {
    void *root_mem;
    struct knode *root;
    
    // Calculate the maximum number of nodes based on size and order
    int max_nodes = 1 << order; // This is equivalent to 2^order
    
    // Allocate memory for the root node using malloc
    root_mem = malloc(sizeof(struct knode) * max_nodes);
    if (!root_mem) {
        return NULL;
    }
    
    // Initialize the root node and set up the queue
    root = (struct knode *)root_mem;
    root->rec.data = 0; // Set initial data value for demonstration purposes
    root->next = NULL;   // The root is the only node initially, so it points to NULL
    
    return root;
}
