#include <string.h>

#define BUFFER_SIZE 1024

typedef struct {
    char buffer[BUFFER_SIZE];
    size_t pos;
    size_t end;
} LineBuffer;

void initLineBuffer(LineBuffer *lb) {
    lb->pos = 0;
    lb->end = 0;
}

ssize_t readLineFromFile(FILE *file, char *line, size_t maxLen) {
    LineBuffer lb;
    initLineBuffer(&lb);

    while (1) {
        if (lb.pos >= lb.end && feof(file)) {
            return -1; // End of file reached
        }

        if (lb.pos >= lb.end) {
            lb.end = fread(lb.buffer, 1, BUFFER_SIZE, file);
            lb.pos = 0;
        }

        size_t i;
        for (i = 0; lb.pos < lb.end && line[i] != '\n'; ++i) {
            line[i] = lb.buffer[lb.pos++];
        }

        if (lb.pos < lb.end || i == maxLen) {
            break; // Line is complete or buffer full
        }
    }

    line[i] = '\0'; // Null-terminate the line
    return i; // Return length of the line read (excluding null terminator)
}

void pushBackLine(const char *line, size_t len) {
