#include <time.h>

typedef struct {
    int type;
    char name[50];
} Card;

typedef struct Node {
    Card card;
    struct Node* next;
} Node;

Node* createCardList(Card cards[], int size) {
    Node* head = NULL;
    Node* temp = NULL;
    for (int i = 0; i < size; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->card = cards[i];
        newNode->next = NULL;
        if (head == NULL) {
            head = newNode;
            temp = newNode;
        } else {
            temp->next = newNode;
            temp = newNode;
        }
    }
    return head;
}

void shuffleCards(Card cards[], int size) {
    srand(time(NULL)); // Seed the random number generator with current time
    for (int i = size - 1; i > 0; i--) {
        int j = rand() % (i + 1); // Generate a random index between 0 and i
        Card temp = cards[i]; // Swap cards[i] and cards[j]
        cards[i] = cards[j];
        cards[j] = temp;
    }
}

Node* shuffleDeck(Card cards[], int size) {
    shuffleCards(cards, size); // Shuffle the array of card structures
    return createCardList(cards, size); // Create a linked list from shuffled array
}
