typedef struct {
    char **files;
    int count;
} FileList;

// Function to initialize the FileList structure
FileList* init_filelist() {
    FileList *fl = (FileList*)malloc(sizeof(FileList));
    fl->files = NULL;
    fl->count = 0;
    return fl;
}

// Function to add a file to the FileList structure
void add_file(FileList *fl, const char *filename) {
    fl->count++;
    fl->files = (char**)realloc(fl->files, fl->count * sizeof(char*));
    fl->files[fl->count - 1] = strdup(filename);
}

// Function to search for files matching a given pattern
int search_files(const char *pattern) {
    FileList *fl = init_filelist();
    glob_t gg;
    
    int ret = glob(pattern, 0, NULL, &gg);
    if (ret != 0 && ret != GLOB_NOMATCH) {
        perror("glob");
        return -1;
    }
    
    for (size_t i = 0; i < gg.gl_pathc; i++) {
        if (!mp_path_isdir(gg.gl_pathv[i])) {
            add_file(fl, gg.gl_pathv[i]);
        }
    }
    
    globfree(&gg);
    
    printf("Number of files found: %d\n", fl->count);
    
    // Free allocated memory for file names
    for (int i = 0; i < fl->count; i++) {
        free(fl->files[i]);
    }
    free(fl->files);
    free(fl);
    
    return fl->count;
}
