        strcpy(buffer, serviceName);
        buffer += strlen(serviceName);

        // Append a pointer record with a TTL of 4 minutes (240 seconds)
        *buffer++ = '\x00'; // Pointer type
        *buffer++ = '\x01'; // Class IN
        *(uint32_t*)buffer = htonl(240); // TTL in network byte order
        buffer += 4;
        *buffer++ = '\x00'; // Zero length for the pointer record
        *buffer++ = '\x00'; // End of DNS message
    }
    return buffer;
}
