char* combine_path(const char* directory, const char* file) {
    size_t dir_len = strlen(directory);
    size_t file_len = (file != NULL) ? strlen(file) : 0;
    size_t total_len = dir_len + (file_len > 0 ? 1 : 0) + file_len; // +1 for the '/' or '\0'
    
    char* fullpath = (char*)malloc(total_len + 1); // +1 for the null terminator
    if (!fullpath) {
        perror("Failed to allocate memory");
        return NULL;
    }
    
    strcpy(fullpath, directory);
    if (file_len > 0 && fullpath[dir_len - 1] != '/' && fullpath[dir_len - 1] != '\\') {
        fullpath[dir_len] = '/';
        dir_len++;
    }
    strcpy(fullpath + dir_len, file);
    
