MYSQL_RES* execute_prepared_statement(MYSQL *conn, const char *stmt_str, ...) {
    MYSQL_STMT *stmt;
    MYSQL_BIND bind[10]; // Adjust the size as needed based on your requirements
    int ret;
    va_list args;

    stmt = mysql_stmt_init(conn);
    if (!stmt) {
        fprintf(stderr, "mysql_stmt_init() failed\n");
        return NULL;
    }

    // Prepare the statement
    ret = mysql_stmt_prepare(stmt, stmt_str, strlen(stmt_str));
    if (ret != 0) {
        fprintf(stderr, "mysql_stmt_prepare() failed: %s\n", mysql_stmt_error(stmt));
        mysql_stmt_close(stmt);
        return NULL;
    }

    // Bind the arguments
    va_start(args, stmt_str);
    for (int i = 0; ; ++i) {
        const char *arg = va_arg(args, const char *);
        if (!arg) break;

        MYSQL_BIND *b = &bind[i];
        b->buffer_type = MYSQL_TYPE_STRING; // Adjust based on your data types
        b->buffer = (void *)arg;
        b->is_null = 0;
        b->length = strlen(arg);

        ret = mysql_stmt_bind_param(stmt, b);
        if (ret != 0) {
            fprintf(stderr, "mysql_stmt_bind_param() failed: %s\n", mysql_stmt_error(stmt));
            va_end(args);
            mysql_stmt_close(stmt);
            return NULL;
        }
    }
    va_end(args);

    // Execute the statement
    ret = mysql_stmt_execute(stmt);
    if (ret != 0) {
        fprintf(stderr, "mysql_stmt_execute() failed: %s\n", mysql_stmt_error(stmt));
        mysql_stmt_close(stmt);
        return NULL;
    }

    // Get the result set
    MYSQL_RES *res = mysql_stmt_result_metadata(stmt);
    if (!res) {
        fprintf(stderr, "mysql_stmt_result_metadata() failed: %s\n", mysql_stmt_error(stmt));
        mysql_stmt_close(stmt);
        return NULL;
    }

    // Free the statement handle (the result set will be managed by the caller)
    mysql_stmt_free_result(stmt);
    mysql_stmt_close(stmt);

    return res;
