char* md4_hash(const char* input, size_t length) {
    unsigned char digest[MD4_DIGEST_LENGTH];
    MD4((unsigned char*)input, length, (unsigned char*)digest);

    // Allocate memory for the hash string
    char* output = (char*)malloc(2 * MD4_DIGEST_LENGTH + 1);
    if (!output) {
        return NULL; // Memory allocation failed
    }

    // Convert the digest to a hexadecimal representation
    for (int i = 0; i < MD4_DIGEST_LENGTH; ++i) {
        sprintf(&output[i * 2], "%02x", digest[i]);
    }

    return output;
}
