int count_files(const char *dir, const char *format) {
    DIR *dp;
    struct dirent *entry;
    int count = 0;
    char path[1024];

    if (!(dp = opendir(dir))) {
        perror("opendir");
        return -1;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        snprintf(path, sizeof(path), "%s/%s", dir, entry->d_name);

        if (entry->d_type == DT_DIR) {
            count += count_files(path, format);
        } else if (entry->d_type == DT_REG) {
            FILE *file = fopen(path, "r");
            if (file) {
                char buffer[1024];
                while (fgets(buffer, sizeof(buffer), file)) {
                    if (strstr(buffer, format) != NULL) {
                        count++;
                        break;
                    }
                }
                fclose(file);
            }
        }
    }

    closedir(dp);
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <format>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *dir = argv[1];
    const char *format = argv[2];

    int total_count = count_files(dir, format);
    if (total_count == -1) {
        return EXIT_FAILURE;
    }

    printf("Total number of files with the specified format: %d\n", total_count);
    return EXIT_SUCCESS;
}
