    char name[1024];
    DIR *dir;
    struct dirent *d;
    int pid = 0;
    int cnt = 0;
    unsigned inode;
    int i;

    if ((dir = opendir("/proc")) == NULL)
        return;

    while ((d = readdir(dir)) != NULL && cnt < size) {
        DIR *dir1;
        struct dirent *d1;
        int pos;
        char crap;

        if (sscanf(d->d_name, "%d%c", &pid, &crap) != 1)
            continue;

        pos = sprintf(name, "/proc/%d/fd/", pid);
        if ((dir1 = opendir(name)) == NULL)
            continue;

        while ((d1 = readdir(dir1)) != NULL && cnt < size) {
            int fd, n;
            char lnk[64];

            if (sscanf(d1->d_name, "%d", &fd) != 1)
                continue;

            sprintf(name + pos, "%d", fd);
            n = readlink(name, lnk, sizeof(lnk) - 1);
            if (n + 1 < sizeof(lnk)) {
                lnk[n] = 0;
                if (sscanf(lnk, "socket:[%u]", &inode) != 1)
                    continue;
                for (i = 0; i < size; i++) {
                    if (pairs[i].inode == inode) {
                        cnt++;
                        pairs[i].process_id = pid;
                        break;
                    }
                }
            }
        }
        closedir(dir1);
    }
    closedir(dir);
}

