#include <stdio.h>
#include <string.h>
#include <stdlib.h>

struct FileNameInfo {
    char* name;
    size_t length;
};

int getFileNameLength(const char* buffer, struct FileNameInfo* info) {
    // Check if the input is valid
    if (buffer == NULL || strlen(buffer) < 1) {
        return -1;
    }

    // Initialize the file name information structure
    info->name = malloc(sizeof(char) * MAX_PATH);
    info->length = 0;

    // Iterate through the buffer and extract the file name
    for (int i = 0; i < strlen(buffer); i++) {
        if (buffer[i] == '.') {
            // Check if the file name is too long
            if (info->length > MAX_FILENAME) {
                free(info->name);
                return -1;
            }
            info->name[info->length++] = buffer[i];
        } else {
            // Check if the file name is too long
            if (info->length >= MAX_FILENAME) {
                free(info->name);
                return -1;
            }
            info->name[info->length++] = buffer[i];
        }
    }

    // Return the length of the file name
    return info->length;
}

int main() {
    struct FileNameInfo info;
    char buffer[] = "example.txt";
    int len = getFileNameLength(buffer, &info);
    printf("File name: %s\n", info.name);
    printf("File name length: %d\n", len);
}
