#include <time.h>

int setup_network_socket(const char *protocol, const char *path, const char *name) {
    int sfd = -1;
    struct sockaddr_in server_address;
    struct timeval timeout;

    // Create socket
    if ((sfd = socket(AF_INET, atoi(protocol), 0)) < 0) {
        perror("socket()");
        return -1;
    }

    // Set up server address
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(atoi(path));
    if (inet_pton(AF_INET, name, &server_address.sin_addr) <= 0) {
        perror("inet_pton()");
        close(sfd);
        return -1;
    }

    // Set send and receive timeout
    timeout.tv_sec = 5; // 5 seconds
    timeout.tv_usec = 0;
    if (setsockopt(sfd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) < 0 ||
        setsockopt(sfd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
        perror("setsockopt()");
        close(sfd);
        return -1;
    }

    // Connect to the server
    if (connect(sfd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("connect()");
        close(sfd);
        return -1;
    }

    return sfd;
}
