// Define necessary structures for OLED display and queue
typedef struct {
    char message[100];
} OLEDMessage;

typedef struct Node {
    OLEDMessage data;
    struct Node* next;
} QueueNode;

typedef struct {
    QueueNode* front;
    QueueNode* rear;
} Queue;

// Function to create an empty queue
Queue* createQueue() {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->front = NULL;
    q->rear = NULL;
    return q;
}

// Function to enqueue a message into the queue
void enqueue(Queue* q, OLEDMessage msg) {
    QueueNode* temp = (QueueNode*)malloc(sizeof(QueueNode));
    temp->data = msg;
    temp->next = NULL;
    if (q->front == NULL && q->rear == NULL) {
        q->front = q->rear = temp;
        return;
    }
    q->rear->next = temp;
    q->rear = temp;
}

// Function to dequeue a message from the queue
OLEDMessage dequeue(Queue* q) {
    OLEDMessage msg = {0}; // Initialize with default values
    if (q->front == NULL) {
        printf("Queue is empty\n");
        return msg;
    }
    QueueNode* temp = q->front;
    msg = temp->data;
    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    return msg;
}

