EVP_CIPHER *get_des_cipher(const char *mode, const unsigned char *key, int key_len, const unsigned char *iv, int iv_len) {
    EVP_CIPHER *cipher = NULL;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    } else {
        return NULL; // Unsupported mode
    }

    if (cipher != NULL && key != NULL && iv != NULL) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        if (ctx == NULL) {
            return NULL;
        }
        if (EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, 1) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        EVP_CIPHER_CTX_free(ctx);
    }

    return cipher;
}
