// Define a mutex for thread-safety
pthread_mutex_t error_counter_mutex = PTHREAD_MUTEX_INITIALIZER;
int error_counter = 0;

void parse_http_response(const char* response) {
    // Assuming the HTTP response is in a simple format like "HTTP/1.1 <code> <message>"
    const char* code_start = strstr(response, " ");
    if (code_start == NULL) {
        printf("Invalid HTTP response format\n");
        return;
    }
    code_start++; // Move to the start of the code
    int http_code = atoi(code_start);

    pthread_mutex_lock(&error_counter_mutex);
    if (http_code < 200 || http_code >= 300) {
        error_counter++;
        printf("Warning: HTTP response code is %d\n", http_code);
    }
    pthread_mutex_unlock(&error_counter_mutex);
}

int main() {
    const char* response = "HTTP/1.1 200 OK";
    parse_http_response(response);

    // Simulate another HTTP response with a non-2xx code
    const char* bad_response = "HTTP/1.1 404 Not Found";
    parse_http_response(bad_response);

    printf("Total errors: %d\n", error_counter);
    return 0;
}
