#include <string.h>

char* remove_trailing_newlines(char* line) {
    // Find the length of the string
    int len = strlen(line);
    
    // Remove trailing newlines or carriage returns
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        if (line[len - 1] == '\r') {
            len--; // Skip the carriage return character
        }
        len--; // Move to the previous character
    }
    
    // Append a newline character at the end of the string
    line[len] = '\n';
    line[len + 1] = '\0';
    
    return line;
}
