#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

// Callback function prototype
typedef int (*file_callback)(const char *filename);

// Recursive directory traversal function
int traverse_directory(const char *path, file_callback callback) {
    DIR *dir;
    struct dirent *entry;
    char full_path[1024];

    // Open the directory
    dir = opendir(path);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    // Read entries in the directory
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // Skip '.' and '..' entries
        }

        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        if (entry->d_type == DT_DIR) {
            // Recursively traverse subdirectories
            if (traverse_directory(full_path, callback) != 0) {
                closedir(dir);
                return -1;
            }
        } else if (entry->d_type == DT_REG || entry->d_type == DT_UNKNOWN) {
            // Call the callback function for regular files
            if (callback(full_path) != 0) {
                closedir(dir);
                return -1;
            }
        }
    }

    // Close the directory
    closedir(dir);
    return 0;
}
