#include <stdio.h>
#include <stdlib.h>
#include <string.h>

size_t insert_substring(char *str, const char *substr, size_t pos) {
    size_t str_len = strlen(str);
    size_t substr_len = strlen(substr);
    
    // Check if the position is valid
    if (pos > str_len) {
        return str_len; // Return original length if pos is out of bounds
    }
    
    // Resize the string to accommodate the new substring
    char *new_str = realloc(str, str_len + substr_len + 1);
    if (new_str == NULL) {
        return str_len; // Return original length in case of allocation failure
    }
    
    // Shift the string to make space for the new substring
    memmove(new_str + pos + substr_len, new_str + pos, str_len - pos + 1);
    
    // Insert the new substring
    memcpy(new_str + pos, substr, substr_len);
    
    // Update the original string pointer and return the new length
    *str = *new_str;
    return str_len + substr_len;
}
