#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

int createUnixSocket(const char *sockFile) {
    int sock;
    struct sockaddr_un addr;

    // Create socket
    sock = socket(AF_UNIX, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    // Set up the Unix address structure
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    if (strlen(sockFile) >= sizeof(addr.sun_path)) {
        close(sock);
        return -1; // File name too long for the socket path
    }
    strncpy(addr.sun_path, sockFile, sizeof(addr.sun_path) - 1);

    // Bind the socket to the file name
    if (bind(sock, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) < 0) {
        perror("bind");
        close(sock);
        return -1;
    }

    // Listen for incoming connections
    if (listen(sock, 5) < 0) {
        perror("listen");
        close(sock);
        return -1;
    }

    return sock;
}
