        arr[i] = rand() % 100; // Random numbers between 0 and 99
    }

    printf("Original Array: ");
    printArray(arr, size);

    bubbleSort(arr, size);

    printf("Sorted Array in Ascending Order: ");
    printArray(arr, size);

