        return;
    }
    new_driver->next = block_drivers;
    block_drivers = new_driver;
}

// Function to find a block driver by file name, considering an optional protocol prefix
struct block_driver *find_block_driver(const char *file_name) {
    struct block_driver *current = block_drivers;
    while (current != NULL) {
        if (strncmp(current->name, file_name, strlen(current->name)) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL; // Driver not found
