#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/md5.h>

char* generate_shared_secret(const char* path, uint32_t timestamp) {
    // Calculate the length of the input string
    size_t len = strlen(path);

    // Convert the integer to a string
    char ts[17];
    sprintf(ts, "%" PRIu32 , timestamp);

    // Concatenate the two strings
    char* input = malloc((len + strlen(ts) + 1) * sizeof(char));
    strcpy(input, path);
    strcat(input, ts);

    // Initialize the MD5 context
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit(ctx, EVP_md5());

    // Update the hash with the input string
    EVP_DigestUpdate(ctx, input, len);

    // Finalize the hash and convert it to a hexadecimal string
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len = 0;
    EVP_DigestFinal(ctx, digest, &digest_len);
    char* output = malloc((2 * digest_len + 1) * sizeof(char));
    for (size_t i = 0; i < digest_len; i++) {
        sprintf(&output[2 * i], "%02x", digest[i]);
    }
    output[digest_len * 2] = '\0';

    // Free the memory allocated for the input string and the MD5 context
    free(input);
    EVP_MD_CTX_free(ctx);

    return output;
}

int main() {
    char* path = "path/to/file";
    uint32_t timestamp = 1640995200; // January 1, 2022
    char* secret = generate_shared_secret(path, timestamp);
    printf("Shared secret: %s\n", secret);
    free(secret);
    return 0;
}

