// Function to parse the JWT and extract the access token
char* parse_jwt(const char* jwt, const char* secret_key) {
    // Load the private key from PEM format
    EVP_PKEY* pkey = NULL;
    BIO* bio = BIO_new_mem_buf((void*)secret_key, -1);
    if (!bio) {
        fprintf(stderr, "Failed to create BIO\n");
        return NULL;
    }
    pkey = PEM_read_bio_PrivateKey(bio, NULL, NULL, NULL);
    BIO_free(bio);
    if (!pkey) {
        fprintf(stderr, "Failed to read private key\n");
        return NULL;
    }

    // Verify the JWT signature using the secret key
    jwt_t* decoded = jwt_decode(jwt, 0, NULL);
    if (!decoded) {
        fprintf(stderr, "Failed to decode JWT\n");
        EVP_PKEY_free(pkey);
        return NULL;
    }

    int ret = jwt_verify(decoded, pkey);
    if (ret != 1) {
        fprintf(stderr, "JWT verification failed\n");
        jwt_free(decoded);
        EVP_PKEY_free(pkey);
        return NULL;
    }

    // Extract the access token from the claims
    const char* payload = jwt_payload(decoded);
    if (!payload) {
        fprintf(stderr, "Failed to get JWT payload\n");
        jwt_free(decoded);
        EVP_PKEY_free(pkey);
        return NULL;
    }

    // Allocate memory for the access token and copy it from the payload
    char* access_token = (char*)malloc(strlen(payload) + 1);
    if (!access_token) {
        fprintf(stderr, "Failed to allocate memory\n");
        jwt_free(decoded);
        EVP_PKEY_free(pkey);
        return NULL;
    }
    strcpy(access_token, payload);

    // Free resources and return the access token
    jwt_free(decoded);
    EVP_PKEY_free(pkey);
    return access_token;
}
