char *concatenate_and_correct_path(const char *cwd, size_t cwd_len, const char *path) {
    static char result[PATH_MAX];
    char temp[PATH_MAX];
    char *ptr;

    // Concatenate the current working directory and the given path
    snprintf(temp, PATH_MAX, "%s%s", cwd, path);

    // Correct the path to ensure it is an absolute path
    if (temp[0] != '/') {
        char *cwd_copy = strdup(cwd);
        if (!cwd_copy) return NULL;

        // Ensure there's a trailing slash in the cwd
        size_t len = strlen(cwd_copy);
        if (len > 0 && cwd_copy[len - 1] != '/') {
            strcat(cwd_copy, "/");
        }

        // Concatenate the cwd and path with a leading slash
        snprintf(temp, PATH_MAX, "%s%s", cwd_copy, path);
        free(cwd_copy);
    }

    // Remove any duplicate slashes
    ptr = temp;
    char *write_ptr = temp;
    while (*ptr) {
        if (*ptr == '/' && *(ptr + 1) == '/') {
            ptr++;
        } else {
            *write_ptr++ = *ptr;
        }
        ptr++;
    }
    *write_ptr = '\0';

    // Get the absolute path
    if (!realpath(temp, result)) {
        return NULL;
    }

    return result;
}
