void InsertNewLine(HWND hEdit)
{
    // Get the current cursor position in the edit control
    LONG lCurrentPos = Edit_GetSel(hEdit);
    
    // Get the length of the text currently in the edit control
    DWORD dwTextLength = Edit_GetText(hEdit, NULL, 0);
    
    // Allocate a buffer for the new line of text
    LPSTR lpNewLine = (LPSTR)malloc((dwTextLength + 3) * sizeof(char));
    
    // Copy the current text to the buffer
    Edit_GetText(hEdit, lpNewLine, dwTextLength);
    
    // Add a new line character to the end of the buffer
    strcat(lpNewLine, "\r\n");
    
    // Insert the new line text into the edit control at the current cursor position
    Edit_SetSel(hEdit, lCurrentPos);
    Edit_ReplaceSel(hEdit, lpNewLine);
    
    // Free the buffer for the new line of text
    free(lpNewLine);
}

