void des_ecb_encrypt(const unsigned char key[3][8], const unsigned char *plaintext, unsigned char result[3][8]) {
    DES_key_schedule schedule;
    int i;

    for (i = 0; i < 3; i++) {
        DES_set_key_unchecked(&key[i], &schedule);
        DES_ecb_encrypt((const_DES_cblock *)plaintext, (DES_cblock *)result[i], &schedule, DES_ENCRYPT);
        plaintext += 8;
