void modify_filename(char *buffer, const char *orig_name) {
    int len = strlen(orig_name);
    if (len == 0) {
        fprintf(stderr, "An empty string is not a valid file name\n");
        return;
    }

    // Determine the number of digits and file type from the original filename
    int digits = 0;
    char file_type[5]; // Assuming file type will not be longer than 4 characters
    const char *dot = strrchr(orig_name, '.');
    if (dot) {
        snprintf(file_type, sizeof(file_type), "%s", dot + 1);
        digits = len - strlen(file_type) - 1;
    } else {
        strncpy(file_type, "", sizeof(file_type));
        digits = len;
    }

    // Create the new filename using sprintf and strcat
    if (snprintf(buffer, PATH_MAX + 1, "%.*s%0*d.%s", digits, orig_name, digits, 0, file_type) > PATH_MAX) {
        fprintf(stderr, "Filename is too long (> %d)\n", PATH_MAX);
    }
}
