#include <windows.h>
#include <stdio.h>

char* get_jre_path() {
    HKEY hKey;
    DWORD type;
    char path[MAX_PATH];
    DWORD size = sizeof(path);

    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, "SOFTWARE\\JavaSoft\\Java Update Scheduler", 0, KEY_QUERY_VALUE, &hKey) != ERROR_SUCCESS) {
        return NULL;
    }

    if (RegQueryValueExA(hKey, "JREPath", NULL, &type, (BYTE*)path, &size) != ERROR_SUCCESS) {
        RegCloseKey(hKey);
        return NULL;
    }

    RegCloseKey(hKey);
    char* result = malloc(strlen(path) + 1);
    strcpy(result, path);
    return result;
}
