#include <vector>
#include <algorithm>
#include <limits>
#include <cstdlib> // for std::abs

struct Pair {
    int value;
    bool selected;
};

std::pair<int, std::vector<Pair>> find_best_combination(const std::vector<Pair>& pairs, int target) {
    int best_sum = std::numeric_limits<int>::min();
    std::vector<Pair> best_combination;

    for (size_t i = 0; i < (1 << pairs.size()); ++i) { // Iterate over all possible combinations
        int current_sum = 0;
        std::vector<Pair> current_combination;

        for (size_t j = 0; j < pairs.size(); ++j) {
            if (i & (1 << j)) { // Check if the j-th pair is selected in the current combination
                current_sum += pairs[j].value;
                current_combination.push_back(pairs[j]);
            }
        }

        if (std::abs(current_sum - target) < std::abs(best_sum - target)) { // Update the best combination if the current one is better
            best_sum = current_sum;
            best_combination = current_combination;
        }
    }

    return {best_sum, best_combination};
}
