#include <string.h>
#include <assert.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

void create_directory_and_files(const char *dir_name, const char *file_names[], int num_files) {
    // Create directory
    if (mkdir(dir_name, 0755) != 0) {
        perror("mkdir");
        exit(EXIT_FAILURE);
    }

    // Loop through each file name and create the file with fixed content
    for (int i = 0; i < num_files; i++) {
        char *file_path = malloc(strlen(dir_name) + strlen(file_names[i]) + 2);
        strcpy(file_path, dir_name);
        strcat(file_path, "/");
        strcat(file_path, file_names[i]);

        FILE *file = fopen(file_path, "w");
        if (file == NULL) {
            perror("fopen");
            free(file_path);
            exit(EXIT_FAILURE);
        }

        const char *fixed_string = "This is a fixed string.\n";
        fputs(fixed_string, file);
        fclose(file);

        // Check if the file was created successfully
        assert(access(file_path, F_OK) == 0);

        free(file_path);
    }
}

int main() {
    const char *dir_name = "test_directory";
    const char *file_names[] = {"file1.txt", "file2.txt", "file3.txt"};
    int num_files = sizeof(file_names) / sizeof(file_names[0]);

    create_directory_and_files(dir_name, file_names, num_files);

    return 0;
}
