void insert_into_collection(const char* name, const char* value) {
    if (name != NULL && value != NULL) {
        set_env_var(name, value); // Set the new environment variable
        // Remove any existing environment variables with the same name
        unsetenv(name); // Unset the environment variable if it exists
        set_env_var(name, value); // Re-set the environment variable to ensure it's updated
    }
}

