unsigned char* ecies_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, int key_len) {
    // Initialize context for ECIES encryption
    EVP_PKEY_CTX *ctx = NULL;
    ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_ECIES_KDF, NULL);
    if (!ctx) {
        fprintf(stderr, "Error creating ECIES context\n");
        return NULL;
    }

    // Set the key and parameters for ECIES
    if (EVP_PKEY_encrypt_init(ctx) <= 0 || EVP_PKEY_CTX_set1_pkey(ctx, (const EVP_PKEY *)key) <= 0) {
        fprintf(stderr, "Error setting key for ECIES\n");
        EVP_PKEY_CTX_free(ctx);
        return NULL;
    }

    // Set the plaintext length
    if (EVP_PKEY_encrypt(ctx, NULL, &plaintext_len, plaintext, plaintext_len) <= 0) {
        fprintf(stderr, "Error setting plaintext for ECIES\n");
        EVP_PKEY_CTX_free(ctx);
        return NULL;
    }

    // Allocate memory for the ciphertext
    unsigned char *ciphertext = (unsigned char *)malloc(plaintext_len);
    if (!ciphertext) {
        fprintf(stderr, "Error allocating memory for ciphertext\n");
        EVP_PKEY_CTX_free(ctx);
        return NULL;
    }

    // Perform the encryption
    if (EVP_PKEY_encrypt(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len) <= 0) {
        fprintf(stderr, "Error encrypting data with ECIES\n");
        free(ciphertext);
        EVP_PKEY_CTX_free(ctx);
        return NULL;
    }

    // Clean up the context
    EVP_PKEY_CTX_free(ctx);

    return ciphertext;
}
