#include <vector>
#include <unordered_set>

template<typename Container>
size_t CountUniqueElements(const Container& container) {
    std::unordered_set<typename Container::value_type> unique_elements;
    for (const auto& element : container) {
        unique_elements.insert(element);
    }
    return unique_elements.size();
}

std::vector<size_t> GetUniqueElementCounts(const std::vector<std::unordered_set<int>>& containers, const std::vector<std::vector<double>>& double_containers) {
    std::vector<size_t> counts;
    for (const auto& container : containers) {
        counts.push_back(CountUniqueElements(container));
    }
    for (const auto& container : double_containers) {
        counts.push_back(CountUniqueElements(container));
    }
    return counts;
}
