#include <vector>
#include <iterator>

template<typename Iterator>
void createAdjacencyList(Iterator begin, Iterator end) {
    // Assuming the input is a pair of (vertex, list_of_neighbors)
    using Vertex = typename std::iterator_traits<Iterator>::value_type::first_type;
    using Neighbors = typename std::iterator_traits<Iterator>::value_type::second_type;

    // Create an adjacency list to store the graph
    std::vector<std::pair<Vertex, Neighbors>> adjList;

    // Iterate over the range and populate the adjacency list
    for (auto it = begin; it != end; ++it) {
        Vertex vertex = it->first;
        Neighbors neighbors = it->second;

        // Allocate memory for the new entry in the adjacency list
        adjList.emplace_back(vertex, Neighbors());

        // Set the degrees of each vertex and the heads of each vertex
        adjList.back().second = std::move(neighbors);
    }
}
