#include <cmath>
#include <string>

int EstimateStorage(double threshold, int num_angles) {
    // Constants for byte conversion
    const double KB = 1024;
    const double MB = KB * 1024;
    const double GB = MB * 1024;
    const double TB = GB * 1024;

    // Calculate the estimated storage in bytes
    double storage_bytes = threshold * num_angles;

    // Round to the nearest unit of measurement
    if (storage_bytes < KB) {
        return std::round(storage_bytes);
    } else if (storage_bytes < MB) {
        return std::round(storage_bytes / KB) * KB;
    } else if (storage_bytes < GB) {
        return std::round(storage_bytes / MB) * MB;
    } else if (storage_bytes < TB) {
        return std::round(storage_bytes / GB) * GB;
    } else {
        return std::round(storage_bytes / TB) * TB;
    }
}
