// Function to handle device discovery callback
void device_callback(UpnpDeviceInfo *device, int event, void *cookie) {
    if (event == UPNP_DISCOVERY_SEARCH_RESULT) {
        printf("Found device: %s\n", device->location);
    } else if (event == UPNP_DISCOVERY_ADVERTISEMENT_BYE) {
        printf("Device removed: %s\n", device->udn);
    }
}

// Function to discover UPnP devices
void discover_upnp_devices() {
    UpnpContext context;
    int res = 0;

    // Initialize the UPnP context
    if ((res = UpnpInit(&context)) != UPNP_E_SUCCESS) {
        printf("Error initializing UPnP: %s\n", UpnpGetErrorMessage(res));
        return;
    }

    // Start device discovery
    char *ssdp_search_target = "urn:schemas-upnp-org:device:InternetGatewayDevice:1";
    if ((res = UpnpSearch(&context, ssdp_search_target)) != UPNP_E_SUCCESS) {
        printf("Error starting device discovery: %s\n", UpnpGetErrorMessage(res));
        UpnpDeinit(&context);
        return;
    }

    // Keep the program running for a while to receive callbacks
    sleep(10);

    // Stop the search
    if ((res = UpnpSearchAsyncStop(&context)) != UPNP_E_SUCCESS) {
        printf("Error stopping device discovery: %s\n", UpnpGetErrorMessage(res));
    }

    // Deinitialize the UPnP context
    UpnpDeinit(&context);
}

int main() {
    discover_upnp_devices();
    return 0;
}
