void drawCurve(const std::vector<std::pair<double, double>>& controlPoints, float lineWidth = 1.0f, const GLfloat color[3] = {0.0f, 0.0f, 0.0f}, int numSegments = 100) {
    glLineWidth(lineWidth);
    glColor3fv(color);

    std::vector<std::pair<double, double>> points;
    for (int i = 0; i < controlPoints.size(); ++i) {
        points.push_back(controlPoints[i]);
    }
    if (!points.empty() && !(points.front().first == points.back().first && points.front().second == points.back().second)) {
        // Add the first control point at the end to handle the tail case
        points.push_back(points.front());
    }

    glBegin(GL_LINE_STRIP);
    for (int i = 0; i < numSegments; ++i) {
        double t = static_cast<double>(i) / static_cast<double>(numSegments - 1);
        double x = 0.0, y = 0.0;
        for (size_t j = 0; j < points.size(); ++j) {
            double B = binomialCoeff(points.size() - 1, j) * std::pow(1 - t, points.size() - 1 - j) * std::pow(t, j);
            x += B * points[j].first;
            y += B * points[j].second;
        }
        glVertex2d(x, y);
    }
    glEnd();
}

double binomialCoeff(int n, int k) {
    double res = 1.0;
    for (int i = 0; i < k; ++i) {
        res *= static_cast<double>(n - i);
        res /= static_cast<double>(i + 1);
    }
    return res;
}
