#include <cstring>

std::vector<unsigned char> encryptWideString(const wchar_t* input) {
    std::vector<unsigned char> encryptedData;

    size_t len = 0;
    while (input[len] != L'\0' || input[len + 1] != L'\0') {
        len++;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char byte1 = static_cast<unsigned char>(input[i] & 0xFF);
        unsigned char byte2 = static_cast<unsigned char>((input[i] >> 8) & 0xFF);
