#include <cuda_runtime.h>
#include <cuComplex.h>
#include <cufft.h>
#include <iostream>
#include <random>

#define N 256 // Size of the input array (NxN)

void checkCudaError(cudaError_t err, const char *msg) {
    if (err != cudaSuccess) {
        std::cerr << msg << ": " << cudaGetErrorString(err) << std::endl;
        exit(EXIT_FAILURE);
    }
}

int main() {
    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    // Allocate host memory for the input array
    cuComplex* h_input = (cuComplex*)malloc(N * N * sizeof(cuComplex));
    checkCudaError(cudaMallocHost(&h_input, N * N * sizeof(cuComplex)), "Failed to allocate host memory");

    // Initialize the input array with random values
    for (int i = 0; i < N * N; ++i) {
        h_input[i].x = dis(gen);
        h_input[i].y = 0.0f;
    }

    // Allocate device memory for the input array
    cuComplex* d_input;
    checkCudaError(cudaMalloc(&d_input, N * N * sizeof(cuComplex)), "Failed to allocate device memory");

    // Copy the input data from host to device
    checkCudaError(cudaMemcpy(d_input, h_input, N * N * sizeof(cuComplex), cudaMemcpyHostToDevice), "Failed to copy data to device");

    // Allocate device memory for the output array
    cuComplex* d_output;
    checkCudaError(cudaMalloc(&d_output, N * N * sizeof(cuComplex)), "Failed to allocate device memory");

    // Create a CUFFT plan for 2D FFT
    cufftHandle plan;
    checkCudaError(cufftPlan2d(&plan, N, N, CUFFT_C2C), "Failed to create CUFFT plan");

    // Execute the CUFFT forward transform
    checkCudaError(cufftExecC2C(plan, d_input, d_output, CUFFT_FORWARD), "CUFFT execution failed");

    // Copy the output data from device to host
    cuComplex* h_output = (cuComplex*)malloc(N * N * sizeof(cuComplex));
    checkCudaError(cudaMemcpy(h_output, d_output, N * N * sizeof(cuComplex), cudaMemcpyDeviceToHost), "Failed to copy data from device to host");

    // Print the first few elements of the output array (for verification)
    for (int i = 0; i < 10; ++i) {
        std::cout << h_output[i].x << " + " << h_output[i].y << "i" << std::endl;
    }

    // Cleanup
    checkCudaError(cudaFreeHost(h_input), "Failed to free host memory");
    checkCudaError(cudaFree(d_input), "Failed to free device memory");
    checkCudaError(cudaFree(d_output), "Failed to free device memory");
    checkCudaError(cufftDestroy(plan), "Failed to destroy CUFFT plan");

    return 0;
}
