#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int parse_and_transform(const char *input) {
    // Allocate memory for the parsed text
    char *parsed_text = (char *)malloc(strlen(input) + 1);
    if (!parsed_text) return -1; // Memory allocation failed

    int paragraph_count = 0;
    const char *start = input;
    const char *end = input;

    while (*end != '\0') {
        // Find the end of the current paragraph
        if (*end == '\n' && (end == start || *(end - 1) != '\r')) {
            int len = end - start + 1;
            strncpy(parsed_text + paragraph_count * len, start, len);
            parsed_text[paragraph_count * len] = '\0';
            paragraph_count++;
            start = end + 1;
        } else if (*end == '\r' && *(end + 1) == '\n') {
            int len = end - start + 2;
            strncpy(parsed_text + paragraph_count * len, start, len);
            parsed_text[paragraph_count * len] = '\0';
            paragraph_count++;
            start = end + 2;
        }
        end++;
    }

    // Handle the last paragraph if it doesn't end with a newline
    int remaining_len = end - start;
    if (remaining_len > 0) {
        char *last_paragraph = (char *)malloc(remaining_len + 1);
        strncpy(last_paragraph, start, remaining_len);
        last_paragraph[remaining_len] = '\0';
        paragraph_count++;
    }

    return paragraph_count;
}
