    // Copy non-whitespace characters to the new string
    size_t j = 0;
    for (size_t i = 0; i < len; ++i) {
        if (!isspace((unsigned char)input[i])) {
            output[j++] = input[i];
        }
    }
    output[new_len] = '\0'; // Null-terminate the new string

    return output;
