static pthread_key_t rand_key;

// Function to initialize the thread-local storage with a random value
void initRand() {
    // Seed the global RNG only once
    static int seeded = 0;
    if (!seeded) {
        srand((unsigned int)time(NULL));
        seeded = 1;
    }

    // Generate a random seed for each thread
    unsigned long seed = (unsigned long)rand();
    pthread_setspecific(rand_key, (void*)seed);
}

// Function to generate and return a random 64-bit integer
uint64_t RandUInt64() {
    // Initialize the thread-local storage if it hasn't been done yet
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    pthread_once(&once, initRand);

    // Generate a random 64-bit integer using the thread-specific seed
    unsigned long seed = (unsigned long)pthread_getspecific(rand_key);
    srand((unsigned int)seed);
    uint64_t randVal = ((uint64_t)rand() << 32) | rand();

    return randVal;
}
