import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class PdfToImage {
    public static byte[] generatePPMImage(PDDocument document, int pageNumber, int displayWidth, int displayHeight) throws IOException {
        PDFRenderer pdfRenderer = new PDFRenderer(document);
        BufferedImage bufferedImage = pdfRenderer.renderImageWithDPI(pageNumber, 300, org.apache.pdfbox.rendering.ImageType.RGB);

        // Resize the image to fit within the specified display size
        int targetWidth = displayWidth;
        int targetHeight = displayHeight;
        if (bufferedImage.getWidth() > targetWidth || bufferedImage.getHeight() > targetHeight) {
            ResampleOp resampleOp = new ResampleOp(targetWidth, targetHeight);
            bufferedImage = resampleOp.filter(bufferedImage, null);
        }

        // Convert BufferedImage to byte array
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "png", baos);
        return baos.toByteArray();
    }
}
