// Function to perform vertical flip on a 2D array of pixels
template<typename T>
void flipVertical(T** image, int width, int height) {
    if (!image || width <= 0 || height <= 0) {
        return;
    }

    // Allocate temporary memory for the flipped image
    T* temp = static_cast<T*>(std::malloc(width * height * sizeof(T)));
    if (!temp) {
        return;
    }

    // Copy data from input array to temporary array
    for (int y = 0; y < height; ++y) {
        std::memcpy(&temp[y * width], &image[height - y - 1][0], width * sizeof(T));
    }

    // Copy data back to input array in the correct order
    for (int y = 0; y < height; ++y) {
        std::memcpy(&image[y][0], &temp[y * width], width * sizeof(T));
    }

    // Free temporary memory
    std::free(temp);
}
