void handle_client(int client_fd, MessageQueue& message_queue) {
    char buffer[1024];
    while (true) {
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer), 0);
        if (bytes <= 0) {
            close(client_fd);
            break;
        }
        Message msg{client_fd, std::string(buffer, bytes)};
        message_queue.push(msg);
    }
}

int main() {
    uint16_t port = 8080;
    int sfd = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sfd == -1) {
        perror("socket()");
        return EXIT_FAILURE;
    }

    int yes = 1;
    if (setsockopt(sfd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(int)) == -1) {
        perror("setsockopt()");
        close(sfd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in saddr;
    memset((void *)&saddr, 0, sizeof(saddr));
    saddr.sin_family = AF_INET;
    saddr.sin_addr.s_addr = htonl(INADDR_ANY);
    saddr.sin_port = htons(port);

    if (bind(sfd, (struct sockaddr *)&saddr, sizeof(saddr)) == -1) {
        perror("bind()");
        close(sfd);
        return EXIT_FAILURE;
    }

    if (listen(sfd, 5) == -1) {
        perror("listen()");
        close(sfd);
        return EXIT_FAILURE;
    }

    MessageQueue message_queue;
    std::vector<std::thread> threads;

    while (true) {
        int client_fd = accept(sfd, nullptr, nullptr);
        if (client_fd == -1) {
            perror("accept()");
            continue;
        }
        threads.emplace_back(handle_client, client_fd, std::ref(message_queue));
    }

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    close(sfd);
    return EXIT_SUCCESS;
}
