#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* generateInsertSQL(const char* table_name, const char* feature, const char* geometry_column, const char* fid_column) {
    // Allocate memory for the SQL command string
    size_t sql_length = strlen("INSERT INTO ") + strlen(table_name) + strlen(" (") + 
                        (geometry_column ? strlen(geometry_column) : 0) + strlen(", ") + 
                        (fid_column ? strlen(fid_column) : 0) + strlen(") VALUES ('") + 
                        strlen(feature) + strlen("');");
    char* sql = (char*)malloc(sql_length);

    // Check if memory allocation was successful
    if (!sql) {
        return NULL;
    }

    // Start building the SQL command string
    strcpy(sql, "INSERT INTO ");
    strcat(sql, table_name);
    strcat(sql, " (");

    // Append geometry column name if provided
    if (geometry_column) {
        strcat(sql, geometry_column);
        strcat(sql, ", ");
    }

    // Append FID column name if provided
    if (fid_column) {
        strcat(sql, fid_column);
        strcat(sql, ") VALUES ('");
    } else {
        strcat(sql, ") VALUES ('");
    }

    // Append the feature string
    strcat(sql, feature);
    strcat(sql, "');");

    return sql;
}

