#include <stdio.h>
#include <stdint.h>
#include <libcdio/cdio.h>

char* calculate_discid(CDIO_CD_t *cd) {
    static char discid[9]; // 8 characters + null terminator for DISCID format
    uint64_t sum = 0;
    track_t i;
    cdio_trackstatus_t status;

    for (i = 1; i <= cd->numtracks; i++) {
        if ((status = cdio_get_audio_track_lba(cd, i, &sum)) != TRKSTS_AUDIO) {
            fprintf(stderr, "Error: Track %d is not audio\n", i);
            return NULL;
        }
    }

    sum /= 0xff;
    snprintf(discid, sizeof(discid), "%08lx", (unsigned long)sum << 24);

    printf("Computed DISCID: %s\n", discid);
    return discid;
}
