unsigned char** decompress_jpeg(const unsigned char* jpeg_buffer, int width, int height) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    // Initialize the JPEG decompression object
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    // Specify data source
    jpeg_mem_src(&cinfo, (unsigned char*)jpeg_buffer, strlen((char*)jpeg_buffer));

    // Read file header
    jpeg_read_header(&cinfo, TRUE);

    // Calculate output dimensions
    jpeg_calc_output_dimensions(&cinfo);

    // Start decompression
    jpeg_start_decompress(&cinfo);

    // Allocate memory for the image data
    unsigned char** image = (unsigned char**)malloc(height * sizeof(unsigned char*));
    for (int i = 0; i < height; i++) {
        image[i] = (unsigned char*)malloc(width * 3 * sizeof(unsigned char));
    }

    // Read the data into the allocated memory
    int row_stride = width * cinfo.num_components;
    JSAMPARRAY buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, row_stride, 1);

    while (cinfo.output_scanline < cinfo.output_height) {
        jpeg_read_scanlines(&cinfo, buffer, 1);
        for (int i = 0; i < width * cinfo.num_components; i++) {
            image[cinfo.output_scanline - 1][i] = buffer[0][i];
        }
    }

    // Finish decompression and release memory
    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    return image;
}
