#include <vector>
#include <cstdint>
#include <fstream>
#include <iostream>

std::vector<std::vector<uint8_t>> load_descriptors(const std::vector<std::string>& filePaths, bool includeAlpha) {
    std::vector<std::vector<uint8_t>> descriptors;
    uint32_t totalDescriptors = 0;

    for (const auto& filePath : filePaths) {
        std::ifstream file(filePath, std::ios::binary);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filePath << std::endl;
            continue;
        }

        // Read the descriptors from the file and store them in a 2D vector
        std::vector<uint8_t> descriptor;
        uint8_t temp;
        while (file.read(reinterpret_cast<char*>(&temp), sizeof(temp))) {
            descriptor.push_back(temp);
        }

        descriptors.push_back(descriptor);
        totalDescriptors += descriptor.size();
    }

    // Optionally include alpha values if the flag is set
    if (includeAlpha) {
        for (auto& descriptor : descriptors) {
            descriptor.resize(descriptor.size() + 2, 0); // Add 2 additional dimensions for alpha values
        }
    }

    return descriptors;
}
