#include <vector>
#include <unordered_map>

std::unordered_map<int, int> countFrequencies(const std::vector<int>& nums) {
    if (nums.empty()) return {};

    // Find the maximum value in the list to determine the range for counting sort
    int maxVal = *max_element(nums.begin(), nums.end());

    // Create a frequency array to store the count of each number
    std::vector<int> freq(maxVal + 1, 0);

    // Count the occurrences of each number in the input list
    for (int num : nums) {
        freq[num]++;
    }

    // Create a map to store the result with numbers as keys and their frequencies as values
    std::unordered_map<int, int> frequencyMap;

    // Populate the map with the counts from the frequency array
    for (int i = 0; i <= maxVal; ++i) {
        if (freq[i] > 0) {
            frequencyMap[i] = freq[i];
        }
    }

    return frequencyMap;
}
