#define MAX_ROWS 100
#define MAX_COLS 100

void create_board(char* input, char board[MAX_ROWS][MAX_COLS], int* rows, int* cols) {
    *rows = strlen(input);
    *cols = 0;

    // Find the maximum number of characters in a row
    for (int i = 0; i < *rows; i++) {
        if (*cols < strlen(&input[i])) {
            *cols = strlen(&input[i]);
        }
    }

    // Initialize the board with spaces
    for (int i = 0; i < *rows; i++) {
        for (int j = 0; j < *cols; j++) {
            board[i][j] = ' ';
        }
    }

    // Replace each occurrence of 'R' with '/' and update the board
    int row = 0, col = 0;
    for (int i = 0; input[i] != '\0'; i++) {
        if (input[i] == 'R') {
            board[row][col] = '/';
            // Keep track of the position of 'R'
            printf("Found 'R' at row %d, column %d\n", row + 1, col + 1);
        } else {
            board[row][col] = input[i];
        }

        if (input[i] == '\0') break; // Avoid going out of bounds

        col++;
        if (col >= *cols) {
            col = 0;
            row++;
        }
    }
}

int main() {
    char input[100];
    char board[MAX_ROWS][MAX_COLS];
    int rows, cols;

    // Read the string from standard input
    printf("Enter a string: ");
    fgets(input, sizeof(input), stdin);
    input[strcspn(input, "\n")] = '\0'; // Remove newline character if present

    // Create the board
    create_board(input, board, &rows, &cols);

    // Print the board to standard output
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%c", board[i][j]);
        }
        printf("\n");
    }

    return 0;
}
