#include <vector>
#include <string>
#include <sstream>
#include <iostream>

int tokenize(const std::string &input, const std::string &delimiter, const std::string &specialValue, std::vector<std::string> &tokens) {
    tokens.clear();
    size_t start = 0;
    size_t end = input.find(delimiter);
    while (end != std::string::npos) {
        std::string token = input.substr(start, end - start);
        if (token != specialValue) {
            tokens.push_back(token);
        }
        start = end + delimiter.length();
        end = input.find(delimiter, start);
    }
    std::string lastToken = input.substr(start, end);
    if (lastToken != specialValue) {
        tokens.push_back(lastToken);
    }
    return tokens.size();
}
