#include <CL/cl.hpp>
#include <iostream>
#include <vector>

// Function to create and execute a kernel with OpenCL
std::vector<float> run_opencl_kernel(const std::vector<float>& input, const std::vector<float>& output, const std::vector<float>& temp) {
    // Platform selection
    std::vector<cl::Platform> platforms;
    cl::Platform::get(&platforms);
    auto platform = platforms.front();

    // Device selection
    std::vector<cl::Device> devices;
    platform.getDevices(CL_DEVICE_TYPE_GPU, &devices);
    auto device = devices.front();

    // Context creation
    cl::Context context({device});

    // Command queue creation
    cl::CommandQueue queue(context, device);

    // Kernel code (example)
    const char* kernelSource = R"(
        __kernel void process(__global const float* input, __global float* output, __local float* temp) {
            int id = get_global_id(0);
            output[id] = input[id] + temp[id];
        }
    )";

    // Program creation and kernel compilation
    cl::Program program(context, kernelSource);
    if (program.build({device}) != CL_SUCCESS) {
        std::cerr << "Error building: " << program.getBuildInfo<CL_PROGRAM_BUILD_LOG>(device) << std::endl;
        exit(1);
    }

    // Memory objects allocation
    cl::Buffer inputBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, sizeof(float) * input.size(), input.data());
    cl::Buffer outputBuffer(context, CL_MEM_WRITE_ONLY, sizeof(float) * output.size());
    cl::Buffer tempBuffer(context, CL_MEM_READ_WRITE | CL_MEM_COPY_HOST_PTR, sizeof(float) * temp.size(), temp.data());

    // Kernel execution
    cl::Kernel kernel(program, "process");
    kernel.setArg(0, inputBuffer);
    kernel.setArg(1, outputBuffer);
    kernel.setArg(2, tempBuffer);

    queue.enqueueNDRangeKernel(kernel, cl::NullRange, cl::NDRange(input.size()), cl::NullRange);
    queue.finish();

    // Copy data back to host memory
    std::vector<float> result(output.size());
    queue.enqueueReadBuffer(outputBuffer, CL_TRUE, 0, sizeof(float) * output.size(), result.data());

    return result;
}
