struct HeightMap {
    int width;
    int height;
    std::vector<int> data;
};

HeightMap* readBitmapAsHeightMap(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return nullptr;
    }

    // Read the BMP signature to ensure it's a valid bitmap file
    char signature[2];
    file.read(signature, 2);
    if (signature[0] != 'B' || signature[1] != 'M') {
        std::cerr << "Not a valid bitmap file: " << filename << std::endl;
        file.close();
        return nullptr;
    }

    // Read the BMP file header and DIB header (BITMAPINFOHEADER)
    int fileSize, pixelDataOffset;
    file.read(reinterpret_cast<char*>(&fileSize), 4);
    file.ignore(4); // Skip the app-specific data
    file.read(reinterpret_cast<char*>(&pixelDataOffset), 4);

    int headerSize, width, height, planes, bitsPerPixel;
    file.read(reinterpret_cast<char*>(&headerSize), 4);
    file.read(reinterpret_cast<char*>(&width), 4);
    file.read(reinterpret_cast<char*>(&height), 4);
    file.read(reinterpret_cast<char*>(&planes), 2);
    file.read(reinterpret_cast<char*>(&bitsPerPixel), 2);
    file.ignore(24); // Skip the rest of the header

    if (bitsPerPixel != 24) {
        std::cerr << "Only 24-bit bitmaps are supported: " << filename << std::endl;
        file.close();
        return nullptr;
    }

    // Allocate memory for the height map
    HeightMap* heightMap = new HeightMap{width, height, std::vector<int>(width * height)};

    // Read pixel data and convert to height values
    int padding = (4 - (width * 3) % 4) % 4; // Calculate the padding for each row
    char* buffer = new char[width * 3 + padding];
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            file.read(buffer, 3); // Read the BGR values
            int b = static_cast<unsigned char>(buffer[0]);
            int g = static_cast<unsigned char>(buffer[1]);
            int r = static_cast<unsigned char>(buffer[2]);
            heightMap->data[y * width + x] = (r + g + b) / 3; // Average the color values as height
        }
        file.ignore(padding); // Skip the padding bytes
    }

    delete[] buffer;
    file.close();
    return heightMap;
}
