std::pair<int, bool> iterativeSubsetSelection(const std::vector<int>& numbers, int target) {
    srand(time(nullptr)); // Seed the random number generator
    const int maxIterations = 1000; // Maximum number of iterations to prevent infinite loops
    int bestSum = INT_MAX;
    bool targetReached = false;

    for (int iteration = 0; iteration < maxIterations; ++iteration) {
        std::vector<int> selectedNumbers;
        int currentSum = 0;

        // Randomly select numbers until the sum is close to or equal to the target
        while (currentSum < target && !selectedNumbers.empty()) {
            int index = rand() % selectedNumbers.size();
            currentSum += selectedNumbers[index];
            std::swap(selectedNumbers[index], selectedNumbers.back());
            selectedNumbers.pop_back();
        }

        // Check if the sum is close to the target and update the best result found so far
        if (std::abs(currentSum - target) < std::abs(bestSum - target)) {
