#include <GL/glew.h>
#include <iostream>
#include <fstream>
#include <string>
#include <vector>

// Function to create a shader object, compile it, and return the shader if successful or throw an error message if compilation fails.
GLuint CreateShader(GLenum shaderType, const std::string& source) {
    // Create the shader object
    GLuint shader = glCreateShader(shaderType);
    if (shader == 0) {
        std::cerr << "Error creating shader object." << std::endl;
        return 0;
    }

    // Assign the source code to the shader and compile it
    const char* source_ptr = source.c_str();
    glShaderSource(shader, 1, &source_ptr, nullptr);
    glCompileShader(shader);

    // Check for compilation errors
    GLint status;
    glGetShaderiv(shader, GL_COMPILE_STATUS, &status);
    if (status == GL_FALSE) {
        GLint infoLogLength;
        glGetShaderiv(shader, GL_INFO_LOG_LENGTH, &infoLogLength);
        std::vector<char> errorMessage(infoLogLength + 1);
        glGetShaderInfoLog(shader, infoLogLength, nullptr, errorMessage.data());
        std::cerr << "Shader compilation failed: " << errorMessage.data() << std::endl;
        glDeleteShader(shader); // Clean up the shader object
        return 0;
    }

    return shader;
}
