std::vector<std::wstring> listFilesInDirectory(const std::wstring& directoryPath, bool sorted = false) {
    std::vector<std::wstring> files;
    HANDLE hFind;
    WIN32_FIND_DATA data;

    // Combine the directory path with a wildcard to find all files in the directory
    std::wstring searchPath = directoryPath + L"\\*";
    hFind = FindFirstFile(searchPath.c_str(), &data);

    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            // Skip "." and ".." directories
            if (wcscmp(data.cFileName, L".") == 0 || wcscmp(data.cFileName, L"..") == 0) {
                continue;
            }
            std::wstring fileName = data.cFileName;
            files.push_back(fileName);
        } while (FindNextFile(hFind, &data));
        FindClose(hFind);
    }

    // Optionally sort the list of files
    if (sorted) {
        std::sort(files.begin(), files.end());
    }

    return files;
}
