char* generate_signature(const char* message, const char* secret_key) {
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len;

    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!ctx) {
        return NULL;
    }

    HMAC_Init_ex(ctx, secret_key, strlen(secret_key), EVP_sha1(), NULL);
    HMAC_Update(ctx, (unsigned char*)message, strlen(message));
    HMAC_Final(ctx, digest, &digest_len);
    HMAC_CTX_free(ctx);

    BIO *bio = BIO_new(BIO_s_mem());
    if (!bio) {
        return NULL;
    }

    BIO_write(bio, digest, digest_len);
    BUF_MEM *buf_mem;
    BIO_get_mem_ptr(bio, &buf_mem);

    char *base64_signature = (char *)malloc(buf_mem->length * 2 + 1);
    if (!base64_signature) {
        BIO_free(bio);
        return NULL;
    }

    base64_signature[0] = '\0';
    EVP_EncodeBlock((unsigned char*)base64_signature, buf_mem->data, buf_mem->length);

    BIO_free(bio);
    return base64_signature;
}
