std::string kdf2(const std::string& password, const std::string& master_key, size_t output_length) {
    // Convert password and master key to byte arrays
    const unsigned char* p = reinterpret_cast<const unsigned char*>(password.c_str());
    const unsigned char* mk = reinterpret_cast<const unsigned char*>(master_key.c_str());

    // Initialize context for SHA-1 hash function
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create SHA-1 context");
    }

    // Start the hash computation
    if (EVP_DigestInit_ex(ctx, EVP_sha1(), nullptr) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to initialize SHA-1 context");
    }

    // Update the hash computation with the master key
    if (EVP_DigestUpdate(ctx, mk, master_key.size()) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to update SHA-1 context with master key");
    }

    // Update the hash computation with the password
    if (EVP_DigestUpdate(ctx, p, password.size()) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to update SHA-1 context with password");
    }

    // Finalize the hash computation and store the result in a buffer
    unsigned char* digest = new unsigned char[SHA_DIGEST_LENGTH];
    if (EVP_DigestFinal_ex(ctx, digest, nullptr) != 1) {
        EVP_MD_CTX_free(ctx);
        delete[] digest;
        throw std::runtime_error("Failed to finalize SHA-1 computation");
    }

    // Clean up the context
    EVP_MD_CTX_free(ctx);

    // Convert the resulting hash to a hexadecimal string
    std::string derived_key = "";
    for (size_t i = 0; i < SHA_DIGEST_LENGTH && derived_key.size() < output_length; ++i) {
        char buffer[3];
        sprintf(buffer, "%02x", digest[i]);
        derived_key += buffer;
    }

    // Clean up the allocated memory for the digest
    delete[] digest;

    return derived_key.substr(0, output_length);
}

BOOST_PYTHON_MODULE(kdf2) {
    boost::python::def("kdf2", &kdf2);
}
