int findBestCombination(const std::vector<Pair>& pairs, int target) {
    std::srand(std::time(0)); // Seed for random number generation
    const int maxIterations = 1000; // Number of iterations to run the algorithm

    int bestValue = -1;

    for (int iteration = 0; iteration < maxIterations; ++iteration) {
        std::vector<Pair> currentSelection = pairs;
        int currentTotalValue = 0;

        // Randomly select values based on a criteria
        for (auto& pair : currentSelection) {
            if (!pair.selected && ((std::rand() % 2) == 0)) {
                pair.selected = true;
                currentTotalValue += pair.value;
            }
        }

        // Check if the current total value is within the target and better than the best found so far
        if (currentTotalValue <= target && currentTotalValue > bestValue) {
            bestValue = currentTotalValue;
