#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>

// Function to perform convolution operation on an input image
std::vector<std::vector<int>> convolve(const std::vector<std::vector<int>>& image, const std::vector<std::vector<int>>& filter, int stride) {
    int imgHeight = image.size();
    int imgWidth = image[0].size();
    int filtHeight = filter.size();
    int filtWidth = filter[0].size();
    int outputHeight = (imgHeight - filtHeight) / stride + 1;
    int outputWidth = (imgWidth - filtWidth) / stride + 1;

    std::vector<std::vector<int>> output(outputHeight, std::vector<int>(outputWidth, 0));

    for (int i = 0; i < outputHeight; ++i) {
        for (int j = 0; j < outputWidth; ++j) {
            int sum = 0;
            for (int x = 0; x < filtHeight; ++x) {
                for (int y = 0; y < filtWidth; ++y) {
                    sum += image[i * stride + x][j * stride + y] * filter[x][y];
                }
            }
            output[i][j] = sum;
        }
    }

    return output;
}

// Function to allocate memory for the input, resized, and output buffers
std::vector<std::vector<int>> allocateBuffers(int height, int width) {
    std::vector<std::vector<int>> buffer(height, std::vector<int>(width, 0));
    return buffer;
}

// Main function to test the convolution operation
int main() {
    srand(time(NULL)); // Seed for random number generation

    int imgHeight = 5;
    int imgWidth = 5;
    std::vector<std::vector<int>> image = allocateBuffers(imgHeight, imgWidth);

    // Initialize the image with random values
    for (auto& row : image) {
        for (auto& pixel : row) {
            pixel = rand() % 256; // Random value between 0 and 255
        }
    }

    int filtHeight = 3;
    int filtWidth = 3;
    std::vector<std::vector<int>> filter = allocateBuffers(filtHeight, filtWidth);

    // Initialize the filter with random values
    for (auto& row : filter) {
        for (auto& pixel : row) {
            pixel = rand() % 5 - 2; // Random value between -2 and 2
        }
    }

    int bias = rand() % 10 - 5; // Random bias value between -5 and 5

    std::vector<std::vector<int>> output = convolve(image, filter, 1);

    // Add bias to the output
    for (auto& row : output) {
        for (auto& pixel : row) {
            pixel += bias;
        }
    }

    std::cout << "Input Image:\n";
