typedef struct {
    uint32_t id[3];
} DocID;

DocID* generateRandomDocIDs(size_t n) {
    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for the list of doc IDs
    DocID* docIDs = (DocID*)malloc(n * sizeof(DocID));
    if (!docIDs) {
        return NULL; // Return NULL on allocation failure
    }

    // Generate n random 6-byte doc IDs
    for (size_t i = 0; i < n; ++i) {
        for (int j = 0; j < 3; ++j) {
            docIDs[i].id[j] = rand(); // Generate a random 32-bit integer
        }
    }

    return docIDs;
}
