#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

typedef struct {
    char **tokens;
    int count;
} TokenList;

void initTokenList(TokenList *list) {
    list->tokens = NULL;
    list->count = 0;
}

void addToken(TokenList *list, const char *token) {
    list->count++;
    list->tokens = (char **)realloc(list->tokens, list->count * sizeof(char *));
    list->tokens[list->count - 1] = strdup(token);
}

void freeTokenList(TokenList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->tokens[i]);
    }
    free(list->tokens);
}

TokenList parseMultilineString(const char *input) {
    TokenList list;
    initTokenList(&list);
    const char *p = input;
    while (*p != '\0') {
        // Skip leading whitespace
        while (isspace((unsigned char)*p)) {
            p++;
        }

        if (*p == '\n' || *p == '\r' || *p == '#' || *p == '\0') {
            // End of line or comment, skip to next line
            while (*p != '\0' && *p != '\n' && *p != '\r') {
                p++;
            }
            if (*p == '\n') {
                addToken(&list, "\n");
                p++;
            } else if (*p == '\r') {
                addToken(&list, "\r");
                p++;
                if (*p == '\n') {
                    p++;
                }
            }
        } else if (*p == '"') {
            // Quoted string
            const char *start = p;
            p++;
            while (*p != '"' && *p != '\0' && *p != '\n' && *p != '\r') {
                p++;
            }
            if (*p == '"') {
                size_t len = p - start;
                char *token = (char *)malloc(len + 1);
                strncpy(token, start + 1, len);
                token[len] = '\0';
                addToken(&list, token);
                free(token);
                p++;
            } else {
                // Unterminated string
                break;
            }
        } else if (isdigit((unsigned char)*p) || *p == '-') {
            // Number or negative sign
            const char *start = p;
            while (isdigit((unsigned char)*p) || *p == '-' || *p == '.') {
                p++;
            }
            size_t len = p - start;
            char *token = (char *)malloc(len + 1);
            strncpy(token, start, len);
            token[len] = '\0';
            addToken(&list, token);
            free(token);
        } else {
            // Other characters, just take the whole line or comment
            const char *start = p;
            while (*p != '\n' && *p != '\r' && *p != '#' && *p != '\0') {
                p++;
            }
            size_t len = p - start;
            char *token = (char *)malloc(len + 1);
            strncpy(token, start, len);
            token[len] = '\0';
            addToken(&list, token);
            free(token);
        }
    }
    return list;
}
