void extract_server_credentials(const char* input, ServerCredentials* credentials) {
    const char* colon = strchr(input, ':');
    if (colon == NULL || colon == input) {
        // Invalid format: no ':' or it's at the start
        printf("Invalid server name and password format\n");
        return;
    }
    
    strncpy(credentials->server_name, input, colon - input);
    credentials->server_name[colon - input] = '\0';
    
    const char* next_char = colon + 1;
    if (*next_char == ':') {
        next_char++; // Skip the second ':'
    }
    
    strcpy(credentials->password, next_char);
}

