#include <ctype.h>
#include <string.h>

int case_insensitive_match(const char* str1, const char* str2) {
    while (*str1 && *str2) {
        if (tolower(*str1) != tolower(*str2)) {
            return 0; // Characters do not match in a case-insensitive manner
        }
        str1++;
        str2++;
    }
    // Both strings should be fully traversed for a perfect match
    return *str1 == '\0' && *str2 == '\0';
}
