struct Option {
    std::string name;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& input) {
    std::vector<Option> options;
    std::istringstream iss(input);
    std::string token;

    while (iss >> token) {
        size_t pos = token.find('=');
        if (pos == std::string::npos || pos == 0 || pos == token.size() - 1) {
            throw std::runtime_error("Malformed option: " + token);
        }

        Option opt;
        opt.name = token.substr(0, pos);
        opt.value = token.substr(pos + 1);

        options.push_back(opt);
    }

    return options;
}

