void percolation_step(std::vector<int>* sites, double probability, int time_step) {
    // Seed the random number generator with the current time
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    // Randomly select a site from the vector
    int index = std::rand() % sites->size();
    int& site = (*sites)[index];

    // Apply percolation rule based on the site's index and time step
    if (site == 0 && probability > static_cast<double>(std::rand()) / RAND_MAX) {
        site = time_step;
    } else if (site != 0 && site < time_step) {
        site = 0;
    }
}
