#include <cstring>
#include <iostream>

std::vector<std::string> extract_url_components(const std::string& url) {
    std::vector<std::string> components;
    size_t protocol_end = url.find("://");
    if (protocol_end != std::string::npos) {
        components.push_back(url.substr(0, protocol_end));
        size_t host_start = protocol_end + 3;
        size_t port_start = url.find(':', host_start);
        size_t path_start = url.find('/', host_start);

        if (port_start == std::string::npos) {
            components.push_back(url.substr(host_start, path_start - host_start));
        } else {
            components.push_back(url.substr(host_start, port_start - host_start));
            size_t port_end = url.find('/', port_start);
            if (port_end == std::string::npos) {
                components.push_back(url.substr(port_start + 1));
            } else {
                components.push_back(url.substr(port_start + 1, port_end - port_start - 1));
            }
        }
    } else {
        // No protocol found, return an error or handle as needed
        std::cerr << "Invalid URL: Missing protocol" << std::endl;
    }
    return components;
}
