SkDashPathEffect* CreateDashPathEffect(const SkScalar intervals[], int count, SkScalar phase, bool scaleToFit) {
    // Allocate memory for the SkDashPathEffect struct
    SkDashPathEffect* dashPathEffect = (SkDashPathEffect*)sk_malloc_throw(sizeof(SkDashPathEffect));

    // Initialize fIntervals and fCount fields
    dashPathEffect->fIntervals = sk_malloc_throw(count * sizeof(SkScalar));
    memcpy(dashPathEffect->fIntervals, intervals, count * sizeof(SkScalar));
    dashPathEffect->fCount = count;

