// Define Haab calendar constants
#define HAAB_DAYS 365
#define MONTHS 19
#define DAYS_PER_MONTH 20

// Function to convert Haab date to days since a reference date
int haab_to_days(int day, int month, int year) {
    return (year * HAAB_DAYS + month * DAYS_PER_MONTH + day);
}

// Function to calculate the number of days between two dates in Haab calendar
int days_between_dates(int start_day, int start_month, int start_year, int end_day, int end_month, int end_year) {
