template <typename Container>
void foreach_loop(Container& container, bool (*callback)(typename Container::value_type&, void*), void* data) {
    if (container.empty()) {
        return;
    }

    auto it = container.begin();
    while (it != container.end()) {
        if (!callback(*it, data)) {
            break;
        }
        ++it;
    }
}
