struct Person {
    char CURP[10];
    char celular[10];
    char partido[5];
};

int main() {
    int sock;
    struct sockaddr_in server;
    struct Person person = {"CURP123", "1234567890", "PARTY"};
    char buffer[1024] = {0};

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        exit(EXIT_FAILURE);
    }

    server.sin_addr.s_addr = inet_addr("127.0.0.1"); // Server IP address
    server.sin_family = AF_INET;
    server.sin_port = htons(8080); // Server port

    // Connect to server
    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Connection failed");
        exit(EXIT_FAILURE);
    }

    // Send data
    send(sock, &person, sizeof(struct Person), 0);
    printf("Data sent: CURP=%s, celular=%s, partido=%s\n", person.CURP, person.celular, person.partido);

    // Receive response
    int valread = recv(sock, buffer, sizeof(buffer), 0);
    if (valread > 0) {
        printf("Response received: %s\n", buffer);
    } else {
        perror("Receive failed");
    }

    // Close socket
    close(sock);
    return 0;
}
