#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#include <cstring>

char* my_vsnprintf(const char* format, va_list args) {
    // Estimate the size needed for the buffer
    int estimated_size = vsnprintf(nullptr, 0, format, args);
    if (estimated_size <= 0) return nullptr;

    // Allocate memory for the result string
    char* result = new char[estimated_size + 1];
    if (!result) return nullptr;

    // Format the string and store it in the allocated buffer
    int written_chars = vsnprintf(result, estimated_size + 1, format, args);
    if (written_chars <= 0) {
        delete[] result;
        return nullptr;
    }

    return result;
}

char* my_asnprintf(const char* format, ...) {
    va_list args;
    va_start(args, format);
    char* result = my_vsnprintf(format, args);
    va_end(args);
    return result;
}
