std::vector<std::vector<float>> compute_differences(const std::vector<std::vector<float>>& array) {
    int rows = array.size();
    int cols = array[0].size();
    std::vector<std::vector<float>> differences(rows, std::vector<float>(cols, 0.0f));

    // Compute differences for all directions
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (i > 0) differences[i][j] -= array[i - 1][j]; // North
            if (i < rows - 1) differences[i][j] += array[i + 1][j]; // South
            if (j > 0) differences[i][j] -= array[i][j - 1]; // West
            if (j < cols - 1) differences[i][j] += array[i][j + 1]; // East
            if (i > 0 && j > 0) differences[i][j] -= array[i - 1][j - 1]; // North-West
            if (i > 0 && j < cols - 1) differences[i][j] += array[i - 1][j + 1]; // North-East
            if (i < rows - 1 && j > 0) differences[i][j] -= array[i + 1][j - 1]; // South-West
            if (i < rows - 1 && j < cols - 1) differences[i][j] += array[i + 1][j + 1]; // South-East
        }
    }

    return differences;
}
