#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <string>

struct Point {
    double x;
    double y;
};

std::vector<Point> readDataset(const std::string& filename) {
    std::ifstream file(filename);
    std::vector<Point> dataset;
    if (!file.is_open()) {
        std::cerr << "Error: Could not open the file." << std::endl;
        return dataset;
    }

    double x, y;
    while (file >> x >> y) {
        dataset.push_back({x, y});
    }
    file.close();
    return dataset;
}

void linearRegression(const std::vector<Point>& points, double& slope, double& intercept) {
    if (points.empty()) {
        std::cerr << "Error: No data points." << std::endl;
        return;
    }

    int n = points.size();
    double sumX = 0, sumY = 0, sumXY = 0, sumXX = 0;

    for (const auto& point : points) {
        sumX += point.x;
        sumY += point.y;
        sumXY += point.x * point.y;
        sumXX += point.x * point.x;
    }

    slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    intercept = (sumY - slope * sumX) / n;
}

int main() {
    std::string filename;
    std::cout << "Enter the filename of the dataset: ";
    std::cin >> filename;

    std::vector<Point> dataset = readDataset(filename);
    if (dataset.empty()) {
        return 1;
    }

    double slope, intercept;
    linearRegression(dataset, slope, intercept);

    std::cout << "Number of data points: " << dataset.size() << std::endl;
    std::cout << "Linear regression results:" << std::endl;
    std::cout << "Slope: " << slope << ", Intercept: " << intercept << std::endl;

    return 0;
}
