#include <cstring> // for strlen and strncpy
#include <new>     // for bad_alloc

char* string_copy(const char* source) {
    size_t length = std::strlen(source);
    char* allocated_memory = new (std::nothrow) char[length + 1];

    if (!allocated_memory) {
        return nullptr; // Return null on allocation failure
    }

    std::strncpy(allocated_memory, source, length + 1);
    return allocated_memory;
}
