#include <iostream>
#include <stdexcept>

class DynamicArray {
private:
    int* array;
    int capacity;
    int size;

public:
    DynamicArray() : array(new int[1]), capacity(1), size(0) {}

    ~DynamicArray() {
        delete[] array;
    }

    void push_back(int elem) {
        if (size == capacity) {
            // Double the capacity
            int* newArray = new int[2 * capacity];
            for (int i = 0; i < size; ++i) {
                newArray[i] = array[i];
            }
            delete[] array;
            array = newArray;
            capacity *= 2;
        }
        array[size++] = elem;
    }

    int operator[](int index) const {
        if (index < 0 || index >= size) {
            throw std::out_of_range("Index out of range");
        }
        return array[index];
    }
};

int main() {
    DynamicArray arr;
    arr.push_back(10);
    arr.push_back(20);
    arr.push_back(30);

    std::cout << "Element at index 0: " << arr[0] << std::endl;
    std::cout << "Element at index 1: " << arr[1] << std::endl;
    std::cout << "Element at index 2: " << arr[2] << std::endl;

    return 0;
}
