class MyClass {
public:
    MyClass(int value) : data(value) {}
    ~MyClass() { ++destructorCalls; }
    int getData() const { return data; }
    static int getDestructorCalls() { return destructorCalls; }
private:
    int data;
    static int destructorCalls;
};

int MyClass::destructorCalls = 0;

void testAutoPtr() {
    std::auto_ptr<MyClass> ptr(new MyClass(42));
    assert(MyClass::getDestructorCalls() == 0); // Check that destructor hasn't been called yet
    ptr.reset(); // Reset auto_ptr, should call the destructor
    assert(MyClass::getDestructorCalls() == 1); // Check that destructor has been called
    ptr.reset(new MyClass(99)); // Reset auto_ptr again, should call the destructor for the old object and then create a new one
    assert(MyClass::getDestructorCalls() == 2); // Check that destructor has been called again
}

int main() {
    testAutoPtr();
    return 0;
}
