int derive_key(const char *password, const char *salt, uint8_t *derived_key, size_t derived_key_len) {
    // Initialize the OpenSSL context for PBKDF2
    EVP_PKEY_CTX *pctx = NULL;
    int ret = -1;

    pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_PBKDF2, NULL);
    if (!pctx) {
        goto cleanup;
    }

    // Set the PBKDF2 parameters: SHA-1 as the digest, 1000 iterations, and empty password/salt
    if (EVP_PKEY_CTX_set_scrypt_hmac_sha256(pctx, 1000, 8, 1) <= 0 ||
        EVP_PKEY_CTX_set_hkdf_md(pctx, EVP_sha1()) <= 0 ||
        EVP_PKEY_CTX_set1_scrypt_salt(pctx, (unsigned char *)salt, strlen(salt)) <= 0 ||
        EVP_PKEY_CTX_set1_hkdf_key(pctx, (unsigned char *)password, strlen(password)) <= 0) {
        goto cleanup;
    }

    // Derive the key
    if (EVP_PKEY_derive(pctx, derived_key, &derived_key_len) <= 0) {
        goto cleanup;
    }

    ret = 0; // Success

cleanup:
    EVP_PKEY_CTX_free(pctx);
    return ret;
}
