#include <stdlib.h>
#include <math.h>

typedef struct {
    float x, y, z;
} Point;

Point* compute_normals(Point* points, int num_points) {
    Point* normals = (Point*)alloca(num_points * sizeof(Point));
    
    for (int i = 1; i < num_points; ++i) {
        Point p0 = points[i - 1];
        Point p1 = points[i];
        
        Point diff;
        diff.x = p1.x - p0.x;
        diff.y = p1.y - p0.y;
        diff.z = p1.z - p0.z;
        
        float length = sqrt(diff.x * diff.x + diff.y * diff.y + diff.z * diff.z);
        
        if (length != 0) {
            normals[i].x = diff.x / length;
            normals[i].y = diff.y / length;
            normals[i].z = diff.z / length;
        } else {
            // Handle the case where the length is zero to avoid division by zero
            normals[i].x = 0;
            normals[i].y = 0;
            normals[i].z = 0;
        }
    }
    
    return normals;
}
