#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>

// Function to read a file and return its contents as a Unicode string
wchar_t* read_file_as_unicode(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Determine the size of the file
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Allocate memory for the string and read the file content
    wchar_t* buffer = (wchar_t*)malloc((file_size + 1) * sizeof(wchar_t));
    if (!buffer) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(buffer, sizeof(wchar_t), file_size, file);
    buffer[bytes_read / sizeof(wchar_t)] = L'\0'; // Null-terminate the string

    fclose(file);
    return buffer;
}
