#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALPHABET_SIZE 256

typedef struct TrieNode {
    int count;
    struct TrieNode* children[ALPHABET_SIZE];
} TrieNode;

TrieNode* createNode() {
    TrieNode* node = (TrieNode*)malloc(sizeof(TrieNode));
    node->count = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        node->children[i] = NULL;
    }
    return node;
}

void insertChar(TrieNode* root, char* str) {
    TrieNode* current = root;
    for (int i = 0; i < strlen(str); i++) {
        int index = (int)str[i];
        if (!current->children[index]) {
            current->children[index] = createNode();
        }
        current = current->children[index];
    }
    current->count++;
}

void countCharacters(TrieNode* root, int* counts) {
    TrieNode* current = root;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (current->children[i]) {
            counts[i] = current->children[i]->count;
            countCharacters(current->children[i], counts);
        }
    }
}

int* countOccurrences(char* str) {
    TrieNode* root = createNode();
    for (int i = 0; i < strlen(str); i++) {
        insertChar(root, &str[i]);
    }

    int* counts = (int*)calloc(ALPHABET_SIZE, sizeof(int));
    countCharacters(root, counts);

    free(root);
    return counts;
}

int main() {
    char str[] = "hello world";
    int* counts = countOccurrences(str);

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (counts[i] > 0) {
            printf("Character '%c' occurs %d times\n", i, counts[i]);
        }
    }

    free(counts);
    return 0;
}
