// Function to compare two integers for qsort
int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

// Function to reduce and sort the list of entries
int* unique_and_sort_entries(int num_entries, int* entries, int* result_size) {
    // Allocate memory for the unique entries array
    int* unique_entries = (int*)malloc(num_entries * sizeof(int));
    if (!unique_entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Sort the input entries
    qsort(entries, num_entries, sizeof(int), compare);

    int unique_count = 0;
    for (int i = 0; i < num_entries; ++i) {
        if (i == 0 || entries[i] != entries[i - 1]) {
            unique_entries[unique_count++] = entries[i];
        }
    }

    // Set the result size and return the unique entries array
    *result_size = unique_count;
    return unique_entries;
}

int main() {
    int entries[] = {5, 3, 9, 3, 7, 5, 2};
    int num_entries = sizeof(entries) / sizeof(entries[0]);
    int result_size;

