// Function to calculate the number of ways to choose letters from a given string
int count_ways(char *str, int length, int num_ways) {
    // Create a 2D array to store memoized values
    int dp[length + 1][num_ways + 1];
    
    // Initialize the dp array with -1 (indicating uncomputed states)
    for (int i = 0; i <= length; i++) {
        for (int j = 0; j <= num_ways; j++) {
            dp[i][j] = -1;
        }
    }
    
    // Helper function to compute the number of ways recursively with memoization
    int count(char *str, int length, int num_ways) {
        if (num_ways == 0) return 1;
        if (length <= 0 || num_ways < 0) return 0;
        
        // Check if the result is already computed
        if (dp[length][num_ways] != -1) {
            return dp[length][num_ways];
        }
        
        // Recursive cases: either include or exclude the current character
        int ways = count(str, length - 1, num_ways); // Exclude current character
        if (str[length - 1] >= 'a' && str[length - 1] <= 'z') {
            ways += count(str, length - 1, num_ways - 1); // Include lowercase character
        } else if (str[length - 1] >= 'A' && str[length - 1] <= 'Z') {
            ways += count(str, length - 1, num_ways - 1); // Include uppercase character
        }
        
        // Memoize the result before returning
        dp[length][num_ways] = ways;
        return ways;
    }
    
    return count(str, length, num_ways);
}

