#include <vector>
#include <thread>
#include <functional>

struct Color {
    float r, g, b;
};

class Camera {
public:
    virtual Color GetPixelColor(int x, int y) const = 0;
};

class ImageRenderer {
public:
    ImageRenderer(Camera& camera, size_t numThreads) : camera_(camera), pool_(numThreads) {}

    void RenderImage(std::vector<std::vector<Color>>& image) {
        const int width = image.size();
        const int height = image[0].size();

        std::mutex mutex;
        auto worker = [&](int y) {
            for (int x = 0; x < width; ++x) {
                Color color = camera_.GetPixelColor(x, y);
                std::lock_guard<std::mutex> lock(mutex);
                image[x][y] = color;
            }
        };

        for (int y = 0; y < height; ++y) {
            pool_.enqueue(worker, y);
        }
    }

private:
    Camera& camera_;
    ThreadPool pool_;
};
