#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* parse_name(const char* input) {
    const char* colon = strchr(input, ':');
    if (!colon || colon == input) {
        return NULL;
    }
    size_t name_len = colon - input;
    char* name = (char*)malloc((name_len + 1) * sizeof(char));
    if (!name) {
        return NULL;
    }
    strncpy(name, input, name_len);
    name[name_len] = '\0';
    // Remove leading and trailing whitespace from the name
    while (isspace((unsigned char)*name)) {
        memmove(name, name + 1, name_len);
        name_len--;
    }
    while (isspace((unsigned char)name[name_len - 1])) {
        name[name_len - 1] = '\0';
        name_len--;
    }
    return name;
}

char* parse_value(const char* input) {
    const char* colon = strchr(input, ':');
    if (!colon || colon == input + strlen(input) - 1) {
        return NULL;
    }
    size_t value_len = strlen(input) - (colon - input) - 1;
    char* value = (char*)malloc((value_len + 1) * sizeof(char));
    if (!value) {
        return NULL;
    }
    strcpy(value, colon + 1);
    // Remove leading and trailing whitespace from the value
    while (isspace((unsigned char)*value)) {
        memmove(value, value + 1, value_len);
        value_len--;
    }
    while (isspace((unsigned char)value[value_len - 1])) {
        value[value_len - 1] = '\0';
        value_len--;
    }
    return value;
}

void* parse_name_value(const char* input, char** name, char** value) {
    if (!input || !name || !value) {
        return NULL;
    }
    *name = parse_name(input);
    *value = parse_value(input);
    if (!(*name) || !(*value)) {
        free(*name);
        free(*value);
        *name = NULL;
        *value = NULL;
        return NULL;
    }
    return (void*)1;
}
