bool rename_file(const char *old_name) {
    FILE *file = fopen(old_name, "r");
    if (file == NULL) {
        perror("Error opening file");
        return false;
    }
    fclose(file);

    char new_name[256];
    printf("Enter a new name for the file: ");
    if (scanf("%255s", new_name) != 1) {
        printf("Invalid input. Please enter a valid filename.\n");
        return false;
    }

    // Check if the new name already exists
    file = fopen(new_name, "r");
    if (file != NULL) {
        fclose(file);
        printf("A file with that name already exists. Please choose a different name.\n");
        return false;
    }

    // Rename the file
    if (rename(old_name, new_name) != 0) {
        perror("Error renaming file");
        return false;
    }

    printf("File successfully renamed to %s\n", new_name);
    return true;
}

int main() {
    const char *old_name = "oldfile.txt"; // Example old file name
    if (rename_file(old_name)) {
        printf("File renamed successfully.\n");
    } else {
        printf("Failed to rename the file.\n");
    }
    return 0;
}
