CREATE FUNCTION bind_statement(function_name VARCHAR(255), param_array INTEGER[], scalar_param INTEGER) RETURNS VARCHAR(1024)
BEGIN
    DECLARE stmt VARCHAR(1024);
    SET stmt = CONCAT(function_name, '(');
    SET stmt = CONCAT(stmt, 'ARRAY[');
    SET stmt = CONCAT(stmt, COALESCE(GROUP_CONCAT(param_array SEPARATOR ','), ''));
    SET stmt = CONCAT(stmt, ']', scalar_param);
    RETURN stmt;
END;
