#include <stdlib.h>

void topic_modeling(double **wp, double **dp, double ***probs, int num_docs, int vocab_size) {
    // Allocate memory for the output matrix of topic probabilities
    *probs = (double **)malloc(vocab_size * sizeof(double *));
    for (int i = 0; i < vocab_size; i++) {
        (*probs)[i] = (double *)malloc(num_docs * sizeof(double));
    }

    // Allocate memory for the sum of topic probabilities for each word and total number of words in each topic
    double **sumdp = (double **)malloc(vocab_size * sizeof(double *));
    int *ztot = (int *)malloc(num_docs * sizeof(int));
    for (int i = 0; i < vocab_size; i++) {
        sumdp[i] = (double *)malloc(num_docs * sizeof(double));
    }

    // Calculate the topic probabilities and other required values
    for (int w = 0; w < vocab_size; w++) {
        double word_sum = 0.0;
        for (int d = 0; d < num_docs; d++) {
            sumdp[w][d] = 0.0;
            for (int t = 0; t < num_docs; t++) {
                (*probs)[w][d] += wp[w][t] * dp[t][d];
                sumdp[w][d] += wp[w][t] * dp[t][d];
            }
            word_sum += (*probs)[w][d];
        }
        for (int d = 0; d < num_docs; d++) {
            (*probs)[w][d] /= word_sum;
        }
    }

    // Calculate the sum of topic probabilities for each word and total number of words in each topic
    for (int w = 0; w < vocab_size; w++) {
        double sum = 0.0;
        for (int d = 0; d < num_docs; d++) {
            sum += (*probs)[w][d];
        }
        ztot[w] = 0;
        for (int d = 0; d < num_docs; d++) {
            if ((*probs)[w][d] > 0) {
                ztot[w]++;
            }
        }
    }

    // Free allocated memory for intermediate matrices
    for (int i = 0; i < vocab_size; i++) {
        free(sumdp[i]);
    }
    free(sumdp);
    free(ztot);
}
