std::vector<std::vector<double>> sumWithBorder(const std::vector<std::vector<double>>& input, double borderValue) {
    int rows = input.size();
    if (rows == 0) return {};
    int cols = input[0].size();

    // Create a new 2D array to store the result
    std::vector<std::vector<double>> result(rows, std::vector<double>(cols));

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (borderValue == 0) {
                // Special case when border value is zero
                result[i][j] = input[i][j];
            } else {
                // Sum the input array with the given border value
                result[i][j] = input[i][j] + borderValue;
            }
        }
    }

    return result;
}

