#include <stdio.h>
#include <stdlib.h>

int parse_binary_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    int *indices = malloc(sizeof(int) * file_size); // Allocate memory for indices
    if (!indices) {
        perror("Failed to allocate memory");
        fclose(file);
        return -2; // Memory allocation error
    }

    size_t read_count = fread(indices, sizeof(int), file_size / sizeof(int), file);
    if (ferror(file)) {
        perror("Failed to read file");
        free(indices);
        fclose(file);
        return -3; // Read error
    }

    fclose(file);

    int num_blocks = read_count; // Number of blocks is the number of elements read
    printf("Number of blocks: %d\n", num_blocks);
    for (int i = 0; i < num_blocks; i++) {
        printf("Index %d: %d\n", i, indices[i]);
    }

    free(indices); // Free the allocated memory
    return num_blocks; // Return the number of blocks
}
