std::vector<std::vector<unsigned char>> applyGaussianFilter(const std::vector<std::vector<unsigned char>>& image, int kernelWidth, int kernelHeight, const std::vector<double>& kernel) {
    int width = image[0].size();
    int height = image.size();
    std::vector<std::vector<unsigned char>> result(height, std::vector<unsigned char>(width));

    // Normalize the kernel if necessary (not shown here)
    double kernelSum = 0.0;
    for (int i = 0; i < kernelWidth * kernelHeight; ++i) {
        kernelSum += kernel[i];
    }
    if (kernelSum != 1.0) {
        for (auto& k : kernel) {
            k /= kernelSum;
        }
    }

    // Apply the Gaussian filter using separable convolution
    std::vector<std::vector<unsigned char>> temp(height, std::vector<unsigned char>(width));

    // Horizontal pass
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            double sum[3] = {0.0, 0.0, 0.0};
            for (int kx = -kernelWidth / 2; kx <= kernelWidth / 2; ++kx) {
                int ix = x + kx;
                if (ix < 0) ix = 0; else if (ix >= width) ix = width - 1;
                for (int c = 0; c < 3; ++c) { // Assuming RGB image, adjust as necessary
                    sum[c] += image[y][ix * 3 + c] * kernel[(kx + kernelWidth / 2) * 3];
                }
            }
            for (int c = 0; c < 3; ++c) { // Assuming RGB image, adjust as necessary
                temp[y][x * 3 + c] = static_cast<unsigned char>(std::round(sum[c]));
            }
        }
    }

    // Vertical pass
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            double sum[3] = {0.0, 0.0, 0.0};
            for (int ky = -kernelHeight / 2; ky <= kernelHeight / 2; ++ky) {
                int iy = y + ky;
                if (iy < 0) iy = 0; else if (iy >= height) iy = height - 1;
                for (int c = 0; c < 3; ++c) { // Assuming RGB image, adjust as necessary
                    sum[c] += temp[iy][x * 3 + c] * kernel[(ky + kernelHeight / 2)];
                }
            }
            for (int c = 0; c < 3; ++c) { // Assuming RGB image, adjust as necessary
                result[y][x * 3 + c] = static_cast<unsigned char>(std::round(sum[c]));
            }
        }
    }

    return result;
}
