struct Pixel {
    unsigned char r, g, b, a;
};

void blitImageWithAntiAliasing(Pixel* dst, int dstWidth, int dstHeight, int x, int y, const Pixel* src, int srcWidth, int srcHeight, const std::vector<float>& alpha) {
    auto getAlpha = [&](int ax, int ay) -> float {
        if (ax < 0 || ax >= srcWidth || ay < 0 || ay >= srcHeight) {
            return 0.0f;
        }
        return alpha[ay * srcWidth + ax];
    };

    auto getPixel = [&](const Pixel* image, int ix, int iy) -> Pixel {
        if (ix < 0 || ix >= srcWidth || iy < 0 || iy >= srcHeight) {
            return {0, 0, 0, 0};
        }
        return image[iy * srcWidth + ix];
    };

    for (int sy = 0; sy < srcHeight; ++sy) {
        for (int sx = 0; sx < srcWidth; ++sx) {
            float alphaSrc = getAlpha(sx, sy);
            int startX = std::floor(x + sx - alphaSrc * 0.5f);
            int endX = std::ceil(x + sx + alphaSrc * 0.5f);
            int startY = std::floor(y + sy - alphaSrc * 0.5f);
            int endY = std::ceil(y + sy + alphaSrc * 0.5f);

            for (int dy = startY; dy < endY; ++dy) {
                float alphaDstY = std::max(0.0f, std::min(1.0f, (float)(dy - (y + sy)) / alphaSrc));
                for (int dx = startX; dx < endX; ++dx) {
                    float alphaDstX = std::max(0.0f, std::min(1.0f, (float)(dx - (x + sx)) / alphaSrc));
                    float blendFactor = alphaDstY * alphaDstX;
                    Pixel srcPixel = getPixel(src, sx, sy);
                    for (int c = 0; c < 3; ++c) { // Assuming RGB image
                        dst[(dy * dstWidth + dx)].r += static_cast<unsigned char>(srcPixel.r * blendFactor);
                        dst[(dy * dstWidth + dx)].g += static_cast<unsigned char>(srcPixel.g * blendFactor);
                        dst[(dy * dstWidth + dx)].b += static_cast<unsigned char>(srcPixel.b * blendFactor);
                    }
                    dst[(dy * dstWidth + dx)].a += static_cast<unsigned char>(255 * blendFactor);
                }
            }
        }
    }
}
