class Variant;

template<typename T, typename... Rest>
struct TypeIndexHelper {
    static const int value = -1;
};

template<typename T, typename... Rest>
struct TypeIndexHelper<T, Rest...> {
    static const int value = 0 + TypeIndexHelper<Rest...>::value;
};

template<typename T>
struct TypeIndexHelper<T> {
    static const int value = 0;
};

template<typename... Ts>
class Variant {
public:
    template<typename T>
    void assign(T&& value) {
        using namespace std;
        constexpr int index = TypeIndexHelper<Ts...>::value;
        if (index == -1 || typeid(decay_t<T>) != typeid(Ts)) {
            throw invalid_argument("Type not supported");
        }
        new (&storage) decay_t<T>(forward<T>(value));
    }

    template<typename T>
    friend Variant& operator=(Variant& lhs, T&& rhs);

private:
    alignas(max_align_t) char storage[sizeof(std::decay_t<Ts>)];
};

template<typename... Ts>
Variant& operator=(Variant<Ts...>& lhs, Ts&& rhs) {
    lhs.assign(forward<Ts>(rhs));
    return lhs;
}

