#include <vector>
#include <unordered_set>

class DisjointSetUnion {
public:
    DisjointSetUnion(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                ++rank[rootX];
            }
        }
    }

private:
    std::vector<int> parent;
    std::vector<int> rank;
};

bool arePairwiseConnected(const std::vector<int>& firstVector, const std::vector<int>& secondVector) {
    int maxElement = 0;
    for (int num : firstVector) {
        if (num > maxElement) {
            maxElement = num;
        }
    }
    for (int num : secondVector) {
        if (num > maxElement) {
            maxElement = num;
        }
    }

    DisjointSetUnion dsu(maxElement + 1);

    for (int num : firstVector) {
        dsu.unionSets(firstVector[0], num);
    }

    for (int num : secondVector) {
        if (dsu.find(secondVector[0]) != dsu.find(num)) {
            return false;
        }
    }

    return true;
}
