#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Shared resource
int shared_resource = 0;

// Mutex variable
pthread_mutex_t mutex;

// Thread function
void* thread_function(void* arg) {
    // Lock the mutex before accessing the shared resource
    pthread_mutex_lock(&mutex);
    printf("Thread %ld: Lock acquired\n", (long)arg);

    // Simulate some work with the shared resource
    shared_resource++;
    printf("Thread %ld: Shared resource incremented to %d\n", (long)arg, shared_resource);

    // Unlock the mutex after accessing the shared resource
    pthread_mutex_unlock(&mutex);
    printf("Thread %ld: Lock released\n", (long)arg);

    return NULL;
}

int main() {
    // Initialize the mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        return EXIT_FAILURE;
    }

    pthread_t threads[3];
    long thread_ids[] = {1, 2, 3};

    // Create multiple threads
    for (int i = 0; i < 3; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, (void*)thread_ids[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 3; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return EXIT_FAILURE;
        }
    }

    // Destroy the mutex
    pthread_mutex_destroy(&mutex);

    return EXIT_SUCCESS;
}
