typedef void (*CallbackFunction)(const char*);

void formatMessageWithCallback(CallbackFunction callback, const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Determine the maximum size needed for the formatted message
    int maxSize = 1024; // Initial guess, can be adjusted based on requirements
    char* buffer = (char*)malloc(maxSize);
    if (!buffer) {
        va_end(args);
