        // If the buffer is not large enough, reallocate and try again
        free(buffer);
        maxSize = actualSize + 1; // Add space for null terminator
        buffer = (char*)malloc(maxSize);
        if (!buffer) {
            va_end(args);
            return;
        }
        actualSize = vsnprintf(buffer, maxSize, format, args);
    }

    // Call the callback function with the formatted message
    callback(buffer);

    free(buffer);
    va_end(args);
}
