std::vector<int> getAnonymousOutputCounts(const std::map<std::string, int>& stats, const std::vector<int>& outputCounts) {
    // Create a vector to store the anonymous output counts
    std::vector<int> anonymousCounts;

    // Copy the input counts to the new vector
    for (int count : outputCounts) {
        anonymousCounts.push_back(count);
    }

    // Sort the vector in descending order based on the values from the map
    std::sort(anonymousCounts.begin(), anonymousCounts.end(), [&stats](int a, int b) {
        return stats.at(std::to_string(a)) > stats.at(std::to_string(b));
    });

    return anonymousCounts;
}
