    public static List<string> ParseXml(string xmlString, string[] parametersToExtract)
    {
        var parameterValues = new List<string>();
        using (var reader = XmlReader.Create(new System.IO.StringReader(xmlString), new XmlReaderSettings { IgnoreComments = true, IgnoreProcessingInstructions = true }))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && Array.Exists(parametersToExtract, p => p == reader.Name))
