using System;

public class DisplacementFieldGenerator
{
    public double[,] GenerateDisplacementField(int width, int height, double stepSize)
    {
        double[,] displacementField = new double[width, height];
        Random random = new Random();

        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                // Generate Gaussian-distributed random displacement
                double mean = 0.0;
                double stdDev = stepSize / 3.0; // Standard deviation based on step size
                displacementField[x, y] = RandomGaussian(random, mean, stdDev);
            }
        }

        return displacementField;
    }

    private double RandomGaussian(Random random, double mean, double stdDev)
    {
        double u1 = 1.0 - random.NextDouble(); // Uniform(0,1] random doubles
        double u2 = 1.0 - random.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2); // Box-Muller transform
        return mean + stdDev * randStdNormal; // Normal distributed random number
    }
}
