using System.Security.Cryptography;

public class RandomDatagramGenerator
{
    private static readonly Random random = new Random();

    public byte[] GenerateRandomDatagram(int size)
    {
        byte[] datagram = new byte[size];
        random.NextBytes(datagram);
        return datagram;
    }

    public bool AreEqual(byte[] datagram1, byte[] datagram2)
    {
        if (datagram1.Length != datagram2.Length)
            return false;

        for (int i = 0; i < datagram1.Length; i++)
        {
            if (datagram1[i] != datagram2[i])
                return false;
        }

        return true;
    }

    public int GetHashCode(byte[] datagram)
    {
        unchecked
        {
            int hash = 17;
            foreach (byte b in datagram)
            {
                hash = hash * 23 + b.GetHashCode();
            }
            return hash;
        }
    }
}

public class Program
{
