public class GameObjectFactory : MonoBehaviour
{
    private static int instanceCount = 0;

    public GameObject CreateGameObject(Material[] materials)
    {
        // Generate random indices for position, rotation, and material
        int positionIndex = UnityEngine.Random.Range(0, positions.Length);
        int rotationIndex = UnityEngine.Random.Range(0, rotations.Length);
        int materialIndex = UnityEngine.Random.Range(0, materials.Length);

        // Get the random values from arrays
        Vector3 position = positions[positionIndex];
        Quaternion rotation = rotations[rotationIndex];
        Material material = materials[materialIndex];

        // Create a new GameObject instance
        GameObject gameObject = new GameObject();
        gameObject.transform.position = position;
        gameObject.transform.rotation = rotation;
        gameObject.GetComponent<Renderer>().material = material;

        // Update the static variable to keep track of the number of instances created
        instanceCount++;

        return gameObject;
    }
