using System;
using System.Security.Cryptography;
using System.Text;

public class TripleDESDecryption
{
    public static string Decrypt(string encryptedMessage, byte[] key, byte[] iv)
    {
        // Convert the Base64 encoded message to a byte array
        byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

        // Create a TripleDES object with the specified key and IV
        using (TripleDES tripleDes = TripleDES.Create())
        {
            tripleDes.Key = key;
            tripleDes.IV = iv;
            tripleDes.Mode = CipherMode.CBC;
            tripleDes.Padding = PaddingMode.PKCS7;

            // Create a decryptor from the TripleDES object
            ICryptoTransform decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

            // Decrypt the byte array
            using (var memoryStream = new System.IO.MemoryStream(encryptedBytes))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                {
                    using (var reader = new System.IO.StreamReader(cryptoStream))
                    {
                        // Read the decrypted message from the stream and return it as a string
                        return reader.ReadToEnd();
                    }
                }
            }
        }
    }
}
