using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

public class ExternalCommandExecutor
{
    public async Task ExecuteAsync(string commandFormat, string keyFilePath)
    {
        // Construct the command using the format string and key file path
        string commandLine = String.Format(commandFormat, keyFilePath);

        // Initialize a new process start info with the command line
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe", // Assuming Windows for simplicity; adjust if needed
            Arguments = $"/c {commandLine}",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        // Start the process
        using (Process process = new Process { StartInfo = startInfo })
        {
            try
            {
                process.Start();

                // Read output and error streams asynchronously
                Task<string> outputTask = process.StandardOutput.ReadToEndAsync();
                Task<string> errorTask = process.StandardError.ReadToEndAsync();

                // Wait for both tasks to complete or timeout
                bool completed = await Task.WhenAny(outputTask, errorTask) == outputTask;

                // Wait for the remaining task if necessary
                string output = await (completed ? outputTask : errorTask);

                // Output the results
                Console.WriteLine("Output: " + output);

                // Wait for the process to exit and get the exit code
                await process.WaitForExitAsync();
                int exitCode = process.ExitCode;
                Console.WriteLine("Process exited with code: " + exitCode);
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred: " + ex.Message);
            }
        }
    }
}
