using UnityEngine;

public class GameObjectRotator : MonoBehaviour
{
    public void RotateTransform(Transform transform, string intersectionType)
    {
        int rotationAngle = 0;

        switch (intersectionType.ToLower())
        {
            case "three-way":
                // Randomly rotate by 90 or -90 degrees
                rotationAngle = UnityEngine.Random.Range(0, 2) == 0 ? 90 : -90;
                break;
            case "turn":
                // Always rotate by -90 degrees
                rotationAngle = -90;
                break;
            default:
                // Rotate by specified angle based on intersection type
                switch (intersectionType.ToLower())
                {
                    case "90":
                        rotationAngle = 90;
                        break;
                    case "-90":
                        rotationAngle = -90;
                        break;
                }
                break;
        }

        // Apply the rotation to the transform component
        transform.Rotate(Vector3.up, rotationAngle);
    }
}
