using Cassandra;
using System;
using System.Collections.Generic;

public class CassandraBatchInsertExample
{
    public static void ExecuteInsert(ISession session, byte[] incomingPayload)
    {
        // Create a new BatchStatement
        var batch = new BatchStatement();

        // Add an INSERT statement to the batch with outgoing payload set using a dictionary of byte arrays
        var outgoingPayload = new Dictionary<string, byte[]>
        {
            { "key1", new byte[] { 1, 2, 3 } },
            { "key2", new byte[] { 4, 5, 6 } }
        };

        foreach (var kvp in outgoingPayload)
        {
            batch.Add(new SimpleStatement($"INSERT INTO example_table (id, data) VALUES ('{kvp.Key}', :data)").Bind(kvp.Value));
        }

        // Execute the statement using a Cassandra Session
        var result = session.Execute(batch);

        // Assert that the incoming payload is not null and has the same number of elements as the outgoing payload
        Assert.NotNull(incomingPayload);
        Assert.AreEqual(outgoingPayload.Count, incomingPayload.Length);

        // Assert that the contents of the outgoing payload are the same as the contents of the incoming payload
        var index = 0;
        foreach (var kvp in outgoingPayload)
        {
            CollectionAssert.AreEqual(kvp.Value, incomingPayload[index]);
            index++;
        }
    }
}
