using System.Net;

public class RsvpController : Controller
{
    [HttpGet]
    public ActionResult Index()
    {
        return View();
    }

    [HttpPost]
    public async Task<ActionResult> Submit(string name, string email)
    {
        if (string.IsNullOrEmpty(name) || string.IsNullOrEmpty(email))
        {
            ModelState.AddModelError("", "Name and Email are required.");
            return View("Index");
        }

        var message = new StringBuilder();
        message.AppendLine($"Name: {name}");
        message.AppendLine($"Email: {email}");

        string smtpServer = ConfigurationManager.AppSettings["SmtpServer"];
        int smtpPort = int.Parse(ConfigurationManager.AppSettings["SmtpPort"]);
        string senderEmail = ConfigurationManager.AppSettings["SenderEmail"];
        string password = ConfigurationManager.AppSettings["Password"];
        string recipientEmail = ConfigurationManager.AppSettings["RecipientEmail"];

        using (var client = new SmtpClient(smtpServer, smtpPort))
        {
            client.Credentials = new NetworkCredential(senderEmail, password);
            client.EnableSsl = true;

            try
            {
                await client.SendMailAsync(new MailMessage(senderEmail, recipientEmail, "RSVP Submission", message.ToString()));
                ViewBag.Message = "Thank you for your RSVP! We will contact you soon.";
