using System;
using System.Collections.Generic;
using System.Xml;

public class XmlParser
{
    public void ParseXmlToList(List<string> list, string xmlDocument)
    {
        // Create an XML document from the provided XML string
        XmlDocument doc = new XmlDocument();
        doc.LoadXml(xmlDocument);

        // Get the root element of the XML document
        XmlElement root = doc.DocumentElement;

        // Recursively parse the XML and populate the list based on the structure
        ParseNode(list, root);
    }

    private void ParseNode(List<string> list, XmlNode node)
    {
        if (node == null)
        {
            return;
        }

        // Add the current node's name and value to the list
        list.Add($"Element: {node.Name}, Value: {node.InnerText}");

        // Recursively parse child nodes
        foreach (XmlNode child in node.ChildNodes)
        {
            ParseNode(list, child);
        }
    }
}
