using System;
using System.IO;
using System.Reflection;
using System.Xml;
using System.Drawing;

public class FontCreator
{
    public Font CreateFontFromXml(Device device, string fontName)
    {
        // Load the XML file from embedded resources
        var assembly = Assembly.GetExecutingAssembly();
        string resourceName = $"{assembly.GetName().Name}.Fonts.{fontName}.xml";

        using (Stream stream = assembly.GetManifestResourceStream(resourceName))
        {
            if (stream == null)
                throw new FileNotFoundException($"Font XML file '{fontName}' not found.");

            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load(stream);

            // Extract font size, width, and height from the XML file
            XmlNodeList nodeList = xmlDoc.SelectNodes("/font/size");
            int size = int.Parse(nodeList[0].InnerText);

            nodeList = xmlDoc.SelectNodes("/font/width");
            int width = int.Parse(nodeList[0].InnerText);

            nodeList = xmlDoc.SelectNodes("/font/height");
            int height = int.Parse(nodeList[0].InnerText);

            // Create and return the Font object
            return new Font(fontName, size, width, height);
        }
    }
}
