public class ObjectCreator : MonoBehaviour
{
    public GameObject[] objectPrefabs; // Array of 3D objects to instantiate
    public Material[] materials; // Array of materials for the objects
    public Vector3 positionRange = new Vector3(10, 10, 10); // Range within which to place the objects randomly

    void Start()
    {
        CreateObject();
    }

    void CreateObject()
    {
        if (objectPrefabs.Length == 0 || materials.Length == 0)
        {
            Debug.LogWarning("No objects or materials to create.");
            return;
        }

        // Select a random object prefab
        GameObject selectedObject = objectPrefabs[Random.Range(0, objectPrefabs.Length)];

        // Select a random material
