        // Generate a random position within the specified range
        Vector3 randomPosition = new Vector3(
            Random.Range(-positionRange.x, positionRange.x),
            Random.Range(-positionRange.y, positionRange.y),
            Random.Range(-positionRange.z, positionRange.z)
        );

        // Instantiate the object at the random position with the selected material
        GameObject instantiatedObject = Instantiate(selectedObject, randomPosition, Quaternion.identity);
        instantiatedObject.GetComponent<Renderer>().material = selectedMaterial;
    }
}
