public class GameObjectRotator : MonoBehaviour
{
    public void RotateTransform(Transform transform, IntersectionType intersectionType)
    {
        Vector3 otherTransformDirection = transform.forward; // Assuming the direction of the other object's transform component

        if (intersectionType == IntersectionType.Left)
        {
            Quaternion rotation = Quaternion.Euler(0f, 90f, 0f);
            transform.rotation *= rotation;
        }
        else if (intersectionType == IntersectionType.Right)
        {
            Quaternion rotation = Quaternion.Euler(0f, -90f, 0f);
            transform.rotation *= rotation;
        }
    }
}

public enum IntersectionType
{
