public struct LabPixel
{
    public double L;
    public double A;
    public double B;
}

public class Matrix<T> where T : struct
{
    private IntPtr _dataPtr;
    private int _rows;
    private int _columns;

    public Matrix(int rows, int columns)
    {
        _rows = rows;
        _columns = columns;
        int sizeOfT = Marshal.SizeOf<T>();
        _dataPtr = Marshal.AllocHGlobal(rows * columns * sizeOfT);
    }

    ~Matrix()
    {
        Marshal.FreeHGlobal(_dataPtr);
    }

    public T this[int row, int col]
    {
        get
        {
            if (row < 0 || row >= _rows || col < 0 || col >= _columns)
                throw new IndexOutOfRangeException();
            IntPtr cellPtr = Marshal.ReadIntPtr(_dataPtr, ((row * _columns + col) * Marshal.SizeOf<T>()));
            return Marshal.PtrToStructure<T>(cellPtr);
        }
        set
        {
            if (row < 0 || row >= _rows || col < 0 || col >= _columns)
                throw new IndexOutOfRangeException();
            IntPtr cellPtr = Marshal.ReadIntPtr(_dataPtr, ((row * _columns + col) * Marshal.SizeOf<T>()));
            Marshal.StructureToPtr(value, cellPtr, false);
        }
    }
}

public class Program
{
    public static Matrix<LabPixel> GenerateRandomMatrix(int rows, int columns)
    {
        var matrix = new Matrix<LabPixel>(rows, columns);
        Random rand = new Random();
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                LabPixel pixel;
                pixel.L = rand.NextDouble();
                pixel.A = rand.NextDouble();
                pixel.B = rand.NextDouble();
                matrix[i, j] = pixel;
            }
        }
        return matrix;
    }
}
