public class CacheService
{
    private Dictionary<string, byte[]> _cache = new Dictionary<string, byte[]>();

    public async Task<ActionResult> ProcessRequest(HttpRequestMessage request)
    {
        string cacheKey = GenerateCacheKey(request);
        if (_cache.ContainsKey(cacheKey))
        {
            return new ContentResult
            {
                Content = System.Text.Encoding.UTF8.GetString(_cache[cacheKey]),
                StatusCode = 200,
                ContentType = "text/plain"
            };
        }

        HttpResponseMessage response = await SendRequestAsync(request);
        if (response.IsSuccessStatusCode)
        {
            byte[] content = await response.Content.ReadAsByteArrayAsync();
            UpdateCache(cacheKey, response.Headers, content);

            return new ContentResult
            {
                Content = System.Text.Encoding.UTF8.GetString(content),
                StatusCode = (int)response.StatusCode,
                ContentType = response.Content.Headers.ContentType?.ToString() ?? "text/plain"
            };
        }

        return new BadRequestResult();
    }

    private string GenerateCacheKey(HttpRequestMessage request)
    {
        // Implement a method to generate a unique cache key based on the request
        // This can include headers, query parameters, etc.
        return request.RequestUri.ToString();
    }

    private async Task<HttpResponseMessage> SendRequestAsync(HttpRequestMessage request)
    {
        using (HttpClient client = new HttpClient())
        {
            return await client.SendAsync(request);
        }
    }

    private void UpdateCache(string cacheKey, HttpResponseHeaders responseHeaders, byte[] content)
    {
        var headersToCopy = new List<string> { "Cache-Control", "Vary" };
        foreach (var header in headersToCopy)
        {
            if (responseHeaders.TryGetValues(header, out var values))
            {
                _cache[cacheKey] = content;
            }
        }
    }
