using System.Threading;
using ZeroMQ;
using System.Text;

public class Publisher
{
    private static readonly string Topic = "testTopic";
    private static readonly int MaxRetries = 5;
    private static readonly double RetryInterval = 100; // in milliseconds

    public void PublishMessages()
    {
        using (var context = new ZmqContext())
        {
            using (var publisher = context.CreateSocket(SocketType.PUB))
            {
                publisher.Bind("tcp://*:5556");

                for (int i = 0; i < MaxRetries; i++)
                {
                    try
                    {
                        // Generate a random oversized message
                        string largeMessage = new string('A', 1024 * 1024); // 1MB oversized message
                        publisher.Send(Topic, Encoding.UTF8.GetBytes(largeMessage));
                        break;
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Attempt {i + 1} failed: {ex.Message}");
                        Thread.Sleep((int)RetryInterval);
                    }
                }
            }
        }
    }
}
