using System;
using System.Threading;
using System.Threading.Tasks;

public class Observation
{
    public int SequenceNumber { get; set; }
    public int ProducerThreadId { get; set; }
    public int Latency { get; set; }
}

public class DemuxProducer<TInput, TOutput>
{
    private int sequenceNumber = 0;
    private readonly object lockObject = new object();

    public virtual Observation Produce(TInput input)
    {
        var observation = new Observation();
        observation.SequenceNumber = Interlocked.Increment(ref sequenceNumber);
        observation.ProducerThreadId = Thread.CurrentThread.ManagedThreadId;
        Random random = new Random();
        int delay = random.Next(100, 500); // Simulate some latency between 100 and 500 milliseconds
        Thread.Sleep(delay);
        observation.Latency = delay;
        return observation;
    }
}
