using System;
using System.IO;
using System.Net;
using System.Net.Sockets;

public class ProjectHelper
{
    public static string GetStartupFilePath(Project project)
    {
        // Check if the project has a startup file specified
        if (project.HasStartupFile())
        {
            return project.GetStartupFilePath();
        }

        // Generate a random available port number between 1200 and 60000, inclusive
        int generatedPort = new Random().Next(1200, 60001);

        // Find the first available port that is not already in use
        int availablePort = GetAvailablePort(generatedPort);

        // Return the path to the startup file with the generated port number appended to the end
        return Path.Combine(project.GetStartupFilePath(), $"port{availablePort}");
    }

    private static int GetAvailablePort(int startPort)
    {
        for (int port = startPort; port <= 60000; port++)
        {
            if (!IsPortInUse(port))
            {
                return port;
            }
        }
        throw new Exception("No available ports found between " + startPort + " and 60000");
    }

    private static bool IsPortInUse(int port)
    {
        IPAddress[] ipAddresses = Dns.GetHostEntry(Dns.GetHostName()).AddressList;
        foreach (IPAddress ip in ipAddresses)
        {
            IPEndPoint endPoint = new IPEndPoint(ip, port);
            using (Socket socket = new Socket(endPoint.AddressFamily, SocketType.Stream, ProtocolType.Tcp))
            {
                try
                {
                    socket.Bind(endPoint);
                    return false;
                }
                catch (SocketException)
                {
