        timer += Time.deltaTime;

        if (timer >= spawnRate)
        {
            if (cubeCount < maxCubes)
            {
                SpawnCube();
            }
            else
            {
                cubeCount = 0; // Reset the counter and restart the spawning process
            }
            timer = 0.0f; // Reset the timer
