            Random.Range(minSpawnRange.y, maxSpawnRange.y),
            Random.Range(minSpawnRange.z, maxSpawnRange.z)
        );

        GameObject cube = Instantiate(cubePrefab, spawnPosition, Quaternion.identity);
        cubeCount++;
