using System;
using System.IO;
using System.Collections.Generic;

public class IniParser
{
    public static Dictionary<string, string> ParseIniFile(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Console.Error.WriteLine("Ini file does not exist.");
            return null;
        }

        var iniDictionary = new Dictionary<string, string>();
        try
        {
            using (StreamReader reader = new StreamReader(filePath))
            {
                string currentSection = null;
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    var trimmedLine = line.Trim();
                    if (trimmedLine.StartsWith("["))
                    {
                        if (trimmedLine.EndsWith("]"))
                        {
                            currentSection = trimmedLine.Substring(1, trimmedLine.Length - 2);
                        }
                        else
                        {
                            Console.Error.WriteLine("Ini file has invalid section syntax.");
                            return null;
                        }
                    }
                    else if (!string.IsNullOrEmpty(trimmedLine) && !trimmedLine.StartsWith("#") && !trimmedLine.StartsWith(";"))
                    {
                        var equalsIndex = trimmedLine.IndexOf('=');
                        if (equalsIndex > 0)
                        {
                            string key = trimmedLine.Substring(0, equalsIndex).Trim();
                            string value = trimmedLine.Substring(equalsIndex + 1).Trim();
                            if (!string.IsNullOrEmpty(currentSection))
                            {
                                iniDictionary[$"{currentSection}.{key}"] = value;
                            }
                            else
                            {
                                iniDictionary[key] = value;
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"An error occurred while parsing the INI file: {ex.Message}");
            return null;
        }

        return iniDictionary;
    }
}
