    public static async Task<string> GenerateTokenAsync(string password, string domain, int port, string url)
    {
        // Hash the password using SHA1 and encode it in base 16
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] hashBytes = sha1.ComputeHash(Encoding.UTF8.GetBytes(password));
            string token = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

            // Construct the HTTP request with the token included in the request body
            using (HttpClient client = new HttpClient())
            {
                var content = new StringContent(token, Encoding.UTF8, "application/json");
                string requestUri = $"http://{domain}:{port}/{url}";
                HttpResponseMessage response = await client.PostAsync(requestUri, content);
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
                else
                {
                    throw new Exception($"Failed to generate token: {response.ReasonPhrase}");
                }
            }
        }
    }
}
