using Cassandra;
using System;

public class CassandraTestClusterSetup
{
    private Cluster cluster;
    private Session session;

    public void SetupCassandraCluster()
    {
        // Set up the Cassandra cluster
        cluster = Cluster.Builder()
            .AddContactPoint("127.0.0.1") // Replace with your Cassandra host IP
            .Build();

        // Connect to the cluster
        session = cluster.Connect();
    }

    public void CreateKeyspace(string keyspaceName)
    {
        string createKeyspaceQuery = $"CREATE KEYSPACE IF NOT EXISTS {keyspaceName} WITH REPLICATION = {{ 'class' : 'SimpleStrategy', 'replication_factor' : 1 }}";
        session.Execute(createKeyspaceQuery);

        // Set the keyspace to be used
        session.ChangeKeyspace(keyspaceName);
    }

    public void CreateTable(string tableName, string tableSchema)
    {
        string createTableQuery = $"CREATE TABLE IF NOT EXISTS {tableName} ({tableSchema})";
        session.Execute(createTableQuery);
    }

    public void ExecuteQuery(string query, params object[] values)
    {
        var preparedStatement = session.Prepare(query);
        var boundStatement = preparedStatement.Bind(values);
        session.Execute(boundStatement);
    }
}
