using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class SqlServerDatabaseHelper
{
    public List<List<object>> GetTableRows(string serverName, string databaseName, string tableName)
    {
        var rows = new List<List<object>>();
        var connectionString = $"Server={serverName};Database={databaseName};Integrated Security=True;";

        using (var connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                var query = $"SELECT * FROM {tableName}";
                using (var command = new SqlCommand(query, connection))
                using (var reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        var row = new List<object>();
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            row.Add(reader[i]);
                        }
                        rows.Add(row);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }

        return rows;
    }
}
