[AttributeUsage(AttributeTargets.Class)]
public class XmlizedClassAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Property)]
public class XmlizedSqlstringIDClassAttribute : Attribute { }

public static class XmlGenerator
{
    public static XmlDocument GenerateXmlFromType(Type type)
    {
        if (type == null) throw new ArgumentNullException(nameof(type));

        XmlDocument xmlDoc = new XmlDocument();
        XmlElement root = xmlDoc.CreateElement(type.Name);
        xmlDoc.AppendChild(root);

        foreach (var property in type.GetProperties())
        {
            var customAttributes = property.GetCustomAttributes(false);
            if (customAttributes.Any(attr => attr is XmlizedSqlstringIDClassAttribute))
            {
                XmlElement propElement = xmlDoc.CreateElement(property.Name);
                root.AppendChild(propElement);

                var value = property.GetValue(null); // Assuming static properties for simplicity
                if (value != null)
                {
                    XmlText textNode = xmlDoc.CreateTextNode(value.ToString());
                    propElement.AppendChild(textNode);
                }
            }
        }

