using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using HtmlAgilityPack;
using System.Xml;

public class GeocacheParser {
    public List<TravelItem> ParseGeocachesFromHtml(string htmlFileName) {
        var travelItems = new List<TravelItem>();
        var assembly = Assembly.GetExecutingAssembly();
        
        try {
            using (var stream = assembly.GetManifestResourceStream(htmlFileName)) {
                if (stream == null) {
                    throw new FileNotFoundException($"Embedded resource '{htmlFileName}' not found.");
                }
                
                var reader = new StreamReader(stream);
                string htmlContent = reader.ReadToEnd();
                
                HtmlDocument doc = new HtmlDocument();
                doc.LoadHtml(htmlContent);
                
                var nodes = doc.DocumentNode.SelectNodes("//div[@class='geocache-info']");
                if (nodes != null) {
                    foreach (var node in nodes) {
                        string coordinates = node.SelectSingleNode(".//span[@class='coordinates']")?.InnerText;
                        string dateLogged = node.SelectSingleNode(".//span[@class='date-logged']")?.InnerText;
                        
                        if (!string.IsNullOrEmpty(coordinates) && !string.IsNullOrEmpty(dateLogged)) {
                            var travelItem = new TravelItem {
                                Coordinates = coordinates,
                                DateLogged = dateLogged
                            };
                            travelItems.Add(travelItem);
                        }
                    }
                }
            }
        } catch (Exception ex) {
            Console.WriteLine($"Error parsing HTML: {ex.Message}");
        }
        
        return travelItems;
    }
}

public class TravelItem {
    public string Coordinates { get; set; }
    public string DateLogged { get; set; }
}
