using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class VersionManager
{
    private readonly string _connectionString;

    public VersionManager(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<int> GetNextVersionAsync(string streamId, int currentVersion)
    {
        const string query = "SELECT TOP 1 Version FROM StreamVersions WHERE StreamID = @StreamID AND Version > @CurrentVersion ORDER BY Version ASC";

        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (SqlCommand command = new SqlCommand(query, connection))
            {
                command.Parameters.AddWithValue("@StreamID", streamId);
                command.Parameters.AddWithValue("@CurrentVersion", currentVersion);

                object result = await command.ExecuteScalarAsync();
                if (result != null && int.TryParse(result.ToString(), out int nextVersion))
                {
                    return nextVersion;
                }
            }
        }

        return -1;
    }
}
