public class RemoteConnection
{
    public static bool EstablishRemoteConnection(string hostIPAddress, string userName, string password)
    {
        try
        {
            // Create the process start info with the 'net use' command and arguments
            ProcessStartInfo startInfo = new ProcessStartInfo();
            startInfo.FileName = "cmd.exe";
            startInfo.Arguments = $"/c net use * /delete /y && net use \\\\{hostIPAddress} {password} /user:{userName}";
            startInfo.RedirectStandardInput = true;
            startInfo.RedirectStandardOutput = true;
            startInfo.RedirectStandardError = true;
            startInfo.UseShellExecute = false;
            startInfo.CreateNoWindow = true;

            // Start the process
            using (Process process = new Process())
