using System.Xml.Linq;
using System.Xml.XPath;

public class XmlHelper
{
    public static void UpdateAndCountNodes(string xmlFilePath, string xpathQuery, string newElementName, string newValue)
    {
        // Load the XML file
        XDocument doc = XDocument.Load(xmlFilePath);

        // Count the number of nodes before insertion
        int countBefore = doc.XPathEvaluate(xpathQuery);

        // Insert a new element into the XML file
        var root = doc.Root;
        if (root != null)
        {
            root.Add(new XElement(newElementName, newValue));
        }

        // Save the updated XML file
        doc.Save(xmlFilePath);

        // Count the number of nodes after insertion
        int countAfter = doc.XPathEvaluate(xpathQuery);

        // Assert that the number of nodes before and after the insertion is the same
        if (countBefore != countAfter)
        {
            throw new Exception("The number of nodes has changed after insertion.");
        }
    }
}
