using System;
using System.Xml;
using System.IO;

public class XmlValidator
{
    public static bool ValidateXmlAgainstSchema(string xmlContent, string schemaContent)
    {
        using (var xmlReaderSettings = new XmlReaderSettings())
        {
            xmlReaderSettings.ValidationType = ValidationType.Schema;
            var schemaSet = new XmlSchemaSet();
            using (var schemaStream = new StringReader(schemaContent))
            using (var reader = XmlReader.Create(schemaStream))
            {
                while (reader.Read()) ; // Read the entire schema content to load it into the schema set
                schemaSet.Add(null, reader);
            }
            xmlReaderSettings.Schemas = schemaSet;

            using (var xmlStream = new StringReader(xmlContent))
            using (var xmlReader = XmlReader.Create(xmlStream, xmlReaderSettings))
            {
                while (xmlReader.Read()) ; // Read the entire XML content to validate it against the schema
                if (xmlReader.MoveToFirstAttribute() && string.IsNullOrEmpty(xmlReader.Prefix))
                {
                    return true; // The first attribute's prefix is empty, validation passed
                }
            }
        }
        return false; // Validation failed or no attributes found in XML document
    }
}
