public string GetDatabaseValue(string configKey)
{
    // Retrieve the connection string from configuration
    var configuration = new ConfigurationBuilder()
        .AddJsonFile("appsettings.json")
        .Build();

    string connectionString = configuration.GetConnectionString(configKey);
    if (connectionString == null)
    {
        throw new ArgumentException($"Configuration key '{configKey}' not found.");
    }

    // Use the connection string to connect to the database
    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        try
        {
            connection.Open();

            // Construct and execute a query using the configuration key
            string query = configuration["Query"];
            if (string.IsNullOrEmpty(query))
            {
                throw new ArgumentException("Query not found in configuration.");
            }

            using (SqlCommand command = new SqlCommand(query, connection))
            {
                command.CommandType = System.Data.CommandType.Text;

                // Execute the query and retrieve the result
                string result = command.ExecuteScalar() as string;
                return result ?? null;
            }
        }
