    {
        string utilityPath = @"C:\path\to\your\utility.exe"; // Path to the external command-line utility
        string arguments = "arg1 arg2"; // Arguments for the utility

        try
        {
            var processInfo = new ProcessStartInfo(utilityPath, arguments)
            {
                RedirectStandardInput = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true // Run the utility in a minimized window
            };

            using (var process = new Process { StartInfo = processInfo })
            {
