public class XmlValidator
{
    public static bool ValidateXmlAgainstSchema(string xmlFilePath, string schemaFilePath)
    {
        try
        {
            // Create a new XmlSchemaSet to hold the schema
            XmlSchemaSet schemas = new XmlSchemaSet();
            schemas.Add("", schemaFilePath);

            // Create an XmlReaderSettings object with validation enabled
            XmlReaderSettings settings = new XmlReaderSettings();
            settings.ValidationType = ValidationType.Schema;
            settings.Schemas = schemas;
            settings.ValidationEventHandler += new ValidationEventHandler(ValidationCallBack);

            // Create an XmlReader object to read the XML file
            using (XmlReader reader = XmlReader.Create(xmlFilePath, settings))
            {
                while (reader.Read()) ; // Read through the document
            }

            return true; // Validation passed
        }
        catch (Exception ex)
        {
            Console.WriteLine("Validation failed: " + ex.Message);
            return false; // Validation failed
        }
    }

    private static void ValidationCallBack(object sender, ValidationEventArgs e)
    {
        if (e.Severity == XmlSeverityType.Warning)
        {
            Console.Write("WARNING: ");
        }
        else if (e.Severity == XmlSeverityType.Error)
        {
            Console.Write("ERROR: ");
        }
        Console.WriteLine(e.Message);
    }
}
