    public void DeleteTrackableItems(ListView listView)
    {
        if (listView.SelectedIndices.Count == 0)
        {
            MessageBox.Show("No items selected.");
            return;
        }

        foreach (int index in listView.SelectedIndices)
        {
            string itemId = listView.Items[index].SubItems[0].Text; // Assuming the first subitem is the ID
            DeleteItem(itemId);
        }
    }

    private void DeleteItem(string itemId)
    {
        string query = "DELETE FROM TrackableItems WHERE Id = @id";
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            using (SqlCommand command = new SqlCommand(query, connection))
            {
                command.Parameters.AddWithValue("@id", itemId);
                try
                {
                    connection.Open();
                    int rowsAffected = command.ExecuteNonQuery();
                    if (rowsAffected > 0)
                    {
                        LogDeletion(itemId);
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Error deleting item: " + ex.Message);
                }
            }
        }
    }

    private void LogDeletion(string itemId)
    {
        string logQuery = "INSERT INTO DeletionLog (ItemId, DeletedDate) VALUES (@itemId, @deletedDate)";
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            using (SqlCommand command = new SqlCommand(logQuery, connection))
            {
                command.Parameters.AddWithValue("@itemId", itemId);
                command.Parameters.AddWithValue("@deletedDate", DateTime.Now);
                try
                {
                    connection.Open();
                    command.ExecuteNonQuery();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Error logging deletion: " + ex.Message);
                }
            }
        }
    }
}
