using System;
using System.Diagnostics;
using System.Windows.Forms;

public class ExternalProcessRunner
{
    public void RunExternalProcess(string fileName, string arguments, bool showPopup = false)
    {
        try
        {
            using (Process process = new Process())
            {
                process.StartInfo.FileName = fileName;
                process.StartInfo.Arguments = arguments;
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.RedirectStandardError = true;
                process.StartInfo.UseShellExecute = false;
                process.EnableRaisingEvents = true;

                // Redirect the output and error streams to the parent process
                process.OutputDataReceived += (sender, e) => Console.WriteLine(e.Data);
                process.ErrorDataReceived += (sender, e) => Console.WriteLine("Error: " + e.Data);

                // Start the process and wait for it to exit
                process.Start();
                process.BeginOutputReadLine();
                process.BeginErrorReadLine();
                process.WaitForExit();

                // Show a popup if requested
                if (showPopup && process.ExitCode != 0)
                {
                    MessageBox.Show($"Process exited with code {process.ExitCode}", "Process Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show($"An error occurred: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }
}
