using System;
using System.IO;

public class FileCopier
{
    public void CopyFiles(string sourceDir, string targetDir, string[] includeExtensions, string[] excludeExtensions)
    {
        // Ensure the directories exist
        Directory.CreateDirectory(targetDir);

        // Get all files in the source directory and subdirectories
        var files = Directory.GetFiles(sourceDir, "*.*", SearchOption.AllDirectories);

        foreach (var file in files)
        {
            string relativePath = Path.GetRelativePath(sourceDir, file);
            string targetFilePath = Path.Combine(targetDir, relativePath);

            // Check if the file should be included based on its extension
            bool includeFile = false;
            foreach (var ext in includeExtensions)
            {
                if (Path.GetExtension(file).Equals(ext, StringComparison.OrdinalIgnoreCase))
                {
                    includeFile = true;
                    break;
                }
            }

            // Check if the file should be excluded based on its extension
            bool excludeFile = false;
            foreach (var ext in excludeExtensions)
            {
                if (Path.GetExtension(file).Equals(ext, StringComparison.OrdinalIgnoreCase))
                {
                    excludeFile = true;
                    break;
                }
            }

            // Copy the file if it should be included and not excluded
            if (includeFile && !excludeFile)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(targetFilePath));
                File.Copy(file, targetFilePath);
            }
        }
    }
}
