using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class Program
{
    public static async Task Main(string[] args)
    {
        string executablePath = "path/to/your/executable";
        string arguments = "arguments for the executable";

        try
        {
            var processInfo = new ProcessStartInfo(executablePath, arguments)
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            int maxRetries = 5;
            int retryDelay = 1000; // milliseconds

            for (int attempt = 0; attempt < maxRetries; attempt++)
            {
                try
                {
                    using (var process = new Process { StartInfo = processInfo })
                    {
                        process.Start();
                        await Task.WhenAll(process.WaitForExitAsync(), ReadOutputAndError(process));
                    }
                    break; // Successfully executed the process, exit the loop
                }
                catch (Exception ex)
                {
                    if (attempt == maxRetries - 1) // Last attempt
                    {
                        Console.WriteLine($"Failed to execute process after {maxRetries} attempts: {ex.Message}");
                        return;
                    }
                    else
                    {
                        Console.WriteLine($"Attempt {attempt + 1}/{maxRetries}: Failed to execute process, retrying in {retryDelay} ms...");
                        await Task.Delay(retryDelay);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private static async Task ReadOutputAndError(Process process)
    {
        var outputTask = process.StandardOutput.ReadToEndAsync();
        var errorTask = process.StandardError.ReadToEndAsync();

        await Task.WhenAll(outputTask, errorTask);

        string output = outputTask.Result;
        string error = errorTask.Result;

        Console.WriteLine("Output: " + output);
        Console.WriteLine("Error: " + error);
    }
}
