using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public class DesEncryptionHelper
{
    private static readonly byte[] Key = { 0x01, 0x23, 0x45, 0x67, (byte)0x89, (byte)0xAB, (byte)0xCD, (byte)0xEF };

    public static string DecryptDesMessage(string hexEncryptedMessage)
    {
        if (!IsHexStringValid(hexEncryptedMessage))
        {
            throw new ArgumentException("Input is not a valid hexadecimal representation.");
        }

        byte[] encryptedBytes = HexStringToByteArray(hexEncryptedMessage);
        string decryptedMessage;

        using (var des = new DESCryptoServiceProvider())
        {
            des.Key = Key;
            des.Mode = CipherMode.ECB;
            des.Padding = PaddingMode.PKCS7;

            try
            {
                byte[] decryptedBytes = des.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                decryptedMessage = Encoding.ASCII.GetString(decryptedBytes);
            }
            catch (Exception ex)
            {
                throw new CryptographicException("Failed to decrypt the message.", ex);
            }
        }

        return decryptedMessage;
    }

    private static bool IsHexStringValid(string hexString)
    {
        return !string.IsNullOrEmpty(hexString) && hexString.Length % 2 == 0 && hexString.All(c => "0123456789ABCDEFabcdef".Contains(c));
    }

    private static byte[] HexStringToByteArray(string hexString)
    {
        int length = hexString.Length;
        byte[] byteArray = new byte[length / 2];
        for (int i = 0; i < length; i += 2)
        {
            byteArray[i / 2] = Convert.ToByte(hexString.Substring(i, 2), 16);
        }
        return byteArray;
    }
