using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public class Deserializer
{
    public static object DeserializeFromStream(byte[] data)
    {
        using (MemoryStream ms = new MemoryStream(data))
        {
            BinaryFormatter formatter = new BinaryFormatter();

            // Read the integer from the stream
            int size = BitConverter.ToInt32(ms.ToArray(), 0);

            // Read that many bytes from the stream
            byte[] objectData = new byte[size];
            ms.Read(objectData, 0, size);

            // Create a MemoryStream from the bytes
            using (MemoryStream objectMs = new MemoryStream(objectData))
            {
                // Deserialize the object from the MemoryStream
                return formatter.Deserialize(objectMs);
            }
        }
    }
}
