using System;
using System.Security.Cryptography;
using System.Text;

public class TripleDESEncryption
{
    public static string Encrypt(string input, Guid key1, Guid key2)
    {
        // Convert GUIDs to byte arrays
        byte[] keyBytes1 = key1.ToByteArray();
        byte[] keyBytes2 = key2.ToByteArray();

        // Combine the keys into a single 24-byte key for TripleDES
        byte[] tripleDesKey = new byte[24];
        Array.Copy(keyBytes1, 0, tripleDesKey, 0, 8);
        Array.Copy(keyBytes2, 0, tripleDesKey, 8, 8);
        Array.Copy(keyBytes1, 0, tripleDesKey, 16, 8);

        // Create the TripleDES provider and initialize it with the key
        using (TripleDESCryptoServiceProvider desProvider = new TripleDESCryptoServiceProvider())
        {
            desProvider.Key = tripleDesKey;
            desProvider.Mode = CipherMode.ECB;
            desProvider.Padding = PaddingMode.PKCS7;

            // Convert the input string to a byte array and encrypt it
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] encryptedBytes = desProvider.CreateEncryptor().TransformFinalBlock(inputBytes, 0, inputBytes.Length);

            // Convert the encrypted bytes to a base64-encoded string and return it
            return Convert.ToBase64String(encryptedBytes);
        }
    }
}
