using System;
using System.Xml.Linq;
using System.Linq;

public class ConfigUpdater
{
    public int UpdateConfig(string filePath, string sectionXPath)
    {
        try
        {
            // Load the configuration file
            XDocument configDoc = XDocument.Load(filePath);

            // Select and remove the specific section using XPath
            var sectionsToRemove = configDoc.XPathSelectElements(sectionXPath);
            int removedCount = sectionsToRemove.Count();
            foreach (var section in sectionsToRemove)
            {
                section.Remove();
            }

            // Save the updated configuration file
            configDoc.Save(filePath);

            return removedCount;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"An error occurred: {ex.Message}");
            throw;
        }
    }
}
