using System;
using System.Xml.Linq;

public class XmlUpdater
{
    public static string UpdateXmlFile(string filePath, string xpathToElement, string insertAfterXPath)
    {
        try
        {
            XDocument doc = XDocument.Load(filePath);
            var elementToRemove = doc.XPathSelectElement(xpathToElement);

            if (elementToRemove == null)
            {
                throw new Exception($"Element not found using XPath: {xpathToElement}");
            }

            // Find the element after which to insert the removed element
            var parent = elementToRemove.Parent;
            var referenceElement = parent?.XPathSelectElement(insertAfterXPath);

            if (referenceElement != null)
            {
                parent?.ReplaceNodes((parent as XContainer)?.Elements().Except(new[] { elementToRemove }).ToList());
            }
            else
            {
                // If insertAfterXPath is not provided, simply remove the element
                elementToRemove.Remove();
            }

            return doc.ToString();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
            throw;
        }
    }
}
