public class XmlizedPropertyAttribute : Attribute
{
    public string Path { get; set; }
}

public interface IExportToXmlable
{
    XmlNode ExportToXml();
}

public static class ObjectToXmlConverter
{
    public static XmlDocument ConvertObjectToXml(object obj)
    {
        var xmlDoc = new XmlDocument();
        var rootElement = xmlDoc.CreateElement("root");
        xmlDoc.AppendChild(rootElement);

        foreach (var property in obj.GetType().GetProperties())
        {
            var attribute = property.GetCustomAttribute<XmlizedPropertyAttribute>();
            if (attribute != null)
            {
                var element = xmlDoc.CreateElement(attribute.Path);
                rootElement.AppendChild(element);

                var value = property.GetValue(obj);
                if (value is IExportToXmlable exportable)
                {
                    var exportedNode = exportable.ExportToXml();
                    element.AppendChild(xmlDoc.ImportNode(exportedNode, true));
                }
                else
                {
                    element.InnerText = value?.ToString() ?? string.Empty;
                }
            }
        }

        return xmlDoc;
    }
}
