public class ConfigurationUpdater
{
    public XDocument UpdateConfiguration(string filePath, string xmlFragment, string xpathExpression)
    {
        // Load the configuration file
        XDocument config = XDocument.Load(filePath);

        // Parse the XML fragment to an XElement
        XElement newProvider = XElement.Parse(xmlFragment);

        // Insert the new search provider section after the specified XPath expression
        var targetNode = config.XPathSelectElement(xpathExpression);
        if (targetNode != null)
        {
            targetNode.AddAfterSelf(newProvider);
        }
        else
        {
            throw new InvalidOperationException("The specified XPath expression does not match any element in the configuration file.");
        }

        // Save and return the updated configuration file
        config.Save(filePath);
        return config;
    }
}
