using System;
using System.Xml;

public class XmlConfigHelper
{
    public static void RemoveAndCreateConfigurationNode(string xmlFilePath, string keyValue)
    {
        XmlDocument doc = new XmlDocument();
        doc.Load(xmlFilePath);

        XmlNode nodeToRemove = FindNodeByKey(doc, keyValue);
        if (nodeToRemove != null)
        {
            RemoveNode(nodeToRemove);
        }

        CreateNewConfigurationNode(doc, keyValue);
        doc.Save(xmlFilePath);
    }

    private static XmlNode FindNodeByKey(XmlDocument doc, string keyValue)
    {
        XmlNodeList nodes = doc.SelectNodes($"//*[@key='{keyValue}']");
        return nodes.Count > 0 ? nodes[0] : null;
    }

    private static void RemoveNode(XmlNode nodeToRemove)
    {
        if (nodeToRemove != null && nodeToRemove.ParentNode != null)
        {
            nodeToRemove.ParentNode.RemoveChild(nodeToRemove);
        }
    }

    private static void CreateNewConfigurationNode(XmlDocument doc, string keyValue)
    {
        XmlElement newNode = doc.CreateElement("configuration");
        newNode.SetAttribute("key", keyValue);
        doc.DocumentElement.AppendChild(newNode);
    }
}
