using System.Xml;
using System.IO;

public class ConfigurationLoader
{
    public List<Setting> LoadSettings(string xmlFilePath)
    {
        List<Setting> settings = new List<Setting>();

        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFilePath);
            XmlElement root = doc.DocumentElement;

            foreach (XmlNode node in root.ChildNodes)
            {
                if (node.Name == "setting")
                {
                    Setting setting = new Setting();
                    foreach (XmlAttribute attr in node.Attributes)
                    {
                        switch (attr.Name)
                        {
                            case "name":
                                setting.Name = attr.Value;
                                break;
                            case "value":
                                setting.Value = attr.Value;
                                break;
                            // Add more cases as needed for other attributes
                        }
                    }
                    settings.Add(setting);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error loading XML configuration file: " + ex.Message);
        }

        return settings;
    }
}

public class Setting
{
    public string Name { get; set; }
    public string Value { get; set; }
