public class XPathHelper
{
    public static string GetTagValue(XPathNavigator navigator, string tagName)
    {
        if (navigator == null || string.IsNullOrEmpty(tagName))
        {
            throw new ArgumentException("Invalid arguments");
        }

        XPathNodeIterator nodeIterator = navigator.SelectSingleNode(tagName);
        if (nodeIterator != null && nodeIterator.MoveNext())
        {
            string value = nodeIterator.Current.Value;
            return value?.Trim();
        }

        return null;
    }
}
