using System;
using System.Security.Cryptography;
using System.Text;

public class SymmetricEncryptionTester
{
    public void TestSymmetricEncryption(string algorithmName, byte[] key, string plaintext)
    {
        // Check if the key size is correct for the selected algorithm
        int keySize = GetKeySizeInBits(algorithmName);
        if (key.Length * 8 != keySize)
        {
            throw new ArgumentException($"Invalid key size. Expected {keySize} bits, but got {key.Length * 8} bits.");
        }

        // Check the effective key size and block size for the selected algorithm
        using (SymmetricAlgorithm symmetricAlgorithm = SymmetricAlgorithm.Create(algorithmName))
        {
            if (symmetricAlgorithm.KeySize != keySize)
            {
                throw new ArgumentException($"Invalid effective key size for {algorithmName}. Expected {keySize} bits, but got {symmetricAlgorithm.KeySize} bits.");
            }
            if (symmetricAlgorithm.BlockSize != symmetricAlgorithm.KeySize)
            {
                throw new ArgumentException($"Invalid block size for {algorithmName}. Expected {symmetricAlgorithm.KeySize} bits, but got {symmetricAlgorithm.BlockSize} bits.");
            }
        }

        // Encrypt the plaintext message
        byte[] encryptedMessage = Encrypt(algorithmName, key, Encoding.UTF8.GetBytes(plaintext));

        // Decrypt the encrypted message
        byte[] decryptedMessage = Decrypt(algorithmName, key, encryptedMessage);

        // Check if the decrypted message is the same as the original plaintext message
        string decryptedText = Encoding.UTF8.GetString(decryptedMessage);
        if (plaintext != decryptedText)
        {
            throw new Exception("Decryption failed. The decrypted message does not match the original plaintext.");
        }
    }

    private int GetKeySizeInBits(string algorithmName)
    {
        switch (algorithmName)
        {
            case "AES":
                return 128; // Default AES key size is 128 bits, but can be changed to other values like 192 or 256
            default:
                throw new ArgumentException("Unsupported algorithm.");
        }
    }

    private byte[] Encrypt(string algorithmName, byte[] key, byte[] plaintext)
    {
        using (SymmetricAlgorithm symmetricAlgorithm = SymmetricAlgorithm.Create(algorithmName))
        {
            symmetricAlgorithm.Key = key;
            symmetricAlgorithm.Mode = CipherMode.ECB;
            symmetricAlgorithm.Padding = PaddingMode.Zeros;

            using (ICryptoTransform encryptor = symmetricAlgorithm.CreateEncryptor())
            {
                return encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
            }
        }
    }

    private byte[] Decrypt(string algorithmName, byte[] key, byte[] encryptedMessage)
    {
        using (SymmetricAlgorithm symmetricAlgorithm = SymmetricAlgorithm.Create(algorithmName))
        {
            symmetricAlgorithm.Key = key;
            symmetricAlgorithm.Mode = CipherMode.ECB;
            symmetricAlgorithm.Padding = PaddingMode.Zeros;

            using (ICryptoTransform decryptor = symmetricAlgorithm.CreateDecryptor())
            {
                return decryptor.TransformFinalBlock(encryptedMessage, 0, encryptedMessage.Length);
            }
        }
    }
}
