import org.hamcrest.Matchers;

public class LuceneComparison {
    public static void compareFields(IndexReader reader, int docId1, int docId2, String field1, String field2) throws IOException {
        Document doc1 = reader.document(docId1);
        Document doc2 = reader.document(docId2);

        String value1 = doc1.get(field1);
        String value2 = doc2.get(field2);

        // Check if both fields exist in both documents
        MatcherAssert.assertThat("Field " + field1 + " exists in document 1", value1, Matchers.notNullValue());
        MatcherAssert.assertThat("Field " + field2 + " exists in document 2", value2, Matchers.notNullValue());

        // Compare the values of the fields
        MatcherAssert.assertThat(field1 + " and " + field2 + " have the same content", value1, Matchers.equalTo(value2));
    }
}
