import java.util.*;

public class PairMover {
    public static void movePairs(List<Pair> pairs, double percentage) {
        int totalPairs = pairs.size();
        int targetProcessed = (int) (totalPairs * percentage);
        int processedCount = 0;

        Random rand = new Random();

        while (processedCount < targetProcessed) {
            for (int i = 0; i < totalPairs; i++) {
                if (rand.nextDouble() <= 0.5 && i != totalPairs - 1) { // 50% chance to move the pair
                    Pair currentPair = pairs.get(i);
                    int randomIndex = rand.nextInt(totalPairs);
                    pairs.set(randomIndex, currentPair);
                    processedCount++;
                }
                System.out.println("Current pair is " + (i == totalPairs - 1 ? "last" : "not last"));
            }
        }
    }

    static class Pair {
        int randomInt;
        boolean boolValue;

        Pair(int randomInt, boolean boolValue) {
            this.randomInt = randomInt;
            this.boolValue = boolValue;
        }
    }
}
