import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.FileSystem;
import java.util.Random;

public class RandomBinaryDataGenerator {
    public static File generateRandomBinaryData(FileSystem fileSystem, String folderPath, String fileName, int length) throws IOException {
        File folder = new File(folderPath);
        if (!folder.exists()) {
            folder.mkdirs(); // Ensure the directory exists
        }

        File file = new File(folder, fileName);
        try (FileOutputStream fos = new FileOutputStream(file)) {
            Random random = new Random();
            byte[] buffer = new byte[8192]; // Buffer size for writing data
            int bytesRead;

            while (length > 0) {
                if (length < buffer.length) {
                    bytesRead = length;
                } else {
                    bytesRead = buffer.length;
                }
                for (int i = 0; i < bytesRead; i++) {
                    buffer[i] = (byte) random.nextInt(256); // Generate random byte values
                }
                fos.write(buffer, 0, bytesRead);
                length -= bytesRead;
            }
        }
        return file;
    }
}
