import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class ObjectListHandler {
    public List<Object> replaceObjects(List<Object> originalList) {
        Random random = new Random();
        double stdDev = 0.2 * originalList.size();
        List<Object> resultList = new ArrayList<>(originalList);
        List<Object> discreteValues = new ArrayList<>();

        for (int i = 0; i < originalList.size(); i++) {
            if (random.nextDouble() < 0.5) { // Replace with a new object from Gaussian distribution
                double newValue = random.nextGaussian() * stdDev;
                resultList.set(i, newValue);
                discreteValues.add(newValue);
            }
        }

        return resultList;
    }
}
