import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

class Graph {
    private int vertices;
    private int edges;
    private AtomicInteger completedThreads = new AtomicInteger(0);

    public Graph(int vertices, int edges) {
        this.vertices = vertices;
        this.edges = edges;
    }

    public void traverseGraph() {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        for (int i = 0; i < 4; i++) {
            executor.execute(() -> {
                // Simulate graph traversal work
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                completedThreads.incrementAndGet();
            });
        }
        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void printStats() {
        System.out.println("Vertices: " + vertices);
        System.out.println("Edges: " + edges);
        System.out.println("Completed Threads: " + completedThreads.get());
    }
}

public class ConcurrentGraphTraversal {
    public static void main(String[] args) {
        Graph graph = new Graph(10, 20);
        graph.traverseGraph();
        graph.printStats();
    }
