import java.io.*;

public class CommandExecutor {

    public static ProcessReturnInfo executeCommand(String command) throws IOException {
        Process process = Runtime.getRuntime().exec(command);

        StringBuilder stdout = new StringBuilder();
        StringBuilder stderr = new StringBuilder();

        StreamGobbler outputGobbler = new StreamGobbler(process.getInputStream());
        StreamGobbler errorGobbler = new StreamGobbler(process.getErrorStream());

        outputGobbler.start();
        errorGobbler.start();

        int exitCode = process.waitFor();

        outputGobbler.join();
        errorGobbler.join();

        return new ProcessReturnInfo(exitCode, stdout.toString(), stderr.toString());
    }

    private static class StreamGobbler extends Thread {
        private InputStream inputStream;
        private StringBuilder stringBuilder = new StringBuilder();

        public StreamGobbler(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        @Override
        public void run() {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    stringBuilder.append(line).append("\n");
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public StringBuilder getStringBuilder() {
            return stringBuilder;
        }
    }

    public static class ProcessReturnInfo {
        private int exitCode;
        private String stdout;
        private String stderr;

        public ProcessReturnInfo(int exitCode, String stdout, String stderr) {
            this.exitCode = exitCode;
            this.stdout = stdout;
            this.stderr = stderr;
        }

        public int getExitCode() {
            return exitCode;
        }

        public String getStdout() {
            return stdout;
        }

        public String getStderr() {
            return stderr;
        }
    }
}
