import java.io.IOException;
import java.lang.reflect.Array;
import java.util.Collection;
import java.util.Map;

public class JsonGenerator {

    public static String toJson(Object object) throws IOException {
        StringBuilder json = new StringBuilder();
        buildJsonString(json, object);
        return json.toString();
    }

    private static void buildJsonString(StringBuilder json, Object object) throws IOException {
        if (object == null) {
            json.append("null");
        } else if (object instanceof String) {
            json.append('"').append(escape((String) object)).append('"');
        } else if (object instanceof Number || object instanceof Boolean) {
            json.append(object.toString());
        } else if (object.getClass().isArray()) {
            json.append('[');
            boolean first = true;
            for (int i = 0; i < Array.getLength(object); i++) {
                if (!first) {
                    json.append(',');
                }
                buildJsonString(json, Array.get(object, i));
                first = false;
            }
            json.append(']');
        } else if (object instanceof Collection) {
            json.append('[');
            boolean first = true;
            for (Object item : ((Collection<?>) object)) {
                if (!first) {
                    json.append(',');
                }
                buildJsonString(json, item);
                first = false;
            }
            json.append(']');
        } else if (object instanceof Map) {
            json.append('{');
            boolean first = true;
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) object).entrySet()) {
                if (!first) {
                    json.append(',');
                }
                buildJsonString(json, entry.getKey());
                json.append(':');
                buildJsonString(json, entry.getValue());
                first = false;
            }
            json.append('}');
        } else {
            throw new IllegalArgumentException("Unsupported type: " + object.getClass().getName());
        }
    }

    private static String escape(String str) {
        StringBuilder sb = new StringBuilder();
        for (char c : str.toCharArray()) {
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < ' ') {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }
}
