import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

public class WeightedItem<T> {
    private T item;
    private double weight;

    public WeightedItem(T item, double weight) {
        this.item = item;
        this.weight = weight;
    }

    public T getItem() {
        return item;
    }

    public double getWeight() {
        return weight;
    }
}

public class WeightedRandomizer<T> {
    private List<WeightedItem<T>> items;
    private Function<WeightedItem<T>, Double> normalizer;

    public WeightedRandomizer(List<WeightedItem<T>> items, Function<WeightedItem<T>, Double> normalizer) {
        this.items = items;
        this.normalizer = normalizer;
    }

    public Map<T, Double> getNormalizedWeights() {
        double totalWeight = items.stream().mapToDouble(item -> normalizer.apply(item)).sum();
        return items.stream()
                .collect(Collectors.toMap(
                        WeightedItem::getItem,
                        item -> normalizer.apply(item) / totalWeight
                ));
    }
}
