public class DrawableCropper {
    public static RectF cropDrawable(RectF drawableBounds, RectF viewport) {
        float aspectRatioDrawable = drawableBounds.width() / drawableBounds.height();
        float aspectRatioViewport = viewport.width() / viewport.height();

        // Determine the maximum possible crop rectangle based on aspect ratios
        RectF maxCropRect = new RectF(0, 0, 0, 0);
        if (aspectRatioDrawable > aspectRatioViewport) {
            maxCropRect.right = viewport.width();
            maxCropRect.bottom = viewport.width() / aspectRatioDrawable;
        } else {
            maxCropRect.bottom = viewport.height();
            maxCropRect.right = viewport.height() * aspectRatioDrawable;
        }

        // Randomly scale the crop rectangle by a factor between 0 and 1, with a minimum size constraint
        Random random = new Random();
        float scaleFactor = random.nextFloat();
        if (scaleFactor < 0.5f) {
            scaleFactor = 0.5f;
        }
        maxCropRect.right *= scaleFactor;
        maxCropRect.bottom *= scaleFactor;

        // Randomly offset the crop rectangle within the drawable bounds
        float offsetX = random.nextFloat() * (drawableBounds.width() - maxCropRect.right);
        float offsetY = random.nextFloat() * (drawableBounds.height() - maxCropRect.bottom);
        maxCropRect.left = drawableBounds.left + offsetX;
        maxCropRect.top = drawableBounds.top + offsetY;

        return new RectF(maxCropRect);
    }
}
