import java.io.IOException;
import java.nio.channels.Channel;
import java.nio.channels.ClosedByInterruptException;
import java.nio.channels.SocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class RemoteConnectionHandler {

    private SocketChannel channel;
    private ExecutorService executor;

    public void setupConnection(String remoteAddress) throws IOException {
        channel = SocketChannel.open();
        channel.connect(new InetSocketAddress(remoteAddress));
        executor = Executors.newSingleThreadExecutor();
        executor.submit(() -> handleConnectionStateChanges());
    }

    private void handleConnectionStateChanges() {
        try {
            while (!Thread.currentThread().isInterrupted()) {
                if (channel.isOpen()) {
                    System.out.println("Channel is open.");
                } else if (channel.isConnected()) {
                    System.out.println("Channel is connected.");
                } else if (channel.isShutdown()) {
                    System.out.println("Channel is shutdown.");
                } else if (channel.isInputShutdown() && channel.isOutputShutdown()) {
                    System.out.println("Channel is fully shut down.");
                    break;
                }

                // Add more state checks as needed

                Thread.sleep(1000); // Check every second
            }
        } catch (ClosedByInterruptException e) {
            System.out.println("Connection was closed by interrupt.");
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            try {
                channel.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
            executor.shutdown();
        }
