import java.util.*;

public class GeoPointComparator {
    public static void compareGeographicalPoints(List<List<Double>> set1, List<List<Double>> set2, double tolerance) throws Exception {
        if (set1.size() != set2.size()) {
            throw new Exception("The sets have different sizes.");
        }

        for (int i = 0; i < set1.size(); i++) {
            List<Double> points1 = set1.get(i);
            List<Double> points2 = set2.get(i);

            if (points1.size() != points2.size()) {
                throw new Exception("Document at index " + i + " has different number of values.");
            }

            for (int j = 0; j < points1.size(); j++) {
                double value1 = points1.get(j);
                double value2 = points2.get(j);

                if (value1 > value2) {
                    throw new Exception("Values in document at index " + i + " are not in increasing order.");
                }

                double distance = Math.abs(value1 - value2);
                if (distance > tolerance) {
                    throw new Exception("Values at position " + j + " in document at index " + i + " differ by more than the tolerance.");
                }
            }
        }
    }
}
