import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;

public class AESCTREncryption {
    public static void main(String[] args) throws Exception {
        // Generate a 256-bit AES key
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256);
        byte[] aesKey = keyGen.generateKey().getEncoded();

        // Input message to be encrypted
        String inputMessage = "Hello, World!";
        byte[] plainText = inputMessage.getBytes(StandardCharsets.UTF_8);

        // Generate IV (Initialization Vector)
        SecureRandom random = new SecureRandom();
        byte[] iv = new byte[16];
        random.nextBytes(iv);

        // Create a cipher instance for AES in CTR mode
        Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
        SecretKeySpec keySpec = new SecretKeySpec(aesKey, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

        // Encrypt the message
        byte[] encryptedText = cipher.doFinal(plainText);

        // Output the encrypted message in hexadecimal format
        StringBuilder hexString = new StringBuilder();
        for (byte b : encryptedText) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        System.out.println("Encrypted Message: " + hexString.toString());
    }
}
