import java.util.Date;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class DateRangeProcessor {

    public static String processDateRange(String dateRange) throws ParseException, NoSuchAlgorithmException {
        // Split the input string into start and end dates
        String[] dates = dateRange.split("/");
        if (dates.length != 2) {
            throw new IllegalArgumentException("Invalid date range format. Expected 'startDate/endDate'.");
        }

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        Date startDate = sdf.parse(dates[0]);
        Date endDate = sdf.parse(dates[1]);

        // Calculate the interval between the two dates
        long startTimeInMillis = startDate.getTime();
        long endTimeInMillis = endDate.getTime();
        long intervalInMillis = endTimeInMillis - startTimeInMillis;

        // Format the interval as a string
        String intervalString = "start/end";

        // Hash the input string and prefix the result to the interval string
        String hashedInput = hashString(dateRange);
        return hashedInput + "/" + intervalString;
    }

    private static String hashString(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = md.digest(input.getBytes());

        // Convert the byte array to a hexadecimal string
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }
}
