                byte[] dataBuffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(dataBuffer)) != -1) {
                    outputStream.write(dataBuffer, 0, bytesRead);
                }
            }
        } catch (IOException e) {
            System.out.println("Error downloading file: " + e.getMessage());
            return null;
        }

        return savePath;
    }
}
