public class NonBlockingClient {
    public static void main(String[] args) {
        String serverAddress = "localhost"; // Change this to the server's address if needed
        int port = 12345; // Change this to the server's port number

        try (SocketChannel socketChannel = SocketChannel.open()) {
            socketChannel.configureBlocking(false);
            InetSocketAddress inetSocketAddress = new InetSocketAddress(serverAddress, port);
            if (!socketChannel.connect(inetSocketAddress)) {
                while (!socketChannel.finishConnect()) {
                    System.out.println("Attempting to connect...");
