import java.io.*;
import java.util.*;

public class POS_Tagger {
    private static final String MODEL_FILE = "hmm_model.txt";

    public static void main(String[] args) throws IOException {
        // Load the HMM model from a file
        Map<String, Map<String, Double>> hmmModel = loadHMMModel(MODEL_FILE);

        // Example input text
        String inputText = "The quick brown fox jumps over the lazy dog";

        // Perform POS tagging on the input text
        List<String> taggedWords = tagPOS(inputText, hmmModel);

        // Print the tagged words
        for (String word : taggedWords) {
            System.out.println(word);
        }
    }

    private static Map<String, Map<String, Double>> loadHMMModel(String fileName) throws IOException {
        Map<String, Map<String, Double>> model = new HashMap<>();
        BufferedReader reader = new BufferedReader(new FileReader(fileName));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\\s+");
            if (parts.length < 3) continue;
            String word = parts[0];
            String tag = parts[1];
            double probability = Double.parseDouble(parts[2]);
            model.putIfAbsent(word, new HashMap<>());
            model.get(word).put(tag, probability);
        }
        reader.close();
        return model;
    }

    private static List<String> tagPOS(String inputText, Map<String, Map<String, Double>> hmmModel) {
        List<String> taggedWords = new ArrayList<>();
        String[] words = inputText.split("\\s+");
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            Map<String, Double> tagProbabilities = hmmModel.get(word);
            if (tagProbabilities != null) {
                // Find the tag with the highest probability for this word
                String bestTag = "";
                double maxProbability = -Double.MAX_VALUE;
                for (Map.Entry<String, Double> entry : tagProbabilities.entrySet()) {
                    if (entry.getValue() > maxProbability) {
                        maxProbability = entry.getValue();
                        bestTag = entry.getKey();
                    }
                }
                taggedWords.add(word + "/" + bestTag);
            } else {
                // If the word is not in the model, assign a default tag (e.g., NN for noun)
                taggedWords.add(word + "/NN");
            }
        }
        return taggedWords;
    }
}
