import java.io.*;
import java.net.*;

public class DictionaryDownloader {
    public static void main(String[] args) {
        String url = "http://example.com/dictionary.txt"; // Replace with the actual URL of the dictionary file
        String tempFilePath = downloadDictionary(url);
        replaceExistingDictionary(tempFilePath);
    }

    private static String downloadDictionary(String urlStr) {
        try (InputStream is = new URL(urlStr).openStream();
             FileOutputStream fos = new FileOutputStream("dictionary.tmp")) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return "dictionary.tmp";
    }

    private static void replaceExistingDictionary(String tempFilePath) {
        File existingDictFile = new File("dictionary.txt");
        if (existingDictFile.exists()) {
            boolean deleted = existingDictFile.delete();
            if (!deleted) {
                System.err.println("Failed to delete the existing dictionary file.");
                return;
            }
        }
        File tempFile = new File(tempFilePath);
        boolean renamed = tempFile.renameTo(existingDictFile);
        if (!renamed) {
            System.err.println("Failed to rename the temporary file to the existing dictionary file.");
        }
    }
}
