public class HttpClientExample {
    private final HttpClient httpClient = new HttpClient();
    private final String tokenHeaderName = "Authorization";
    private final String gzipEncoding = "gzip";

    public String sendPostRequest(String uri, String requestBody, String mediaType, String token, Double rateLimit) throws IOException {
        if (rateLimit != null && rateLimit > 0) {
            // Implement rate limiter logic here
            // For simplicity, we will just sleep for the required time to simulate a delay.
            try {
                Thread.sleep((long) (1000 / rateLimit));
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
