public class DatagramConnector {
    public static DatagramConnector setupDatagramConnection(String uri) throws IllegalArgumentException {
        if (uri == null || uri.isEmpty()) {
            throw new IllegalArgumentException("URI cannot be empty");
        }

        // Parse the URI to get host and port
        String[] parts = uri.split(":");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid URI format. Expected format: host:port");
        }

        String host = parts[0];
        int port;
