import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.xerial.snappy.Snappy;

public class LZOCompressor {
    public static String compressAndGetMD5(String filePath, int compressionLevel) throws IOException, NoSuchAlgorithmException {
        // Read the file content into a byte array
        FileInputStream fis = new FileInputStream(filePath);
        byte[] inputBytes = fis.readAllBytes();
        fis.close();

        // Compress the byte array using LZO algorithm with specified compression level
        byte[] compressedBytes = Snappy.compress(inputBytes, compressionLevel);

        // Write the compressed bytes to a temporary file
        String tempFilePath = filePath + ".lzo";
        FileOutputStream fos = new FileOutputStream(tempFilePath);
        fos.write(compressedBytes);
        fos.close();

        // Calculate the MD5 hash of the compressed file
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(compressedBytes);

        // Convert the byte array to a hexadecimal string representation
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }

        // Delete the temporary compressed file
        java.nio.file.Files.deleteIfExists(java.nio.file.Paths.get(tempFilePath));

        return sb.toString();
    }
}
