                signer.update(buffer, 0, bytesRead);
            }
            fis.close();

            byte[] signature = signer.sign();
            String encodedSignature = Base64.getEncoder().encodeToString(signature);

            System.out.println("Signature: " + encodedSignature);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
