import java.io.BufferedReader;
import java.io.InputStreamReader;

public class SystemCommandExecutor {

    public String executeSystemCommand(String command, boolean waitForCompletion) throws Exception {
        // Execute the system command
        Process process = Runtime.getRuntime().exec(command);

        StringBuilder outputBuilder = new StringBuilder();
        StringBuilder errorBuilder = new StringBuilder();

        // Read the standard output of the command
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                outputBuilder.append(line).append("\n");
            }
        }

        // Read the standard error of the command
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                errorBuilder.append(line).append("\n");
            }
        }

        // Wait for the command to complete if requested
        if (waitForCompletion) {
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        }

        // Combine standard output and error into a single string
        String result = outputBuilder.toString() + "\n" + errorBuilder.toString();
        return result;
    }
}
