import java.io.*;
import java.nio.file.*;

public class WalkMapFactory {
    public static WalkMap createWalkMap(String filePath) throws IOException {
        Path path = Paths.get(filePath);
        String extension = getFileExtension(path);

        if (extension == null) {
            throw new IllegalArgumentException("File does not have a valid extension");
        }

        try (InputStream inStream = Files.newInputStream(path)) {
            switch (extension) {
                case "objv":
                    return ViewMap.readFromStream(inStream);
                case "objp":
                    return PathsMap.readFromStream(inStream);
                case "jrd3m":
                    ObjectInputStream objIn = new ObjectInputStream(inStream);
                    WalkMap walkMap = (WalkMap) objIn.readObject();
                    objIn.close();
                    return walkMap;
                default:
                    throw new IllegalArgumentException("Unsupported file extension: " + extension);
            }
        } catch (ClassNotFoundException e) {
            throw new IOException("Invalid object stream", e);
        }
    }

    private static String getFileExtension(Path path) {
        String fileName = path.getFileName().toString();
        int dotIndex = fileName.lastIndexOf('.');
        return (dotIndex == -1) ? null : fileName.substring(dotIndex + 1);
    }
}
