import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.UUID;

public class UUIDGenerator {
    public static UUID generateMD5UUID() {
        try {
            // Generate a random UUID for the input to MD5 hash function
            String uuid = UUID.randomUUID().toString();
            
            // Create MessageDigest instance for MD5
            MessageDigest md = MessageDigest.getInstance("MD5");
            
            // Perform the hash calculation on the UUID string
            byte[] digest = md.digest(uuid.getBytes());
            
            // Convert the byte array to a formatted UUID string
            String uuidFromHash = bytesToUUIDString(digest);
            
            // Return the generated UUID as a UUID object
            return UUID.fromString(uuidFromHash);
        } catch (NoSuchAlgorithmException e) {
            // Handle the exception if MD5 algorithm is not available
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }
    
    private static String bytesToUUIDString(byte[] digest) {
        long mostSigBits = 0;
        long leastSigBits = 0;
        
        for (int i = 0; i < 8; i++) {
            mostSigBits = (mostSigBits << 8) | (digest[i] & 0xFF);
        }
        
        for (int i = 8; i < 16; i++) {
            leastSigBits = (leastSigBits << 8) | (digest[i] & 0xFF);
        }
        
        return (mostSigBits + "-" + leastSigBits).toUpperCase();
    }
}
