import org.xml.sax.*;
import org.xml.sax.helpers.*;
import java.util.*;
import java.io.*;

class FrequencyHandler extends DefaultHandler {
    private Map<String, Integer> prefixCount;

    public FrequencyHandler() {
        prefixCount = new HashMap<>();
    }

    @Override
    public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
        // Extract the prefix from the URI if it exists
        int lastSlashIndex = uri.lastIndexOf('/');
        String prefix;
        if (lastSlashIndex != -1) {
            prefix = uri.substring(lastSlashIndex + 1);
        } else {
            prefix = "";
        }

        // Update the count of prefixes
        prefixCount.put(prefix, prefixCount.getOrDefault(prefix, 0) + 1);
    }

    public Map<String, Integer> getPrefixCount() {
        return prefixCount;
    }
}

public class XMLPrefixCounter {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java XMLPrefixCounter file1.xml [file2.xml ...]");
            return;
        }

        for (String fileName : args) {
            try {
                SAXParserFactory factory = SAXParserFactory.newInstance();
                SAXParser parser = factory.newSAXParser();
                FrequencyHandler handler = new FrequencyHandler();
                parser.parse(new File(fileName), handler);

                Map<String, Integer> prefixCount = handler.getPrefixCount();
                System.out.println("File: " + fileName);
                for (Map.Entry<String, Integer> entry : prefixCount.entrySet()) {
                    System.out.println("Prefix: " + entry.getKey() + ", Frequency: " + entry.getValue());
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
