import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5HashGenerator {
    public static String generateMD5(String input) throws NoSuchAlgorithmException {
        // Create MessageDigest instance for MD5
        MessageDigest md = MessageDigest.getInstance("MD5");

        // Perform the hash calculation
        byte[] messageDigest = md.digest(input.getBytes());

        // Convert the byte array into a signum representation
        BigInteger no = new BigInteger(1, messageDigest);

        // Convert the number to a hex string
        String hashtext = no.toString(16);

        // Pad with leading zeros to ensure it has 32 characters
        while (hashtext.length() < 32) {
            hashtext = "0" + hashtext;
        }

        return hashtext;
    }

    public static void main(String[] args) {
        try {
            String input = "exampleInput";
            String md5Hash = generateMD5(input);
            System.out.println("MD5 hash of '" + input + "' is: " + md5Hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
