public class PathHasher {
    public static String generateHashCode(Map<String, String[]> paths, String moduleName, boolean createSymlinks, boolean createHeaderMap) {
        StringBuilder combinedData = new StringBuilder();

        // Append module name
        combinedData.append(moduleName);

        // Append symlink state
        combinedData.append(createSymlinks ? "true" : "false");

        // Append header map state (simplified representation)
        combinedData.append(createHeaderMap ? "true" : "false");

        // Append paths and linked paths
        for (String path : paths.keySet()) {
            combinedData.append(path).append(",");
            String[] linkedPaths = paths.get(path);
            if (linkedPaths != null) {
                for (String linkedPath : linkedPaths) {
                    combinedData.append(linkedPath).append(",");
                }
            }
        }

        // Remove the last comma
        String dataToHash = combinedData.toString().replaceAll("\\s+", "");

        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] hashBytes = digest.digest(dataToHash.getBytes());

            // Convert the byte array to a hexadecimal string
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-1 algorithm not available", e);
        }
    }
}
