import java.io.*;

public class SingletonLoader<T> {
    private static final String FILE_NAME = "singletonInstance.ser";

    public T getSingletonInstance(Class<T> clazz) throws IOException, ClassNotFoundException {
        File file = new File(FILE_NAME);
        if (file.exists()) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                return clazz.cast(ois.readObject());
            }
        } else {
            T instance = clazz.getDeclaredConstructor().newInstance();
            saveInstanceToFile(instance);
            return instance;
        }
    }

    private void saveInstanceToFile(T instance) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(FILE_NAME))) {
            oos.writeObject(instance);
        }
    }
}
