import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.OptionalLong;

public class CommandExecutor {
    public int executeCommand(String[] command, InputStream inputStream, OutputStream outputStream, OptionalLong timeout) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command);

        // Handle input stream if provided
        if (inputStream != null) {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputStream.write((line + "\n").getBytes());
                }
            }
        }

        // Handle error stream if provided
        if (inputStream != null) {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputStream.write((line + "\n").getBytes());
                }
            }
        }

        // Handle timeout if provided
        int exitCode = process.waitFor();
        return exitCode;
    }
}
