import javax.xml.xpath.*;
import org.w3c.dom.*;
import javax.xml.parsers.*;
import java.io.*;

public class XMLParser {
    public static String evaluateXPath(String responseValue, String xpathExpression) throws Exception {
        if (responseValue == null || xpathExpression == null) {
            throw new IllegalArgumentException("Input values cannot be null");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        InputSource is = new InputSource(new StringReader(responseValue));
        Document doc = builder.parse(is);

        XPath xpath = XPathFactory.newInstance().newXPath();
        Boolean result = (Boolean) xpath.evaluate(xpathExpression, doc, XPathConstants.BOOLEAN);

        if (result != null && result) {
            return null; // No failure detail
        } else {
            String message = "XPath expression returned false";
            return message; // Failure detail with a message
        }
    }
}
