import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceStarter {
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final Random random = new Random();
    private static boolean serviceRunning = false;

    public static void main(String[] args) {
        startServiceWithRandomDelay();
    }

    private static void startServiceWithRandomDelay() {
        scheduler.scheduleAtFixedRate(() -> {
            if (!serviceRunning) {
                startService();
            } else {
                stopServiceAndSendMessage();
            }
        }, 0, getRandomDelay(), TimeUnit.SECONDS);
    }

    private static void startService() {
        System.out.println("Starting service...");
        serviceRunning = true;
    }

    private static void stopServiceAndSendMessage() {
        System.out.println("Stopping service and sending message...");
        serviceRunning = false;
    }

    private static long getRandomDelay() {
        return random.nextInt(10) + 1; // Random delay between 1 to 10 seconds
    }
}
