import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Encryptor {
    public static String encryptMessage(String message, String encodingScheme, boolean toUpperCase) {
        try {
            // Create MessageDigest instance for MD5
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Perform the hash computation
            byte[] digest = md.digest(message.getBytes());

            // Convert the byte array into a string representation
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b & 0xff));
            }

            // Optionally convert to uppercase
            String encryptedMessage = sb.toString();
            if (toUpperCase) {
                encryptedMessage = encryptedMessage.toUpperCase();
            }

            return encryptedMessage;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not available.", e);
        }
    }
}
