public class CompileJava {
    public static void main(String[] args) {
        // Check for source code file path argument
        if (args.length < 1) {
            System.err.println("Usage: java CompileJava <source_file>");
            return;
        }

        String sourceFilePath = args[0];
        File sourceFile = new File(sourceFilePath);

        // Check if the file exists and is a regular file
        if (!sourceFile.exists() || !sourceFile.isFile()) {
            System.err.println("Source file does not exist or is not a file.");
            return;
        }

        // Create a JavaCompiler instance
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();

        // Set up standard diagnostics listener
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();

        // Standard file manager for locating and managing files
        StandardJavaFileManager standardFileManager = compiler.getStandardFileManager(diagnostics, null, null);

        // Java source object from the file
        JavaFileObject javaFileObject = new JavaSourceFromString(sourceFilePath, new String(Files.readAllBytes(Paths.get(sourceFilePath))));

        // Compilation task
        StandardJavaFileManager standardJavaFileManager = (StandardJavaFileManager) standardFileManager;
        DiagnosticCollector<JavaFileObject> diagnosticCollector = new DiagnosticCollector<>();
        JavaCompiler.CompilationTask task = compiler.getTask(null, standardJavaFileManager, diagnosticCollector, null, null, Collections.singletonList(javaFileObject));

        // Perform the compilation
        boolean success = task.call();

        // Output diagnostics if any
        for (Diagnostic<? extends JavaFileObject> diagnostic : diagnostics.getDiagnostics()) {
            System.err.format("Error on line %d in file %s:%n", diagnostic.getLineNumber(), diagnostic.getSource().toUri());
            System.err.println(diagnostic.getMessage(Locale.getDefault()));
        }

        // Check if compilation was successful
        if (!success) {
            System.err.println("Compilation failed.");
            return;
        }

        // Output the compiled bytecode to a file
        try (OutputStream outputStream = new FileOutputStream("output.class")) {
            Path classPath = Paths.get(sourceFilePath).resolveSibling("output.class");
            Files.copy(classPath, outputStream);
            System.out.println("Compilation successful. Bytecode saved to 'output.class'.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

