import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;

public class FileUploader {
    private static final int MAX_RETRIES = 3;

    public static boolean uploadFile(String fileUrl, String filePath) throws IOException {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                URL url = new URL(fileUrl);
                HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                connection.setDoOutput(true);
                connection.setRequestMethod("POST");

                File fileToUpload = new File(filePath);
                OutputStream outputStream = connection.getOutputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                InputStream fileInputStream = new FileInputStream(fileToUpload);
                while ((bytesRead = fileInputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
                fileInputStream.close();
                outputStream.flush();

                int responseCode = connection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    return true;
                } else {
                    System.out.println("Failed to upload file. Response code: " + responseCode);
                }
            } catch (IOException e) {
                retryCount++;
                System.out.println("Upload attempt failed, retrying... (" + retryCount + "/" + MAX_RETRIES + ")");
            }
        }
        return false;
    }
}
