public class HttpClientExample {
    public static void main(String[] args) throws IOException, URISyntaxException {
        // Create a BasicCredentialsProvider with username and password
        BasicCredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        credentialsProvider.setCredentials(AuthScope.ANY, new UsernamePasswordCredentials("username", "password"));

        // Create a Registry for the PlainConnectionSocketFactory and SSLConnectionSocketFactory
        Registry<ConnectionSocketFactory> registry = RegistryBuilder.<ConnectionSocketFactory>create()
                .register("http", PlainConnectionSocketFactory.INSTANCE)
                .register("https", SSLConnectionSocketFactory.getSocketFactory())
                .build();

        // Create a PoolingHttpClientConnectionManager with the given registry
        PoolingHttpClientConnectionManager connectionManager = new PoolingHttpClientConnectionManager(registry);

        // Create a RequestConfig with custom settings
        RequestConfig requestConfig = RequestConfig.custom()
                .setConnectTimeout(5000)  // Connection timeout in milliseconds
                .setSocketTimeout(5000)    // Socket timeout in milliseconds
                .build();

        // Create a CloseableHttpClient using HttpClientBuilder with the given connection manager and request config
        CloseableHttpClient httpClient = HttpClientBuilder.create()
                .setConnectionManager(connectionManager)
                .setDefaultRequestConfig(requestConfig)
                .setDefaultCredentialsProvider(credentialsProvider)
                .build();

        // Create an HttpGet request to the URL
        URI uri = new URI("http://example.com");
        HttpGet request = new HttpGet(uri);

        // Execute the GET request and retrieve the response entity
        try (CloseableHttpResponse response = httpClient.execute(request)) {
            HttpEntity entity = response.getEntity();
            if (entity != null) {
                // Convert the response entity to a string using EntityUtils.toString() method
                String responseBody = EntityUtils.toString(entity);
                System.out.println("Response: " + responseBody);
            }
        }
    }
}
