import java.util.*;

public class GraphDatabase {
    private Map<String, Set<String>> graph;
    private Map<String, String> edgeHashes;

    public GraphDatabase() {
        this.graph = new HashMap<>();
        this.edgeHashes = new HashMap<>();
    }

    public void createEdges(List<VertexBuilder> vertexBuilders) {
        for (VertexBuilder builder : vertexBuilders) {
            String from = builder.getFrom();
            String to = builder.getTo();
            if (!graph.containsKey(from)) {
                graph.put(from, new HashSet<>());
            }
            if (!graph.containsKey(to)) {
                graph.put(to, new HashSet<>());
            }
            String edgeHash = hashEdge(from, to);
            if (!edgeHashes.containsKey(edgeHash) && !graph.get(from).contains(to)) {
                graph.get(from).add(to);
                edgeHashes.put(edgeHash, edgeHash);
            }
        }
    }

    private String hashEdge(String from, String to) {
        return Objects.hash(from, to) + "";
    }
}

class VertexBuilder {
    private String from;
    private String to;

    public VertexBuilder(String from, String to) {
        this.from = from;
        this.to = to;
    }

    public String getFrom() {
        return from;
    }

    public String getTo() {
        return to;
    }
}
