import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static char[] bytesToHexArray(byte[] byteArray) {
    StringBuilder hexString = new StringBuilder();
    for (byte b : byteArray) {
        String hex = Integer.toHexString(0xFF & b);
        if (hex.length() == 1) {
            hexString.append('0');
        }
        hexString.append(hex);
    }
    return hexString.toString().toCharArray();
}

public static char[] byteArrayToHexMD5(byte[] byteArray, char[] saltChars) {
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(byteArray);
        if (saltChars != null) {
            md.update(new String(saltChars).getBytes());
        }
        byte[] hashBytes = md.digest();
        return bytesToHexArray(hashBytes);
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException("MD5 algorithm not available.", e);
    }
