import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class HashFunctionGenerator {
    private static final Map<String, String> ALGORITHM_NAMES = new HashMap<>();

    static {
        ALGORITHM_NAMES.put("MD5", "MD5");
        ALGORITHM_NAMES.put("SHA-1", "SHA-1");
        ALGORITHM_NAMES.put("SHA-256", "SHA-256");
        ALGORITHM_NAMES.put("SHA-384", "SHA-384");
        ALGORITHM_NAMES.put("SHA-512", "SHA-512");
    }

    public static String generateHash(String input, String algorithm) throws NoSuchAlgorithmException {
        if (!ALGORITHM_NAMES.containsKey(algorithm)) {
            throw new IllegalArgumentException("Unsupported hash algorithm: " + algorithm);
        }

        MessageDigest md = MessageDigest.getInstance(ALGORITHM_NAMES.get(algorithm));
        byte[] inputBytes = input.getBytes();
        byte[] hashBytes = md.digest(inputBytes);

        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            String input = "example";
            System.out.println("MD5: " + generateHash(input, "MD5"));
            System.out.println("SHA-1: " + generateHash(input, "SHA-1"));
            System.out.println("SHA-256: " + generateHash(input, "SHA-256"));
            System.out.println("SHA-384: " + generateHash(input, "SHA-384"));
            System.out.println("SHA-512: " + generateHash(input, "SHA-512"));
