import java.security.NoSuchAlgorithmException;

public class MD5Example {
    public static String getMD5(String input) {
        try {
            // Create MessageDigest instance for MD5
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Add password bytes to digest
            byte[] messageDigest = md.digest(input.getBytes());

            // Convert the byte array into a signum representation
            StringBuilder hexString = new StringBuilder();

            // All possible characters for representing a hexadecimal value
            char[] hexChars = "0123456789ABCDEF".toCharArray();

            // Loop through each byte of the digest and convert it to a hexadecimal string
            for (byte b : messageDigest) {
                int v = b & 0xFF;
                hexString.append(hexChars[v >>> 4]);
                hexString.append(hexChars[v & 0x0F]);
            }

            // Return the hexadecimal string
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }
}
