import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class RandomStringGenerator {
    public static String generateRandomString(double seed) {
        try {
            // Create MessageDigest instance for SHA-256 hash function
            MessageDigest md = MessageDigest.getInstance("SHA-256");

            // Convert the seed to a byte array (assuming double is 8 bytes long)
            byte[] seedBytes = new byte[8];
            long bits = Double.doubleToRawLongBits(seed);
            for (int i = 0; i < 8; i++) {
                seedBytes[i] = (byte) ((bits >> (8 * (7 - i))) & 0xFF);
            }

            // Update the digest with the seed bytes
            md.update(seedBytes);

            // Generate the hash value
            byte[] hashBytes = md.digest();

            // Convert the hash value to a hexadecimal string
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available.", e);
        }
    }
}
