import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MaskGenerator {
    public static byte[] generateMask(int length, byte[] seed) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        int blockSize = digest.getDigestLength();
        int numBlocks = (length + blockSize - 1) / blockSize;
        byte[] mask = new byte[length];
        byte[] counterBytes = new byte[4];

        for (int i = 0; i < numBlocks; i++) {
            System.arraycopy(seed, 0, counterBytes, 0, seed.length);
            int offset = i * blockSize / 4;
            System.arraycopy(toInt32(i), 0, counterBytes, seed.length, 4);
            byte[] hash = digest.digest(counterBytes);
            System.arraycopy(hash, 0, mask, i * blockSize, Math.min(blockSize, length - i * blockSize));
        }

        return mask;
    }

    private static byte[] toInt32(int value) {
        return new byte[]{
            (byte)(value >> 24),
            (byte)(value >> 16),
            (byte)(value >> 8),
            (byte)value
        };
    }
}
