import javax.servlet.*;
import javax.servlet.http.*;

public class ConfigServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String configFilePath = "/path/to/config.file"; // Specify the path to your configuration file

        try (BufferedReader reader = new BufferedReader(new FileReader(configFilePath))) {
            StringBuilder content = new StringBuilder();
            String line;

            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }

            response.setContentType("text/plain"); // Set the content type to plain text
            response.getWriter().write(content.toString());
        } catch (IOException e) {
            response.setContentType("text/plain");
            response.getWriter().write("Error reading configuration file: " + e.getMessage());
            getServletContext().log("Error reading configuration file", e);
        }
    }
