function asyncReduce(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;

    function next(index) {
      if (index >= arr.length) {
        resolve(accumulator);
        return;
      }

      const currentValue = arr[index];

      callback(accumulator, currentValue).then((result) => {
        accumulator = result;
        next(index + 1);
      }).catch((error) => {
        reject(error);
      });
    }

    next(0);
  });
}

