const fs = require('fs');
const path = require('path');

function serveStaticResource(request, response, filePath) {
    const method = request.method;
    const fullPath = path.join(__dirname, filePath);

    if (method !== 'GET' && method !== 'HEAD') {
        response.setHeader('Allow', 'GET, HEAD');
        response.status(405).send('Method Not Allowed');
        return;
    }

    fs.access(fullPath, fs.constants.R_OK, (err) => {
        if (err) {
            console.log(`File not found: ${filePath}`);
            response.status(404).send('Not Found');
            return;
        }

        const stats = fs.statSync(fullPath);
        if (stats.isDirectory()) {
            console.log(`Redirecting to index file: ${filePath}/index.html`);
            response.status(301).setHeader('Location', `${filePath}/index.html`).send();
            return;
        }

        const stream = fs.createReadStream(fullPath);
        response.setHeader('Content-Type', 'text/html'); // Adjust based on file type

        if (method === 'HEAD') {
            response.status(200).send();
            return;
        }

        stream.pipe(response);
    });
}
