const fs = require('fs');
const path = require('path');

function checkFilesAndDirectories() {
    const cwd = process.cwd();
    const requiredFiles = ['file1.txt', 'file2.txt'];
    const requiredDirs = ['dir1', 'dir2'];

    function exists(filePath) {
        try {
            fs.accessSync(filePath, fs.constants.F_OK);
            return true;
        } catch (err) {
            return false;
        }
    }

    function checkRecursive(currentPath) {
        let allExist = true;
        for (const file of requiredFiles) {
            if (!exists(path.join(currentPath, file))) {
                allExist = false;
                break;
            }
        }
        for (const dir of requiredDirs) {
            if (!exists(path.join(currentPath, dir))) {
                allExist = false;
                break;
            }
        }
        return allExist;
    }

    return checkRecursive(cwd);
}
