#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    ACTION_TYPE_OUTPUT = 0,
    ACTION_TYPE_GROUP,
    // Add other action types here as needed
} ActionType;

typedef struct {
    ActionType type;
    uint16_t port;
} OutputAction;

typedef struct {
    ActionType type;
    uint32_t group_id;
} GroupAction;

typedef union {
    ActionType type;
    OutputAction output;
    GroupAction group;
} ParsedAction;

typedef struct {
    ParsedAction action;
    uint32_t offset;
} ParsedResult;

typedef struct {
    int error_code;
    char *message;
} ErrorResponse;

ParsedResult parse_openflow_action(uint8_t *buffer, uint32_t buffer_size, uint32_t offset) {
    if (offset + sizeof(ActionType) > buffer_size) {
        ErrorResponse error = {.error_code = -1, .message = "Buffer overflow"};
        ParsedResult result = {{0}, 0};
        memcpy(&result.action.type, &error, sizeof(ErrorResponse));
        return result;
    }

    ActionType action_type = *(ActionType *)(buffer + offset);
    uint32_t next_offset = offset + sizeof(ActionType);

    ParsedAction parsed_action;
    parsed_action.type = action_type;

    switch (action_type) {
        case ACTION_TYPE_OUTPUT:
            if (next_offset + sizeof(uint16_t) > buffer_size) {
                ErrorResponse error = {.error_code = -2, .message = "Buffer overflow"};
                ParsedResult result = {{0}, 0};
                memcpy(&result.action.type, &error, sizeof(ErrorResponse));
                return result;
            }
            parsed_action.output.port = *(uint16_t *)(buffer + next_offset);
            next_offset += sizeof(uint16_t);
            break;
        case ACTION_TYPE_GROUP:
            if (next_offset + sizeof(uint32_t) > buffer_size) {
                ErrorResponse error = {.error_code = -3, .message = "Buffer overflow"};
                ParsedResult result = {{0}, 0};
                memcpy(&result.action.type, &error, sizeof(ErrorResponse));
                return result;
            }
            parsed_action.group.group_id = *(uint32_t *)(buffer + next_offset);
            next_offset += sizeof(uint32_t);
            break;
        default:
            ErrorResponse error = {.error_code = -4, .message = "Invalid action type"};
            ParsedResult result = {{0}, 0};
            memcpy(&result.action.type, &error, sizeof(ErrorResponse));
            return result;
    }

    ParsedResult result = {parsed_action, next_offset};
    return result;
}
