function getValueFromConfig(config, key) {
    let value = config[key];

    if (value !== undefined) {
        return value;
    }

    // Check if the file exists in the current directory or a parent directory
    const path = require('path');
    const fs = require('fs');
    const util = require('util');
    const readFile = util.promisify(fs.readFile);

    async function checkDirectoryForFile(dir) {
        const filePath = path.join(dir, 'config.js');
        if (fs.existsSync(filePath)) {
            const configContent = await readFile(filePath, 'utf8');
            const configObject = JSON.parse(configContent);
            return configObject;
        }
        const parentDir = path.dirname(dir);
        if (parentDir === dir) {
            return null; // Reached the root directory without finding the file
        }
        return checkDirectoryForFile(parentDir);
    }

    async function getConfigFromFile() {
        const currentDir = process.cwd();
        const configObject = await checkDirectoryForFile(currentDir);
        if (configObject && configObject[key] !== undefined) {
            return configObject[key];
        }
        return null;
    }

    getConfigFromFile().then((result) => {
        if (result !== null) {
            value = result;
        }
    });

    // Check if the key is a package name
    const packageJsonPath = path.join(process.cwd(), 'package.json');
    if (fs.existsSync(packageJsonPath)) {
        const packageJsonContent = fs.readFileSync(packageJsonPath, 'utf8');
        const packageJsonObject = JSON.parse(packageJsonContent);
        if (packageJsonObject.dependencies && packageJsonObject.dependencies[key]) {
            value = packageJsonObject.dependencies[key];
        } else if (packageJsonObject.devDependencies && packageJsonObject.devDependencies[key]) {
            value = packageJsonObject.devDependencies[key];
        }
    }

    // Set the value in the configuration object for future reference
    config[key] = value;
    return value;
}
