function calculateBufferLength(buffer, repeat, options) {
    const escapeRegex = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); // $& means the whole matched string
    
    let groupSeparatorEscaped = escapeRegex(options.groupSeparator);
    let radixPointEscaped = escapeRegex(options.radixPoint);
    
    const bufferLength = buffer.length;
    const repeatFactor = repeat * (bufferLength + groupSeparatorEscaped.length + radixPointEscaped.length);
    
    return { length: repeatFactor, offset: 0 };
}
