const fs = require('fs');
const path = require('path');
const less = require('less');

async function compileLessFiles(sourceDir, destDir) {
    const result = {};

    async function processFile(filePath) {
        if (fs.lstatSync(filePath).isDirectory()) {
            return;
        }

        if (path.extname(filePath) === '.less') {
            try {
                const lessContent = fs.readFileSync(filePath, 'utf8');
                const css = await compileLessToCss(lessContent);
                const relativePath = path.relative(sourceDir, filePath);
                result[relativePath] = css;
            } catch (error) {
                console.error(`Error compiling ${filePath}:`, error);
            }
        }
    }

    async function compileLessToCss(lessContent) {
        const output = await less.render(lessContent, { filename: filePath });
        return output.css;
    }

    fs.promises.readdir(sourceDir).then(files => {
        files.forEach(file => {
            const fullPath = path.join(sourceDir, file);
            processFile(fullPath);
        });
    }).catch(error => {
        console.error('Error reading directory:', error);
    });

    return result;
}
