  try {
    fs.appendFileSync(filePath, text);
    console.log(`Inserted text into file: ${filePath}`);
  } catch (err) {
    console.error(`Error inserting text into file: ${filePath}`, err);
  }
}

// Function to compile Sass to CSS
function compileSassToCss(inputPath, outputPath) {
  try {
    const result = sass.compileFile(inputPath);
    fs.writeFileSync(outputPath, result.css);
    console.log(`Compiled Sass to CSS: ${inputPath} -> ${outputPath}`);
  } catch (err) {
    console.error(`Error compiling Sass to CSS: ${inputPath}`, err);
  }
}

// Function to compile TypeScript to JavaScript
function compileTypeScriptToJs(inputPath, outputPath) {
  try {
    const tsResult = typescript.transpileModule(fs.readFileSync(inputPath).toString(), {
      compilerOptions: { module: typescript.ModuleKind.CommonJS }
    });
    fs.writeFileSync(outputPath, tsResult.outputText);
    console.log(`Compiled TypeScript to JavaScript: ${inputPath} -> ${outputPath}`);
  } catch (err) {
    console.error(`Error compiling TypeScript to JavaScript: ${inputPath}`, err);
  }
}

// Function to concatenate files
function concatenateFiles(filePaths, outputFilePath) {
  try {
    const content = filePaths.map(filePath => fs.readFileSync(filePath).toString()).join('');
    fs.writeFileSync(outputFilePath, content);
    console.log(`Concatenated files: ${filePaths.join(', ')} -> ${outputFilePath}`);
