    // Check if the element matches the basic tag name
    if (tagMatch && element.tagName !== tagMatch) {
        return false;
    }

    // Check attributes
    for (let attr of attrMatch || []) {
        const [, attrName, attrValue] = attr.match(/^\[(\w+)(?:=([^=\]]*))?\]$/);
        const elementAttrValue = getAttributeValue(element, attrName);

        switch (operator) {
            case '=':
                if (attrValue && attrValue !== elementAttrValue) {
                    return false;
                }
                break;
            case '!=':
                if (attrValue === elementAttrValue) {
                    return false;
                }
                break;
            // Add more operators as needed
