  const ctx = canvas.getContext('2d');

  // Generate random position and radius
  const posX = Math.random() * canvas.width;
  const posY = Math.random() * canvas.height;
  const radius = Math.random() * 50 + 10; // Radius between 10 and 60

  // Generate random velocity (for movement)
  const velX = (Math.random() - 0.5) * 2; // Velocity between -1 and 1 in both x and y directions
  const velY = (Math.random() - 0.5) * 2;

  function drawStar() {
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const angle1 = Math.PI / 2 + (i * Math.PI / 2.5);
      const x1 = posX + radius * Math.cos(angle1);
      const y1 = posY + radius * Math.sin(angle1);

      const angle2 = Math.PI / 2 + ((i + 0.5) * Math.PI / 2.5);
      const x2 = posX + (radius / 2.675) * Math.cos(angle2); // Adjusted for smaller radius
      const y2 = posY + (radius / 2.675) * Math.sin(angle2);

      ctx.lineTo(x1, y1);
      ctx.lineTo(x2, y2);
    }
    ctx.closePath();
    ctx.fillStyle = 'yellow'; // Random color can be added here if needed
    ctx.fill();
  }

  function updatePosition() {
    posX += velX;
    posY += velY;

    // Bounce off the edges of the canvas
    if (posX < 0 || posX > canvas.width) {
      velX = -velX;
    }
    if (posY < 0 || posY > canvas.height) {
