function dfs(grid, x, y) {
    const rows = grid.length;
    const cols = grid[0].length;

    // Check for out-of-bounds or already visited nodes
    if (x < 0 || y < 0 || x >= rows || y >= cols || grid[x][y].state === 'visited') {
        return;
    }

    // Mark the current node as visited
    grid[x][y].state = 'visited';

    // Define the directions to move (up, down, left, right)
    const directions = [
        [-1, 0], [1, 0], [0, -1], [0, 1]
    ];

    // Recursively visit all adjacent nodes
    for (const [dx, dy] of directions) {
        dfs(grid, x + dx, y + dy);
    }
}

function plantRandomNode(grid) {
    const rows = grid.length;
    const cols = grid[0].length;

    // Find a random position that is not already visited
    let x, y;
    do {
        x = Math.floor(Math.random() * rows);
        y = Math.floor(Math.random() * cols);
    } while (grid[x][y].state === 'visited');

    // Plant a new node with a random value at the found position
    grid[x][y] = { x, y, value: Math.random(), state: 'unvisited' };
}

function plantNodesUntilMax(grid, maxNodes) {
    for (let i = 0; i < maxNodes; i++) {
        plantRandomNode(grid);
    }
}

function performDFSAndPlantNodes(grid, startX, startY, maxNodes) {
    // Initialize the grid with nodes having 'unvisited' state
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[i].length; j++) {
            grid[i][j] = { x: i, y: j, value: Math.random(), state: 'unvisited' };
        }
    }

    // Perform DFS starting from the given position
    dfs(grid, startX, startY);

    // Plant additional nodes until reaching the maximum number of nodes
    plantNodesUntilMax(grid, maxNodes);
}
