function reformatString(str, separator) {
    let result = '';
    let period = false;
    for (let i = 0; i < str.length; i++) {
        let char = str[i];
        if (char === '.') {
            period = true;
            result += char;
        } else if (/^\d$/.test(char)) {
            result += char;
        } else if (period) {
            // Remove trailing zeros after the decimal point
            while (result.length > 0 && result[result.length - 1] === '0') {
                result = result.slice(0, -1);
            }
            if (result.length > 0 && result[result.length - 1] === '.') {
                result = result.slice(0, -1); // Handle case that number is .000
                if (!/\d/.test(result[result.length - 1])) {
                    result += '0';
                }
            }
            period = false;
            result += char;
        } else {
            period = false;
            result += char;
        }
    }
    // Insert the separator every three digits
    let finalResult = '';
    for (let i = 0; i < result.length; i++) {
        if (/^\d$/.test(result[i]) && i > 0) {
            if ((result.length - i) % 3 === 0) {
                finalResult += separator;
            }
        }
        finalResult += result[i];
    }
    return finalResult;
}
