const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

// Function to clone a Git repository
function cloneRepository(repoUrl, targetDir) {
  const command = `git clone ${repoUrl} ${targetDir}`;
  return new Promise((resolve, reject) => {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        reject(`Error cloning repository: ${stderr}`);
      } else {
        resolve(`Repository cloned successfully to ${targetDir}`);
      }
    });
  });
}

// Function to create a symbolic link to the binary executable
function createSymbolicLink(repoPath, targetDir) {
  const binPath = path.join(repoPath, 'path', 'to', 'binary'); // Adjust this path according to your repository structure
  const linkPath = path.join(targetDir, 'binary');

  fs.symlink(binPath, linkPath, (err) => {
    if (err) {
      console.error(`Error creating symbolic link: ${err}`);
    } else {
      console.log(`Symbolic link created successfully at ${linkPath}`);
    }
  });
}

// Main function to clone the repository and create a symbolic link
async function main() {
  const repoUrl = 'https://github.com/user/repo.git'; // Replace with your repository URL
  const targetDir = '/path/to/target/directory'; // Replace with your target directory

  try {
    await cloneRepository(repoUrl, targetDir);
    const repoPath = path.join(targetDir, 'repo'); // Adjust this according to the cloned repository name
    createSymbolicLink(repoPath, targetDir);
  } catch (error) {
    console.error(error);
  }
}

main();
