const fs = require('fs');
const path = require('path');

function validateAndCreateFilesDirectories(directoryPath, options) {
    // Validate directory path
    if (typeof directoryPath !== 'string' || !fs.existsSync(directoryPath)) {
        throw new Error(`Invalid directory path: ${directoryPath}`);
    }

    // Iterate over the files and directories in the options object
    for (const [filePath, fileOptions] of Object.entries(options)) {
        const fullPath = path.join(directoryPath, filePath);

        // Check if the directory exists, create it if not
        const dirPath = path.dirname(fullPath);
        if (!fs.existsSync(dirPath)) {
            fs.mkdirSync(dirPath, { recursive: true });
        }

        // Generate an empty file if specified and it does not exist
        if (fileOptions && fileOptions.createIfMissing) {
            if (!fs.existsSync(fullPath)) {
                fs.writeFileSync(fullPath, '');
            }
        }
    }
}
