function updateParticlePosition(canvas) {
  let x = 50; // Initial x position
  let y = 50; // Initial y position
  const radius = 10; // Particle size

  canvas.addEventListener('mousemove', function(event) {
    const rect = canvas.getBoundingClientRect();
    x = event.clientX - rect.left;
    y = event.clientY - rect.top;
  });

  function drawParticle() {
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height); // Clear the canvas
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.closePath();
  }

  function update() {
    x += (Math.random() - 0.5) * 10; // Random horizontal movement
    y += (Math.random() - 0.5) * 10; // Random vertical movement
    drawParticle();
    requestAnimationFrame(update);
  }

  update();
}
