function sendMessageToIframe(iframe, message, callback) {
  // Post the message to the iframe's content window
  iframe.contentWindow.postMessage(JSON.stringify({ event: message }), '*');

  // If a callback function is provided, install it as a listener on the window object
  if (callback) {
    const uniqueName = `callback_${Date.now()}`;
    window[uniqueName] = data => callback(data);
    window.addEventListener('message', event => {
      if (event.source === iframe.contentWindow && event.data.name === message) {
        window[uniqueName](JSON.parse(event.data.data));
        delete window[uniqueName]; // Clean up the callback function
      }
    });
  }
}
