```javascript
function createAutocomplete() {
  const searchInput = document.getElementById('search-input');
  const suggestionList = document.getElementById('suggestion-list');

  // Fetch data from PHP script using AJAX
  function fetchSuggestions(query) {
    const xhr = new XMLHttpRequest();
    xhr.open('POST', 'autocomplete.php', true);
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.onreadystatechange = function() {
      if (xhr.readyState === 4 && xhr.status === 200) {
        const suggestions = JSON.parse(xhr.responseText);
        renderSuggestions(suggestions);
      }
    };
    xhr.send(JSON.stringify({ query: query }));
  }

  // Render suggestions using Handlebars templates
  function renderSuggestions(suggestions) {
    const source = document.getElementById('suggestion-template').innerHTML;
    const template = Handlebars.compile(source);
    suggestionList.innerHTML = template({ suggestions: suggestions });
  }

  // Handle selection of a suggestion
  function handleSelection(event) {
    if (event.target.tagName === 'LI') {
      const selectedProduct = event.target.dataset;
      searchInput.value = `${selectedProduct.id} (${selectedProduct.upc})`;
      suggestionList.innerHTML = ''; // Clear suggestions after selection
    }
  }

  // Event listener for input field
  searchInput.addEventListener('input', function() {
    const query = this.value;
    if (query.length >= 3) { // Minimum length to trigger fetch
      fetchSuggestions(query);
    } else {
      suggestionList.innerHTML = ''; // Clear suggestions if input is too short
    }
  });

  // Event listener for suggestion list items
  suggestionList.addEventListener('click', handleSelection);
}
