function loadJobsFromDirectory(directory) {
    const fs = require('fs');
    const path = require('path');
    const coffeeRegister = require('coffee-script/register');

    // Register CoffeeScript compiler
    coffeeRegister();

    // Read directory and filter files with .js or .coffee extension
    fs.readdir(directory, (err, files) => {
        if (err) {
            console.error(`Error reading directory: ${err}`);
            return;
        }

        files.forEach(file => {
            if (path.extname(file) === '.js' || path.extname(file) === '.coffee') {
                const filePath = path.join(directory, file);
                require(filePath); // Dynamically load the file
            }
        });
    });
}
