const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

function createDebianPackage(packageName) {
    const packageDir = `/tmp/${packageName}`;
    const controlFileContent = `Package: ${packageName}\nVersion: 0.1\nArchitecture: all\nMaintainer: Your Name <your.email@example.com>\nDescription: A sample Debian package for ${packageName}.`;

    if (!fs.existsSync(packageDir)) {
        fs.mkdirSync(packageDir);
    }

    const controlFilePath = path.join(packageDir, 'control');
    fs.writeFileSync(controlFilePath, controlFileContent);

    exec(`dpkg-deb --build ${packageDir} /tmp/${packageName}.deb`, (err, stdout, stderr) => {
        if (err) {
            console.error(`Error creating Debian package: ${stderr}`);
            return;
        }
        console.log('Debian package created successfully.');
    });
}

function createRedHatPackage(packageName) {
    const specFilePath = `/tmp/${packageName}.spec`;
    const specFileContent = `%description\nA sample Red Hat package for ${packageName}.`;

    fs.writeFileSync(specFilePath, specFileContent);

    exec(`rpmbuild -bb ${specFilePath}`, (err, stdout, stderr) => {
        if (err) {
            console.error(`Error creating Red Hat package: ${stderr}`);
            return;
        }
        const rpmFilePath = `/tmp/${packageName}.rpm`;
        if (fs.existsSync(rpmFilePath)) {
            console.log('Red Hat package created successfully.');
        } else {
            console.error('Failed to create Red Hat package.');
        }
    });
}

function generatePackage() {
    const packageName = 'samplepackage';
    createDebianPackage(packageName);

    exec(`which rpmbuild`, (err, stdout, stderr) => {
        if (!err && stdout.trim()) {
            createRedHatPackage(packageName);
        } else {
            console.log('rpmbuild not found, skipping Red Hat package creation.');
        }
    });
}

generatePackage();
