function evaluateFunctions(functions) {
  const results = [];
  const memoizedResults = {};

  function memoizeResult(funcName, args, result) {
    memoizedResults[`${funcName}-${JSON.stringify(args)}`] = result;
  }

  for (const [funcName, funcArgs] of functions) {
