const headGeometry = new THREE.SphereGeometry(0.5, 32, 32);
const limbGeometry = new THREE.CylinderGeometry(0.1, 0.1, 1, 32);

// Create meshes
const bodyMesh = new THREE.Mesh(bodyGeometry, bodyMaterial);
const headMesh = new THREE.Mesh(headGeometry, headMaterial);
const limbMesh = new THREE.Mesh(limbGeometry, limbMaterial);

// Position the body mesh in the center of the scene
bodyMesh.position.y = -1;

// Position the head on top of the body
