let generateUniqueIdentifier = (key) => {
  const cache = new Map();
  let counter = 0;

  return () => {
    if (!cache.has(key)) {
      const randomPostfix = Math.random().toString(36).substr(2, 5);
      const uniqueId = `${key}${randomPostfix}`;
      cache.set(key, uniqueId);
      counter++;
      return uniqueId;
    } else {
