const Promise = require('bluebird');
const FileUploader = require('file-uploader-library');
const Logger = require('logger-library');

function uploadFile(url) {
    return new Promise((resolve, reject) => {
        try {
            const fileUploader = new FileUploader();
            fileUploader.upload(url).then((uploadedUrl) => {
                Logger.info(`File uploaded successfully: ${uploadedUrl}`);
                resolve(uploadedUrl);
            }).catch((error) => {
                Logger.error(`Failed to upload file: ${error}`);
                reject(error);
            });
        } catch (err) {
            Logger.error(`Error occurred while uploading file: ${err}`);
            reject(err);
        }
    });
}
