function parseCSSSelector(selector) {
    // Remove leading and trailing whitespace
    selector = selector.trim();

    // Regular expression to match combinators, simple selectors, and attribute tests
    const regex = /([\s>+~]+)?((?:[^\[\]\(\)\s>]|\([^)]*\)|\[[^]]*\])+)/g;
    let matches;
    const result = {
        combinators: [],
        simpleSelectors: [],
        attributeTests: []
    };

    while ((matches = regex.exec(selector)) !== null) {
        if (matches[1]) {
            result.combinators.push(matches[1]);
        }
        if (matches[2]) {
            const simpleSelector = matches[2];
            // Check for attribute tests within the simple selector
            const attrTestRegex = /\[[^]]*\]/;
            let attrMatch;
            while ((attrMatch = attrTestRegex.exec(simpleSelector)) !== null) {
                result.attributeTests.push(attrMatch[0]);
            }
            // Remove attribute tests from the simple selector
            const cleanedSimpleSelector = simpleSelector.replace(attrTestRegex, '');
            if (cleanedSimpleSelector.length > 0) {
                result.simpleSelectors.push(cleanedSimpleSelector);
            }
        }
    }

    return result;
}
