  // Function to display the list of worlds in a dropdown or list
  function displayWorlds(worldList) {
    const selectElement = document.createElement('select');
    worldList.forEach(world => {
      const optionElement = document.createElement('option');
      optionElement.value = world;
      optionElement.textContent = world;
      selectElement.appendChild(optionElement);
    });
    selectElement.addEventListener('change', function() {
      if (selectElement.value) {
        window.postMessage(`load_world:${selectElement.value}`, '*');
      }
    });
    document.body.appendChild(selectElement);
  }

  // Function to load the selected world
  function loadWorld(worldName) {
    window.postMessage(`load_world:${worldName}`, '*');
    // Additional logic to actually load the world can be added here
  }

  // Initial fetch of the world list from the server
  fetchWorldList();
}
