function jsonpRequest(url, method, payload, successCallback, failureCallback) {
  const callbackName = `jsonp_callback_${Date.now()}`;

  // Create a unique callback function in the window object
  window[callbackName] = (response) => {
    delete window[callbackName]; // Remove the callback function from the window object
    document.body.removeChild(script); // Remove the script element from the DOM

    if (typeof response === 'string') {
      try {
        const jsonResponse = JSON.parse(response);
        successCallback(jsonResponse);
      } catch (error) {
        failureCallback(`Error parsing JSON: ${error}`);
      }
    } else {
      failureCallback('No response data');
    }
  };

  // Create a script element and set its type to 'text/javascript'
  const script = document.createElement('script');
  script.type = 'text/javascript';

  // Set the src attribute of the script element to include the callback function name
  script.src = `${url}?callback=${callbackName}`;

  // Add the script element to the DOM
  document.body.appendChild(script);

  return { url, method, payload }; // Return the created XHR object (in this case, just an object with the parameters)
}
