function defineNativeShortcuts() {
  const nativeMethods = {};

  // Define shortcuts for native methods with the same name as lodash methods
  const lodashMethods = [
    'map', 'filter', 'reduce', 'forEach', 'find', 'some', 'every', 'concat', 'slice', 'includes'
  ];

  lodashMethods.forEach(method => {
    nativeMethods[method] = Array.prototype[method];
  });

  // Create a lookup table for built-in constructors by [[Class]]
  const constructorLookup = {};

  [
    'Boolean', 'Number', 'String', 'Array', 'Object', 'Function', 'Date', 'RegExp'
  ].forEach(constructorName => {
    constructorLookup[`[object ${constructorName}]`] = globalThis[constructorName];
  });

  return { nativeMethods, constructorLookup };
}
