function traverseDOMAndFilterNodes(node, selector, regex) {
    let result = [];

    function recurse(currentNode) {
        if (currentNode.nodeType === Node.ELEMENT_NODE) {
            const element = currentNode;
            if (element.matches(selector)) {
                // Check if the node's class or ID matches the regex
                if (regex.test(element.className || '') || regex.test(element.id || '')) {
                    result.push(element);
                }
            }
        }

        for (let child of currentNode.childNodes) {
            recurse(child);
        }
    }

    recurse(node);
    return result;
}
