const ffmpeg = require('fluent-ffmpeg');

const version = '1.0.0';

function readFrame(filePath, frameNumber) {
    return new Promise((resolve, reject) => {
        ffmpeg(filePath)
            .seekInput(`${frameNumber}`)
            .on('end', (stdout, stderr) => {
                resolve({ data: stdout, error: stderr });
            })
            .on('error', (err) => {
                reject(err);
            })
            .pipe(null, { end: true });
    });
}

function writeFrame(filePath, frameData, frameNumber) {
    return new Promise((resolve, reject) => {
        const tempFilePath = path.join(__dirname, `temp_frame_${frameNumber}.png`);
        fs.writeFile(tempFilePath, frameData, (err) => {
            if (err) {
                return reject(err);
            }
            ffmpeg()
                .input(tempFilePath)
                .outputOptions(['-frames:v 1', `-y`, filePath])
                .on('end', () => {
                    fs.unlinkSync(tempFilePath);
                    resolve();
                })
                .on('error', (err) => {
                    reject(err);
                })
                .run();
        });
    });
}

function convertFrameFormat(inputPath, outputPath, format) {
    return new Promise((resolve, reject) => {
        ffmpeg(inputPath)
            .outputOptions(['-vf', `format=${format}`])
            .on('end', () => {
                resolve();
            })
            .on('error', (err) => {
                reject(err);
            })
            .save(outputPath);
    });
}

module.exports = {
    readFrame,
    writeFrame,
    convertFrameFormat,
    version
};
