import React, { useState, useEffect } from 'react';
import axios from 'axios';

const VersionSelector = ({ repositoryUrl }) => {
  const [versions, setVersions] = useState([]);
  const [selectedVersion, setSelectedVersion] = useState(null);

  useEffect(() => {
    const fetchVersions = async () => {
      try {
        const response = await axios.get(`${repositoryUrl}/tags`);
        const tags = response.data;
        // Filter out stable versions, assuming a simple filter for 'stable' in the tag name
        const stableTags = tags.filter(tag => tag.name.includes('stable'));
        setVersions(stableTags);
        setSelectedVersion(stableTags[0]); // Set the first stable version as default
      } catch (error) {
        console.error("Error fetching versions:", error);
      }
    };

    fetchVersions();
  }, [repositoryUrl]);

  const handleSelectChange = (event) => {
    const selectedTagName = event.target.value;
    const selectedVersion = versions.find(version => version.name === selectedTagName);
    setSelectedVersion(selectedVersion);
  };

  return (
    <div>
      <h1>Select Version</h1>
      <select value={selectedVersion?.name || ''} onChange={handleSelectChange}>
        {versions.map((version) => (
          <option key={version.name} value={version.name}>
            {version.name}
          </option>
        ))}
      </select>
      {selectedVersion && <p>Selected Version: {selectedVersion.name}</p>}
    </div>
  );
};

export default VersionSelector;
