function processCompressedCode(base64String, callback) {
    // Decode base64 string to binary buffer
    const binaryBuffer = atob(base64String);

    // Decompress using zlib.inflate
    const inflater = new Zlib.Inflate();
    let decompressedData;
    try {
        decompressedData = inflater.decompress(binaryBuffer);
    } catch (e) {
        console.error("Decompression failed:", e);
        return;
    }

    // Convert ASCII hex codes to list of code fragments and time offsets
    const codeFragments = [];
    const timeOffsets = [];
    let i = 0;
    while (i < decompressedData.length) {
        const codeFragment = decompressedData.slice(i, i + 4).toString('hex');
        const timeOffset = parseInt(decompressedData.slice(i + 4, i + 8).toString('hex'), 16);
        codeFragments.push(codeFragment);
        timeOffsets.push(timeOffset);
        i += 8;
    }

    // Call the callback function with the fingerprint object
    const fingerprint = {
        codeFragments: codeFragments,
        timeOffsets: timeOffsets
    };
    callback(fingerprint);
}
