function evaluateExpression(expression, environment) {
    const SAFE_NODES = new Set([
        'Expression', 'Compare', 'Str', 'List', 'Tuple', 'Dict', 'Call', 'Load', 
        'BinOp', 'UnaryOp', 'Num', 'Name', 'Add', 'Sub', 'Mult', 'Div'
    ]);

    class ErrorWithIndex extends Error {
        constructor(message, index) {
            super(message);
            this.index = index;
        }
    }

    function isSafeNode(node) {
        return SAFE_NODES.has(node.type);
    }

    const CALL_WHITELIST = [
        'abs', 'all', 'any', 'basestring', 'bin', 'bool', 'buffer', 'bytearray',
        'bytes', 'callable', 'chr', 'cmp', 'coerce', 'complex', 'copyright', 'credits',
        'dict', 'dir', 'divmod', 'enumerate', 'exit', 'float', 'format', 'frozenset',
        'getattr', 'globals', 'hasattr', 'hash', 'hex', 'id', 'int', 'intern',
        'isinstance', 'issubclass', 'iter', 'len', 'license', 'list', 'locals', 'long',
        'map', 'max', 'memoryview', 'min', 'next', 'oct', 'ord', 'pow', 'print',
        'property', 'quit', 'range', 'reversed', 'round', 'set', 'slice', 'sorted',
        'str', 'sum', 'tuple', 'unichr', 'unicode', 'vars', 'xrange', 'zip'
    ];

    function isSafeCall(node) {
        return CALL_WHITELIST.includes(node.id);
    }

    class CleansingNodeVisitor extends ast.NodeVisitor {
        visit(tree) {
            for node in tree.body:
                this._visitNode(node);
        }

        _visitNode(node) {
            if (!isSafeNode(node)) {
                throw new Error(`invalid expression (${expression})`);
            }
            for child in ast.iter_child_nodes(node):
                this._visitNode(child);
        }

        visit_Call(call) {
            if (!isSafeCall(call.func)) {
                throw new Error(`invalid function: ${call.func.id}`);
            }
            for arg in call.args:
                this._visitNode(arg);
        }
    }

    try {
        parsed_tree = ast.parse(expression, mode='eval');
        cnv = new CleansingNodeVisitor();
        cnv.visit(parsed_tree);
        compiled = compile(parsed_tree, expression, 'eval');
        result = eval(compiled, environment);
        return result;
    } catch (e) {
        if (e instanceof SyntaxError || e instanceof Exception) {
            throw new Error(`invalid expression (${expression})`);
        }
    }
}
