def hash_value(item):
    import hashlib
    import json

    # Counter for new objects encountered
    object_counter = {}

    def get_hash(obj):
        if obj is None or isinstance(obj, (int, float, str, list, tuple, set, dict)):
            return hashlib.sha256(json.dumps(obj, sort_keys=True).encode()).hexdigest()
        elif isinstance(obj, object):
            obj_id = id(obj)
            if obj_id in object_counter:
                return str(object_counter[obj_id])
            else:
                hash_value = get_hash({k: v for k, v in obj.__dict__.items()})
                object_counter[obj_id] = hash_value
                return hash_value
        else:
            raise TypeError("Unsupported type")

    return get_hash(item)
