    // Set initial style properties if not already set
    if (objectToDrag.style.left === undefined) {
        objectToDrag.style.left = "0px";
    }
    if (objectToDrag.style.right === undefined) {
        objectToDrag.style.right = "0px";
    }

    let offsetX, offsetY;

    function onDragStart(event) {
        // Handle the start of dragging
        event.preventDefault();
        offsetX = event.clientX - parseInt(objectToDrag.style.left);
        offsetY = event.clientY - parseInt(objectToDrag.style.top);
    }

    function onDrag(event) {
        // Handle the dragging process
        let x = event.clientX - offsetX;
        if (x < minX) x = minX;
        if (x > maxX) x = maxX;
        objectToDrag.style.left = `${x}px`;
    }

    function onDragEnd(event) {
        // Handle the end of dragging
        event.preventDefault();
    }

    // Add event listeners for drag operations
    leftButton.addEventListener("mousedown", onDragStart);
    rightButton.addEventListener("mousedown", onDragStart);
    objectToDrag.addEventListener("mousemove", onDrag);
