function stopEmbeddedContent() {
  // Get all slides in the presentation
  const slides = document.querySelectorAll('.slide');

  slides.forEach(slide => {
    // Check for embedded content inside each slide
    const iframe = slide.querySelector('iframe');
    if (iframe) {
      const src = iframe.src;
      if (src.includes('youtube.com') || src.includes('youtu.be')) {
        // For YouTube videos, send a postMessage command to pause the video
        iframe.contentWindow.postMessage('{"event":"command","func":"' + 'pauseVideo' + '"}', '*');
      } else if (src.includes('vimeo.com')) {
        // For Vimeo videos, send a postMessage command to pause the video
        iframe.contentWindow.postMessage('{"method":"pause"}', '*');
      } else {
        // For generic iframes, you can add more handling here as needed
        iframe.contentWindow.postMessage('{ "command": "stop" }', '*');
      }
    }
  });
}
