function createMessageHandler(id, callback) {
  // Check for MessageChannel support
  if (typeof MessageChannel !== 'undefined') {
    const channel = new MessageChannel();
    channel.port1.onmessage = function(event) {
      if (event.data.id === id) {
        callback(event.data.id);
      }
    };
    return channel.port2;
  } else {
    // Fallback to polling mechanism for older browsers
    let lastMessageId = null;
    setInterval(() => {
      if (lastMessageId !== id) {
        lastMessageId = id;
        callback(id);
      }
    }, 100); // Polling interval in milliseconds
    return { postMessage: () => {} }; // Return an object with postMessage method for compatibility
  }
}
