function parseBuffer(buffer, offset) {
    // Check if offset is within valid range
    if (offset < 0 || offset >= buffer.length) {
        return { error: 'Invalid offset', code: -1 };
    }

    // Read the length field from the buffer at the given offset
    let lengthBytes = buffer.slice(offset, offset + 2);
    if (lengthBytes.length < 2) {
        return { error: 'Incomplete length field', code: -1 };
    }

    // Convert the length bytes to a 2-byte integer in big-endian format
    let length = (lengthBytes[0] << 8) | lengthBytes[1];

    // Check if the length is valid
    if (length > buffer.length - offset || length <= 0) {
        return { error: 'Invalid length field', code: -1 };
    }

    // Return the extracted action and its length
    return { actionLength: length, action: buffer.slice(offset + 2, offset + 2 + length) };
}
