function scrollToElement() {
    // Get the hash from the URL
    const hash = window.location.hash;

    // Scroll to the top of the page if the hash is 'top'
    if (hash === '#top') {
        window.scrollTo({ top: 0, behavior: 'smooth' });
        return;
    }

    // Get the element by ID if the hash matches an element's ID
    const element = document.getElementById(hash.substring(1));
    if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
        return;
    }

    // Scroll to the top of the page if the hash matches an anchor's name
    if (hash.startsWith('#')) {
        window.location.href = '#top';
        setTimeout(() => {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }, 10);
    }
}

// Set up a watcher to call the function when the URL hash changes
window.addEventListener('hashchange', scrollToElement);

