const { exec } = require('child_process');
const fs = require('fs');

function executeCommand(command, options) {
  return new Promise((resolve, reject) => {
    const childProcess = exec(command);

    childProcess.on('error', (err) => {
      reject(`Error executing command: ${err}`);
    });

    childProcess.on('close', (code) => {
      resolve(code);
    });
  });
}

function watchForFiles(options, callback) {
  if (!options || !options.watch) {
    return;
  }

  const inputFiles = options.inputFiles || [];

  for (const file of inputFiles) {
    fs.watch(file, (eventType, filename) => {
      if (filename && eventType === 'change') {
        callback();
      }
    });
  }
}

async function runCommandWithWatch(command, options) {
  watchForFiles(options, () => {
    console.log('Input files have changed. Re-executing command...');
    executeCommand(command, options);
  });

  try {
    await executeCommand(command, options);
  } catch (error) {
    console.error(`Error: ${error}`);
  }
}

// Example usage:
const command = 'your_command_here';
const options = { watch: true, inputFiles: ['file1.txt', 'file2.txt'] };
runCommandWithWatch(command, options);
