function normalizeUrl(url) {
  // Split the URL into parts
  let parts = url.split('/');

  // Initialize an array to hold the normalized parts
  let normalizedParts = [];

  for (let part of parts) {
    if (part === '..') {
      // Remove the last added part if it's not root
      if (normalizedParts.length > 0 && normalizedParts[normalizedParts.length - 1] !== '.') {
        normalizedParts.pop();
      } else {
        // If we are at root level, just add '..' to indicate going up a directory
        normalizedParts.push(part);
      }
    } else if (part !== '.' && part !== '') {
      // Add the part unless it's a current directory reference or empty
      normalizedParts.push(part);
    }
  }

  // Join the parts back into a URL string
  let normalizedUrl = normalizedParts.join('/');

  // Handle the case where the URL is just root
  if (normalizedUrl === '') {
    normalizedUrl = '/';
  }

  return normalizedUrl;
}
