function splitString(input, delimiter) {
  const regex = new RegExp(`(${delimiter})`);
  let match;
  const result = [];
  let lastIndex = 0;

  while ((match = regex.exec(input)) !== null) {
    result.push(input.substring(lastIndex, match.index));
    lastIndex = regex.lastIndex;
  }

  // Push the final substring if there's any remaining text after the last delimiter
  if (lastIndex < input.length) {
    result.push(input.substring(lastIndex));
  }

  return result;
}
