function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
    // Connect to the database
    $conn = new mysqli("localhost", "username", "password", "database_name");

    // Check connection
    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Prepare the SQL statement
    $sql = "UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=? WHERE id=?";
    $stmt = $conn->prepare($sql);

    if ($stmt === false) {
        die("Error preparing statement: " . $conn->error);
    }

    // Bind parameters and execute the statement
    $lastModifiedDate = date('Y-m-d H:i:s');
    $stmt->bind_param("sssi", $newStatus, $ipAddress, $lastModifiedDate, $clinicId);

    if ($stmt->execute()) {
        // Return success message
        return "Clinic status updated successfully.";
    } else {
        // Return error message
        return "Error updating clinic status: " . $stmt->error;
    }

    // Close the statement and connection
    $stmt->close();
    $conn->close();
}
