<?php
function detect_mime_type($file_path) {
    // Check if the file() command is available
    if (!function_exists('exec')) {
        return null;
    }

    // Use the file() command to determine the MIME type
    $log = [];
    exec("file --mime-type " . escapeshellarg($file_path), $output, $return_var);

    if ($return_var !== 0) {
        $log[] = "Failed to detect MIME type for file: " . $file_path;
        return null;
    }

    // Parse the output of the file command
    preg_match('/^.*:\s*([a-zA-Z]+\/[a-zA-Z0-9+-]+)/', $output[0], $matches);
    if (!isset($matches[1])) {
        $log[] = "Failed to parse MIME type from output: " . implode(' ', $output);
        return null;
    }

    $mime_type = $matches[1];
    $log[] = "Detected MIME type for file: " . $file_path . " is " . $mime_type;

    // Log the messages and return the detected MIME type
    foreach ($log as $message) {
        error_log($message);
    }

    return $mime_type;
}
?>
