<?php
function aes256CtrEncrypt($key, $data) {
    // Check if Mcrypt extension is available
    if (!extension_loaded('mcrypt')) {
        throw new Exception("Mcrypt extension is not loaded.");
    }

    // Generate a random IV (Initialization Vector)
    $iv = mcrypt_create_iv(mcrypt_get_block_size(MCRYPT_RIJNDAEL_256, MCRYPT_MODE_CTR), MCRYPT_RAND);

    // Open the cipher
    $td = mcrypt_module_open(MCRYPT_RIJNDAEL_256, '', MCRYPT_MODE_CTR, '');

    // Initialize encryption handle
    mcrypt_generic_init($td, $key, $iv);

    // Encrypt the data
    $encrypted = mcrypt_generic($td, $data);

    // Finalize encryption and close the cipher handle
    mcrypt_generic_deinit($td);
    mcrypt_module_close($td);

    // Return the encrypted data in base64 format
    return base64_encode($encrypted);
}
