<?php

function generateRequestSignature($request) {
    // Check if user is authenticated
    $user = $request->getUser();
    if ($user && isset($user['auth_identifier'])) {
        $authIdentifier = $user['auth_identifier'];
        $stringToSign = $authIdentifier . "\n" . time();
    } else {
        // Check if route is available
        $route = $request->getRoute();
        if ($route) {
            $domain = $request->getDomain();
            $ipAddress = $request->getIpAddress();
            $stringToSign = $domain . "\n" . $ipAddress . "\n" . time();
        } else {
            throw new RuntimeException("Request signature cannot be generated.");
        }
    }

    // Generate the SHA-1 hash of the string to sign
    $signature = sha1($stringToSign);
    return $signature;
}
