class ConversationLoader {
    private $dataDir;
    private $memoryFile;

    public function __construct($dataDir, $memoryFile) {
        $this->dataDir = $dataDir;
        $this->memoryFile = $memoryFile;
    }

    public function loadConversation($entity) {
        // Check if the memory file exists and load it into the conversation if it does.
        if (file_exists($this->memoryFile)) {
            $conversation = json_decode(file_get_contents($this->memoryFile), true);
        } else {
            $conversation = [];
        }

        // Load the conversation from a file in the bot's data directory.
        $filePath = $this->dataDir . '/' . $entity . '.json';
        if (file_exists($filePath)) {
            $fileContent = json_decode(file_get_contents($filePath), true);
            $conversation = array_merge($conversation, $fileContent);
        }

        // Save the updated conversation back to the memory file.
        file_put_contents($this->memoryFile, json_encode($conversation));

        return $this;
    }
}
