CREATE OR REPLACE FUNCTION modify_query_with_limit_and_offset (
    query VARCHAR2, 
    limit_rows NUMBER, 
    offset_rows NUMBER DEFAULT 0, 
    date_format VARCHAR2 DEFAULT 'YYYY-MM-DD'
) RETURN VARCHAR2 IS
BEGIN
    -- Set the date format using ALTER SESSION SET NLS_DATE_FORMAT command
    EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_DATE_FORMAT = ''' || date_format || '''';

    -- Modify the query to include LIMIT and OFFSET clauses
    IF offset_rows > 0 THEN
        RETURN 'SELECT * FROM (SELECT query.*, ROWNUM rnum FROM (' || query || ') query) WHERE rnum BETWEEN ' || (offset_rows + 1) || ' AND ' || (offset_rows + limit_rows);
