    // Check if 'df' command is installed and available in the system's PATH
    $command = 'which df';
    exec($command, $output, $return_var);

    if ($return_var != 0) {
        throw new Exception("The 'df' command is not installed or not available in the system's PATH.");
    }
}

function getDiskUsage() {
    // Use the 'df' command to get the disk usage information
    $command = 'df -h';
    exec($command, $output);

    // Store the output in a variable
    $disk_usage_info = implode("\n", $output);

    return $disk_usage_info;
}

