        $checkStmt->bindParam(':urlHash', $urlHash, PDO::PARAM_STR);
        $checkStmt->execute();

        if ($checkStmt->rowCount() > 0) {
            // Update the existing record instead of creating a new one.
            $updateStmt = $db->prepare("UPDATE your_table SET views = views + 1 WHERE url_hash = :urlHash");
            $updateStmt->bindParam(':urlHash', $urlHash, PDO::PARAM_STR);
            $updateStmt->execute();
