<?php
function createAndQueryTable($table_name, $columns, $primary_key) {
    // Connect to the database
    $conn = new PDO("mysql:host=localhost;dbname=mydatabase", "username", "password");
    $conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // Create table with specified columns and primary key
    $columns_sql = implode(", ", $columns);
    $primary_key_sql = "PRIMARY KEY ($primary_key)";
    $query = "CREATE TABLE IF NOT EXISTS $table_name ($columns_sql, $primary_key_sql)";
    $conn->exec($query);

    // Function to insert data into the table
    function insertData($conn, $table_name, $data) {
        $columns = implode(", ", array_keys($data));
        $values = ":" . implode(", :", array_keys($data));
        $query = "INSERT INTO $table_name ($columns) VALUES ($values)";
        $stmt = $conn->prepare($query);
        foreach ($data as $key => $value) {
            $stmt->bindValue(":$key", $value);
        }
        $stmt->execute();
    }

    // Example data to insert
    $data = [
        'id' => 1,
        'name' => 'John Doe',
        'email' => 'john@example.com'
    ];
    insertData($conn, $table_name, $data);

    // Query the database to retrieve data based on specific conditions
    function queryTable($conn, $table_name, $conditions) {
        $where = "";
        if (!empty($conditions)) {
            $where = " WHERE " . implode(" AND ", array_map(function($key) {
                return "$key = :$key";
            }, array_keys($conditions)));
        }
        $query = "SELECT * FROM $table_name" . $where;
        $stmt = $conn->prepare($query);
        foreach ($conditions as $key => $value) {
            $stmt->bindValue(":$key", $value);
        }
        $stmt->execute();
        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }

    // Example conditions to query with
    $conditions = [
        'name' => 'John Doe',
        'email' => 'john@example.com'
    ];
    $results = queryTable($conn, $table_name, $conditions);

    // Output the results
    print_r($results);

    // Close the database connection
    $conn = null;
}

