function check_security_attack($username, $max_attempts = 10, $time_window = 3600) {
    // Initialize or retrieve user's login attempts from session or database
    $user_attempts = $_SESSION['login_attempts'][$username] ?? [];

    // Get the current timestamp
    $current_time = time();

    // Filter out old attempts that are outside the time window
    $user_attempts = array_filter($user_attempts, function($timestamp) use ($current_time, $time_window) {
        return $current_time - $timestamp <= $time_window;
    });

    // Count the number of failed login attempts within the time window
    $failed_attempts = count($user_attempts);

    // Check if the number of failed attempts exceeds the maximum allowed
    if ($failed_attempts >= $max_attempts) {
        // Set a flag in the user's session to indicate a security attack was detected
        $_SESSION['security_attack'][$username] = true;
        return true;
    } else {
        // Update the user's login attempts with the current timestamp
        $user_attempts[] = $current_time;
        $_SESSION['login_attempts'][$username] = $user_attempts;
        return false;
    }
