function createGoogleMapsAutocomplete(inputFieldId) {
  // Initialize Google Maps JavaScript API and jQuery library
  function initMap() {
    const input = document.getElementById(inputFieldId);
    if (!input) {
      console.error(`Input field with id ${inputFieldId} not found.`);
      return;
    }

    const autocomplete = new google.maps.places.Autocomplete(input);

    // Trigger the function when the input changes
    google.maps.event.addListener(autocomplete, 'place_changed', function() {
      handlePlaceChange();
    });
  }

  function handlePlaceChange() {
    const place = this.getPlace();
    console.log('Place selected:', place);
    // Add any additional logic here to handle the selected place
  }

  // Load the Google Maps JavaScript API and initialize the map
  window.initMap = initMap;
  (function() {
    const script = document.createElement('script');
    script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&libraries=places`;
    script.onload = function() {
      if (typeof initMap === 'function') {
        initMap();
      }
    };
    document.head.appendChild(script);
  })();
}
