function check_session() {
    // Start or resume the session
    session_start();

    // Check if user agent and IP address are stored in the session
    if (isset($_SESSION['user_agent']) && isset($_SESSION['ip_address'])) {
        $stored_user_agent = $_SESSION['user_agent'];
        $stored_ip_address = $_SESSION['ip_address'];

        // Get current user agent and IP address
        $current_user_agent = $_SERVER['HTTP_USER_AGENT'];
        $current_ip_address = $_SERVER['REMOTE_ADDR'];

        // Compare the stored values with the current ones
        if ($stored_user_agent !== $current_user_agent || $stored_ip_address !== $current_ip_address) {
            // Destroy the session if they don't match
            session_destroy();
            return false;
        }
    } else {
        // Store user agent and IP address in the session if not already set
        $_SESSION['user_agent'] = $current_user_agent;
        $_SESSION['ip_address'] = $current_ip_address;
    }

