function logExecutionTimeAndMemory() {
    $logFile = 'execution_log.txt';

    // Get start time and memory usage
    $startTime = microtime(true);
    $startMemory = memory_get_usage();

    // Log environment variables
    $envVariables = [
        'SCRIPT_NAME' => $_SERVER['SCRIPT_NAME'],
        'REQUEST_METHOD' => $_SERVER['REQUEST_METHOD'],
        'HTTP_HOST' => $_SERVER['HTTP_HOST'],
        'REMOTE_ADDR' => $_SERVER['REMOTE_ADDR'],
    ];

    // Log the information
    $logMessage = "Execution started at: " . date('Y-m-d H:i:s') . "\n";
    foreach ($envVariables as $key => $value) {
        $logMessage .= "$key: $value\n";
    }

    // Get end time and memory usage
    $endTime = microtime(true);
    $endMemory = memory_get_usage();

    // Calculate execution time and memory usage
    $executionTime = ($endTime - $startTime) * 1000; // in milliseconds
    $memoryUsage = ($endMemory - $startMemory) / 1024; // in kilobytes

    $logMessage .= "Execution time: " . number_format($executionTime, 2) . " ms\n";
    $logMessage .= "Memory usage: " . number_format($memoryUsage, 2) . " KB\n";

    // Write to log file or console
    error_log($logMessage, 3, $logFile);
}
