function sortLeaseRecords($leaseRecords, $sortField) {
    // Define a custom comparison function to use with usort
    function compare($a, $b) {
        global $sortField;
        if ($a[$sortField] == $b[$sortField]) return 0;
        return ($a[$sortField] < $b[$sortField]) ? -1 : 1;
    }

    // Sort the lease records using the custom comparison function
    usort($leaseRecords, 'compare');

    // Write the sorted list to a file
    $file = fopen('sorted_lease_records.txt', 'w');
    foreach ($leaseRecords as $record) {
        fwrite($file, implode(',', $record) . "\n");
    }
    fclose($file);

    // Restart the service (example: assuming a restart command for Linux)
    exec('sudo systemctl restart myservice');
