    if (strlen($newPassword) < 8 || !preg_match('/[A-Z]/', $newPassword) || !preg_match('/\d/', $newPassword)) {
        throw new Exception("Password must be at least 8 characters long and contain at least one uppercase letter and one digit.");
    }

    // Connect to the database (example connection parameters)
    $conn = new mysqli("localhost", "username", "password", "database_name");

    // Check connection
    if ($conn->connect_error) {
        throw new Exception("Connection failed: " . $conn->connect_error);
    }

    try {
        // Prepare and execute the query to get the user ID based on the provided ID
        $stmt = $conn->prepare("SELECT id_uzytkownika FROM uzytkownicy uz JOIN nauczyciele ON id_uzytkownika=uz.login WHERE id=?");
        $stmt->bind_param("i", $userId);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($result->num_rows === 0) {
            throw new Exception("User not found.");
        }

        $row = $result->fetch_assoc();
        $userID = $row['id_uzytkownika'];

        // Prepare and execute the query to update the password
        $stmt = $conn->prepare("UPDATE uzytkownicy SET haslo=? WHERE login=?");
        $stmt->bind_param("ss", $newPassword, $userID);
        $stmt->execute();

        if ($stmt->affected_rows === 0) {
