function countdown() {
    // Set the target date and time (replace with your desired date and time)
    const targetDate = moment('2023-12-31T23:59:59');

    // Update the countdown every second
    setInterval(() => {
        // Get the current date and time
        const now = moment();

        // Calculate the difference in seconds between the target date and now
        const diffInSeconds = targetDate.diff(now, 'seconds');

        // If the countdown is over, display "Countdown finished!"
        if (diffInSeconds < 0) {
            document.getElementById('getting-started').innerText = 'Countdown finished!';
        } else {
            // Calculate days, hours, minutes, and seconds
            const days = Math.floor(diffInSeconds / (3600 * 24));
            const hours = Math.floor((diffInSeconds % (3600 * 24)) / 3600);
            const minutes = Math.floor((diffInSeconds % 3600) / 60);
            const seconds = diffInSeconds % 60;

            // Display the countdown in the HTML element with ID 'getting-started'
            document.getElementById('getting-started').innerText = `${days}d ${hours}h ${minutes}m ${seconds}s`;
        }
    }, 1000);
}

// Call the function to start the countdown
countdown();
