function processFormSubmission($formData, $apiUrl) {
    // Initialize session variables to store result and error message
    $_SESSION['result'] = null;
    $_SESSION['error_message'] = null;

    // Prepare data for API request
    $data = array(
        'comment' => $formData['comment'],
        'user_id' => $formData['user_id'],
        // Add other necessary fields as needed
    );

    // Initialize cURL session
    $ch = curl_init($apiUrl);

    // Set cURL options
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));

    // Execute the request and capture the response
    $response = curl_exec($ch);

    // Check for cURL errors
    if (curl_errno($ch)) {
        $_SESSION['error_message'] = "API request failed: " . curl_error($ch);
    } else {
        // Parse the API response
        $responseData = json_decode($response, true);

        if ($responseData && isset($responseData['status']) && $responseData['status'] == 'success') {
            $_SESSION['result'] = "Comment created successfully";
        } else {
            $_SESSION['error_message'] = "Failed to create comment: " . ($responseData['message'] ?? 'Unknown error');
        }
    }

    // Close cURL session
    curl_close($ch);

    // Redirect to the specified URL
    header("Location: " . $formData['returnUrl']);
    exit();
}
