function getYouTubePlaylistVideos($playlistId, $apiKey) {
    $client = new Google_Client();
    $client->setDeveloperKey($apiKey);

    // Define service
    $youtube = new Google_Service_YouTube($client);

    try {
        // Retrieve the playlist items
        $playlistItemsResponse = $youtube->playlistItems->listPlaylistItems('snippet', array(
            'playlistId' => $playlistId,
            'maxResults' => 50
        ));

        $videos = [];

        foreach ($playlistItemsResponse['items'] as $item) {
            $videoSnippet = $item['snippet'];
            $video = [
                'id' => $videoSnippet['resourceId']['videoId'],
                'title' => $videoSnippet['title'],
                'description' => $videoSnippet['description'],
                'thumbnail' => $videoSnippet['thumbnails']['default']['url']
            ];
            $videos[] = $video;
        }

        return json_encode($videos, JSON_PRETTY_PRINT);
    } catch (Google_Service_Exception $e) {
        echo "A service error occurred: ",  $e->getMessage(), "\n";
    } catch (Google_Exception $e) {
        echo "An client error occurred: ",  $e->getMessage(), "\n";
    }
}
