function handle_remote_connection($host, $uri, $method, $body = '', $headers = []) {
    try {
        // Set up the connection
        $conn = new http\Client();
        $request = $conn->newRequest($method, $uri);

        // Add headers
        foreach ($headers as $name => $value) {
            $request->setHeader($name, $value);
        }

        // Set body if method is not HEAD
        if ($method != 'HEAD' && !empty($body)) {
            $request->setBody($body);
        }

        // Send the request
        $conn->send($request);

        // Get the response
        $response = $conn->getResponse();

        // Include a file if needed (example: logging)
        include 'log_response.php';

        return $response;
    } catch (Exception $e) {
        error_log("Connection error: " . $e->getMessage());
        throw $e;
    } finally {
        // Close the connection
        if ($conn) {
            $conn->disconnect();
        }
    }
}
