def generate_candidates(generator, max_size, variable_size=None):
    candidates = set()

    while len(candidates) < max_size:
        candidate = next(generator)
        if variable_size is None or (variable_size is not None and len(candidate) == variable_size):
            candidates.add(candidate)

    assert all(len(cand) == max_size for cand in candidates), "All candidates must be of the specified maximum size"

    with open('candidates.txt', 'w') as file:
        for candidate in candidates:
            file.write(str(candidate) + '\n')

    return candidates
