import hashlib
import json
import os
from typing import Any, Dict, Optional

class CachedResponseHandler:
    def __init__(self, cache_file: str = 'cache.json'):
        self.cache_file = cache_file

    def _hash_request(self, request: Dict[str, Any]) -> str:
        headers = request['headers']
        path = request['path']
        combined = ','.join([f"{k}:{v}" for k, v in sorted(headers.items())] + [path])
        return hashlib.md5(combined.encode()).hexdigest()

    def _load_cache(self) -> Dict[str, Any]:
        if os.path.exists(self.cache_file):
            with open(self.cache_file, 'r') as f:
                return json.load(f)
        return {}

    def _save_cache(self, cache: Dict[str, Any]):
        with open(self.cache_file, 'w') as f:
            json.dump(cache, f)

    def __call__(self, request: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        hash_key = self._hash_request(request)
        cache = self._load_cache()

        if 'GET' in request['method'] and hash_key in cache:
