    def create_subset_array(original_array, intervals):
        result = []
        for interval in intervals:
            begin, end = interval
            if isinstance(original_array[0], list):
                subarray = [row[begin:end] for row in original_array]
            else:
                subarray = original_array[begin:end]
            result.append(subarray)
        return result

    # Generate random intervals if not provided
    if intervals is None:
        intervals = generate_random_intervals(dimensions, intervals)

    # Create the subset array based on the generated intervals
