import json
from typing import Callable, Dict, Type

class JSONFactoryRegistry:
    _registry: Dict[str, Callable[[], 'JSONBase']] = {}

    @classmethod
    def register(cls, id: str, factory_func: Callable[[], 'JSONBase']) -> None:
        cls._registry[id] = factory_func

    @classmethod
    def create_from_id(cls, id: str) -> 'JSONBase':
        if id in cls._registry:
            return cls._registry[id]()
        raise ValueError(f"No factory registered for ID: {id}")

class JSONBase:
    def to_json_string(self) -> str:
        return json.dumps(self.__dict__)

    @classmethod
    def from_json_string(cls, json_str: str):
        instance = cls()
        instance.__dict__.update(json.loads(json_str))
        return instance

# Example subclass
