def generate_random_string(prefix='', maxlen=10, domen=''):
    characters = ''

    if 'lower' in locals():
        characters += string.ascii_lowercase
    if 'upper' in locals():
        characters += string.ascii_uppercase
    if 'digit' in locals():
        characters += string.digits
    if 'special_char' in locals():
        characters += string.punctuation

    length = random.randint(1, maxlen)
    result = prefix + ''.join(random.choice(characters) for _ in range(length))

    if domen:
        result += '@' + domen

