import subprocess
import re
from collections import Counter
import os

def extract_text_from_pdf(pdf_path):
    try:
        result = subprocess.run(['pdftotext', pdf_path, '-'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode != 0:
            raise Exception(f"Error extracting text from PDF: {result.stderr.decode('utf-8')}")
        return result.stdout.decode('utf-8')
    except Exception as e:
        print(e)
        return None

def tokenize_text(text):
    tokens = re.findall(r'\b\w+\b', text)
    return tokens

def create_bag_of_words(tokens):
    bag_of_words = Counter(tokens)
    return bag_of_words

def write_bag_of_words_to_file(bag_of_words, output_path):
    with open(output_path, 'w') as f:
        for word, count in bag_of_words.items():
            f.write(f"{word} {count}\n")

def main(pdf_path, output_path):
    text = extract_text_from_pdf(pdf_path)
    if text is None:
        return

    tokens = tokenize_text(text)
    bag_of_words = create_bag_of_words(tokens)
    write_bag_of_words_to_file(bag_of_words, output_path)

