def deprecate_attribute(new_name):
    def decorator(cls):
        old_name = f"__{getattr(cls, '__deprecated_attr__', None)}"

        @property
        def getter(self):
            warnings.warn(f"Attribute '{old_name}' is deprecated. Use '{new_name}' instead.", DeprecationWarning, stacklevel=2)
            return getattr(self, old_name)

        @getter.setter
        def setter(self, value):
            setattr(self, old_name, value)

        if hasattr(cls, new_name):
            raise AttributeError(f"Attribute '{new_name}' already exists in class {cls.__name__}")

        setattr(cls, '__deprecated_attr__', new_name)
        setattr(cls, old_name, property(getter))
        setattr(cls, new_name, property(getter, setter))

        return cls
    return decorator
