    def parse_template(tokens):
        while tokens:
            token = tokens.pop(0)
            if token == '{':
                expression = ''
                depth = 1
                while depth > 0:
                    next_token = tokens.pop(0)
                    expression += next_token
                    if next_token == '{':
                        depth += 1
                    elif next_token == '}':
                        depth -= 1
                yield expression
            else:
                yield token

    def compile_expression(expression):
        # Define simple syntax rules for conversion to Python code
        syntax_rules = {
            '{{': '{{',
            '}}': '}}',
            '{%': '{%',
            '%}': '%}',
            '{#': '{#',
            '#}': '#}',
        }
        
        # Replace syntax rules with Python code equivalents
        for key, value in syntax_rules.items():
            expression = expression.replace(key, f'{value}')
        
        # Evaluate the compiled expression using eval()
        return compile(expression, '<string>', 'eval')

    tokens = re.findall(r'\{\{|\}\}|\{[^}]*\}|[^{]+', template)
    parsed_tokens = list(parse_template(tokens))
    compiled_lambda = compile_expression(''.join(parsed_tokens))
    
