import sqlite3
from typing import List

def get_row_counts(table_names: List[str], db_path: str) -> dict:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    row_counts = {}
    for table_name in table_names:
        try:
            cursor.execute("SELECT COUNT(*) FROM " + table_name)
            count = cursor.fetchone()[0]
            if count == 0:
                raise ValueError(f"Table {table_name} has zero rows.")
            row_counts[table_name] = count
        except sqlite3.Error as e:
            raise sqlite3.Error(f"Error querying table {table_name}: {e}")

    # Check for different schemas
    if len(set(row_counts.values())) != 1:
        raise ValueError("Tables have different row counts or schemas.")

    conn.close()
    return row_counts
