def adjust_volume(volume_change):
    import os

    # Get current volume level
    current_volume = os.popen("amixer sget Master").read()
    lines = current_volume.split('\n')
    for line in lines:
        if 'Front Left:' in line:
            start = line.find('[') + 1
            end = line.find(']')
            current_volume_level = int(line[start:end])
            break

    # Adjust volume based on the input
    if volume_change == 'up':
        new_volume_level = min(current_volume_level + 5, 100)
    elif volume_change == 'down':
        new_volume_level = max(current_volume_level - 5, 0)
    else:
        return "Invalid input"

    # Set the new volume level
    os.system("amixer sset Master {}%".format(new_volume_level))

    return str(new_volume_level)
