import subprocess

def checkout_package(repository_url):
    """Check out a package from a Subversion repository and return the revision number."""
    try:
        result = subprocess.run(['svn', 'checkout', repository_url], capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Failed to checkout package: {result.stderr}")

