import subprocess

def get_commit_history(repo_path):
    # Run the 'hg log' command to retrieve commit history
    result = subprocess.run(['hg', '--repository', repo_path, 'log', '-r', '.'], capture_output=True, text=True)

    if result.returncode != 0:
        print(f"Error running hg log: {result.stderr}")
        return []

    # Parse the commit history
    commits = []
    current_commit = {}
    for line in result.stdout.splitlines():
        if line.startswith('commit '):
            if current_commit:
                commits.append(current_commit)
            current_commit = {'commit': line[7:], 'parents': [], 'branches': set()}
        elif line.startswith('parent '):
            current_commit['parents'].append(line[7:])

    if current_commit:
        commits.append(current_commit)

    return commits

def calculate_branch_counts(commits):
    branch_counts = {}
    for commit in commits:
        commit_hash = commit['commit']
        parent_hashes = commit['parents']

        # Count the number of branches at this commit
        if commit_hash not in branch_counts:
            branch_counts[commit_hash] = 0

        for parent_hash in parent_hashes:
            if parent_hash not in branch_counts:
                branch_counts[parent_hash] = 0
            branch_counts[parent_hash] += 1

    return branch_counts

# Example usage
repo_path = '/path/to/your/hg/repository'
commit_history = get_commit_history(repo_path)
branch_counts = calculate_branch_counts(commit_history)
print(branch_counts)
