import os
import shutil
import logging

def copy_directory(source_dir, dest_dir):
    # Ensure source directory exists
    if not os.path.isdir(source_dir):
        raise FileNotFoundError(f"Source directory {source_dir} does not exist")
    
    # Create destination directory if it doesn't exist
    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)
    
    # Use shutil to copy the entire directory tree
    try:
        for item in os.listdir(source_dir):
            s = os.path.join(source_dir, item)
            d = os.path.join(dest_dir, item)
            if os.path.isdir(s):
                shutil.copytree(s, d, dirs_exist_ok=True)
            else:
                shutil.copy2(s, d)
        logging.info(f"Successfully copied directory from {source_dir} to {dest_dir}")
    except Exception as e:
        logging.error(f"Failed to copy directory from {source_dir} to {dest_dir}: {e}")

