CREATE OR REPLACE FUNCTION rename_column(table_name TEXT, old_column_name TEXT, new_column_name TEXT, field_object JSONB) RETURNS VOID AS $$
DECLARE
    column_definition TEXT;
BEGIN
    -- Check if the table exists
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = table_name) THEN
        RAISE EXCEPTION 'Table % does not exist', table_name;
    END IF;

    -- Get the column definition
    SELECT string_agg(column_definition, ', ') INTO column_definition
    FROM information_schema.columns
    WHERE table_name = rename_column.table_name AND column_name = rename_column.old_column_name;

    -- Add the new column with constraints
    EXECUTE format('ALTER TABLE %I ADD COLUMN %s', table_name, jsonb_extract_path_text(field_object, 'column'));
    EXECUTE format('ALTER TABLE %I ALTER COLUMN %s SET DATA TYPE %s', table_name, new_column_name, jsonb_extract_path_text(field_object, 'type'));

    -- Rename the column if necessary (not supported in all SQL databases)
    IF old_column_name <> new_column_name THEN
        EXECUTE format('ALTER TABLE %I RENAME COLUMN %s TO %s', table_name, old_column_name, new_column_name);
    END IF;
END;
$$ LANGUAGE plpgsql;
