from flask import Flask, request, redirect, url_for, render_template, session
import requests
import os

app = Flask(__name__)
app.secret_key = 'your_secret_key'  # Change this to a secure random key in production

# PayPal credentials and endpoints
CLIENT_ID = 'your_client_id'
CLIENT_SECRET = 'your_client_secret'
PAYPAL_BASE_URL = "https://api.paypal.com"

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/payment', methods=['POST'])
def payment():
    client_id = request.form['client_id']
    client_secret = request.form['client_secret']

    # Store the credentials in session for later use
    session['client_id'] = client_id
    session['client_secret'] = client_secret

    # Create a payment using PayPal API
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Basic {base64.b64encode(f"{CLIENT_ID}:{CLIENT_SECRET}".encode()).decode()}'
    }

    payload = {
        "intent": "sale",
        "payer": {
            "payment_method": "paypal"
        },
        "redirect_urls": {
            "return_url": url_for('success', _external=True),
            "cancel_url": url_for('index', _external=True)
        },
        "transactions": [{
            "amount": {
                "total": "10.00",
                "currency": "USD"
            },
            "description": "This is a test payment."
        }]
    }

    response = requests.post(f"{PAYPAL_BASE_URL}/v1/payments/payment", headers=headers, json=payload)

    if response.status_code == 201:
        data = response.json()
        approval_url = next(link['href'] for link in data['links'] if link['rel'] == 'approval_url')
        return redirect(approval_url)
    else:
        return "Failed to create payment."

@app.route('/success')
def success():
    payment_id = request.args.get('paymentId')
    client_id = session.get('client_id')
    client_secret = session.get('client_secret')

    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Basic {base64.b64encode(f"{client_id}:{client_secret}".encode()).decode()}'
    }

    response = requests.get(f"{PAYPAL_BASE_URL}/v1/payments/payment/{payment_id}", headers=headers)

    if response.status_code == 200:
        data = response.json()
        if data['state'] == 'approved':
            return "Payment successful!"
        else:
            return "Payment not approved."
    else:
        return "Failed to confirm payment."

if __name__ == '__main__':
    app.run(debug=True)
