def execute_function(func_name, args=(), kwargs={}):
    try:
        # Create a dictionary to hold local variables during execution
        local_vars = {}
        
        # Execute the function with provided arguments and keyword arguments
        exec(f"result = {func_name}(*{args}, **{kwargs})", globals(), local_vars)
        
        # Retrieve the result from the local variables dictionary
        result = local_vars.get('result')
        
        # Remove any variables created in the execution environment after execution
        for var_name in list(local_vars.keys()):
            if var_name != 'result':
                del local_vars[var_name]
        
        return result
    except Exception as e:
        print(f"An error occurred: {e}")
