using System;
using System.Diagnostics;
using System.IO;
using System.Reflection;

class Program
{
    static int Main(string[] args)
    {
        // Generate a dynamic code payload (example: simple C# program)
        string dynamicCode = @"
            using System;
            class DynamicProgram
            {
                static void Main(string[] args)
                {
                    Console.WriteLine(""Hello, World!"");
                    if (args.Length > 0)
                    {
                        Console.WriteLine(""Command line argument: "" + args[0]);
                    }
                }
            }";

        // Save the dynamic code to a temporary file
        string tempFilePath = Path.GetTempFileName();
        File.WriteAllText(tempFilePath, dynamicCode);

        // Compile the dynamic code using csc (C# compiler)
        ProcessStartInfo startInfo = new ProcessStartInfo("csc", $"/out:{tempFilePath}.exe {tempFilePath}")
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (Process compilerProcess = new Process { StartInfo = startInfo })
        {
            compilerProcess.Start();
            string output = compilerProcess.StandardOutput.ReadToEnd();
            string errors = compilerProcess.StandardError.ReadToEnd();
            compilerProcess.WaitForExit();

            if (compilerProcess.ExitCode != 0)
            {
                Console.WriteLine("Compilation failed:");
                Console.WriteLine(errors);
                return compilerProcess.ExitCode;
            }
        }

        // Load the compiled executable
        string exePath = Path.ChangeExtension(tempFilePath, ".exe");
        Assembly assembly = Assembly.LoadFile(exePath);

        // Get the entry point method (Main method)
        MethodInfo mainMethod = assembly.EntryPoint;

        // Execute the program with command line arguments
        string[] commandLineArgs = args;
        object[] parameters = new object[] { commandLineArgs };

        int exitCode = (int)mainMethod.Invoke(null, parameters);

        // Clean up temporary files
        File.Delete(tempFilePath);
        File.Delete(exePath);

        return exitCode;
    }
}
