import requests

def handle_get_request(request, write_function):
    headers = request.headers
    etag = headers.get('If-None-Match')

    response = requests.get(request.url)
    new_etag = response.headers.get('ETag')

    if etag == new_etag:
        return (304, "Not Modified", None)
    else:
        write_function(response.content)

        # Automatically add Content-Length header if it hasn't been set yet
        content_length = len(response.content)
        headers['Content-Length'] = str(content_length)

        return (200, response.text, headers)
