import json

def deserialize_json(input_string):
    def decode_keys(dct):
        new_dict = {}
        for k, v in dct.items():
            try:
                new_k = json.loads(k)
            except (ValueError, TypeError):
                new_k = k
            new_dict[new_k] = v
        return new_dict

    parsed_object = json.loads(input_string, object_hook=decode_keys)
    return parsed_object
