        return "No file part"
    file = request.files['file']
    if file.filename == '':
        return "No selected file"
    if file:
        filename = os.path.join('uploads', file.filename)
        file.save(filename)

        # Process the uploaded file using ctk (assuming some processing logic here)
        result = ctk.process_file(filename)

        return render_template('result.html', filename=file.filename, filesize=os.path.getsize(filename), result=result)
    else:
        return "File upload failed"

@app.route('/download/<path:filename>')
def download_file(filename):
    filepath = os.path.join('uploads', filename)
    if not os.path.exists(filepath):
        return "File not found", 404
    return send_file(filepath, as_attachment=True)

