import hashlib

def generate_hashes(strings, unit=None):
    hashes = []

    for string in strings:
        # Compute SHA-256 hash by default
        sha256_hash = hashlib.sha256(string.encode()).hexdigest()
        hashes.append(sha256_hash)

    if unit is not None:
        if unit == 'bytes':
            # Convert the hex digest to bytes for consistency with other units
            return [bytes.fromhex(h) for h in hashes]
        elif unit == 'bits':
            # Convert each hash from hex to bits (each byte is 8 bits)
            return [len(bytes.fromhex(h)) * 8 for h in hashes]
        else:
            raise ValueError("Unrecognized unit")

    return hashes
