import os
import shutil
import tarfile
import zipfile
from contextlib import closing

def create_staging_folders(products, build_folder):
    for product, packages in products.items():
        staging_folder = os.path.join(build_folder, 'staging', product)
        final_folder = os.path.join(build_folder, 'final', product)
        
        # Create staging folder if it doesn't exist
        if not os.path.exists(staging_folder):
            os.makedirs(staging_folder)
        
        for package in packages:
            # Download and extract the package into the staging folder
            with closing(tarfile.open(package)) as tarinfo:
                def is_within_directory(directory, target):
                    abs_directory = os.path.abspath(directory)
                    abs_target = os.path.abspath(target)
                    return os.path.commonpath([abs_directory]) == os.path.commonpath([abs_directory, abs_target])

                def safe_extract(tar, path=".", members=None):
                    for member in tar.getmembers():
                        member_path = os.path.join(path, member.name)
                        if not is_within_directory(path, member_path):
                            raise Exception("Attempted Path Traversal in Tar File")
                    tar.extractall(path, members)

                safe_extract(tarinfo, path=staging_folder)
            
            # Move extracted files to the final folder
            for cur_file in os.listdir(staging_folder):
                shutil.move(os.path.join(staging_folder, cur_file), final_folder)
        
        # Create a zip file of the final folder
        with zipfile.ZipFile(os.path.join(build_folder, f'{product}.zip'), 'w') as zipf:
            for root, dirs, files in os.walk(final_folder):
                for file in files:
                    zipf.write(os.path.join(root, file), os.path.relpath(os.path.join(root, file), final_folder))
