        Flavor::Shared(ref p) => return p.send(t).map_err(SendError),
        Flavor::Sync(..) => unreachable!(),
    };

    unsafe {
        let tmp = Sender::new(Flavor::Stream(new_inner));
        mem::swap(self.inner_mut(), tmp.inner_mut());
