use std::fs;
use std::io::{self, Write};
use std::path::Path;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        writeln!(std::io::stderr(), "Usage: {} path file", args[0]).unwrap();
        return;
    }

    let file_path = &args[1];
    let output_file_path = &args[2];

    if !Path::new(output_file_path).exists() {
        writeln!(std::io::stderr(), "File {} does not exist", output_file_path).unwrap();
