fn string_from_ptr(s: *const u8) -> &'static str {
    if s.is_null() {
        return "";
    }

    let mut len = 0;
    unsafe {
        while *s.offset(len) != 0 {
            len += 1;
        }
    }

    // SAFETY: We are creating a &'static str from a null-terminated string,
    // which is safe as long as the input pointer is valid and the string is null-terminated.
    unsafe { std::str::from_utf8_unchecked(&*s..&*s.offset(len)) }
}
