def parse_command_line_arguments(args):
    result = []
    current_arg = ""
    in_quotes = False

    for char in args:
        if char == '"' and not in_quotes:
            in_quotes = True
        elif char == '"' and in_quotes:
            in_quotes = False
            result.append(current_arg)
            current_arg = ""
        elif char == ' ' and not in_quotes:
