use std::fs::File;
use std::io::{self, Write};
use std::path::Path;

fn create_tee_writer<P: AsRef<Path>>(paths: Vec<P>) -> io::Result<impl Write> {
    let writers: io::Result<Vec<_>> = paths.iter().map(|path| File::create(path)).collect();
    let mut writers = writers?;

    Ok(io::TeeWriter::new(writers.remove(0), writers))
}

fn main() -> io::Result<()> {
    let paths = vec!["file1.txt", "file2.txt", "file3.txt"];
    let tee_writer = create_tee_writer(paths)?;

    writeln!(tee_writer, "Hello, world!")?;

    for writer in tee_writer.into_inner().iter() {
        writer.flush()?;
    }

    Ok(())
}
```

