use std::net::{IpAddr, SocketAddr};
use std::str::FromStr;
use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <bind_address>:<bind_port> <num_destinations>", args[0]);
        std::process::exit(1);
    }

    let bind_addr = &args[1];
    let num_destinations = args[2].parse().expect("Invalid number of destinations");

    let socket_addr = SocketAddr::from_str(bind_addr).expect("Invalid bind address format");
    let ip_address = IpAddr::V4(socket_addr.ip());
    let port = socket_addr.port();

    let sock = match std::net::UdpSocket::bind((ip_address, port)) {
        Ok(sock) => sock,
        Err(e) => {
            eprintln!("Failed to bind socket: {}", e);
            std::process::exit(1);
        }
    };

    let message = b"Hello, UDP!";
    let mut destinations = Vec::new();

    for i in 0..num_destinations {
        let dest_port = port + i as u16;
        let dest_addr = SocketAddr::new(ip_address, dest_port);
        destinations.push(dest_addr);
    }

    for &dest in &destinations {
