    if !path.is_dir() {
        return Err("The provided directory does not exist or is not a directory".into());
    }

    // Construct the command to update the Cargo.toml file
    let mut cmd = cargo::Command::new("cargo");
    if verbose {
        cmd.arg("--verbose");
    }
    if quiet {
        cmd.arg("--quiet");
    }
    if let Some(color) = color {
        cmd.arg("--color").arg(color);
    }
    if frozen {
        cmd.arg("--frozen");
    }
    if locked {
        cmd.arg("--locked");
    }
    if let Some(manifest_path) = manifest_path {
        cmd.arg("--manifest-path").arg(manifest_path);
    }

    // Run the command to update the Cargo.toml file
    cmd.current_dir(path)?;
    Ok(())
}
