use std::sync::{Once};
use log::{Log, LogLevelFilter, Record};
use env_logger;

static INIT_LOG: Once = Once::new();

pub fn init_logger() {
    INIT_LOG.call_once(|| {
        let mut builder = env_logger::LogBuilder::new();
        
        // Set log level filter based on environment variable
        if let Ok(level) = std::env::var("LOG_LEVEL") {
            match level.as_str() {
                "ERROR" => builder.filter(Some(&["ERROR"]), LogLevelFilter::Error),
                "WARN" => builder.filter(Some(&["WARN", "ERROR"]), LogLevelFilter::Warn),
                "INFO" => builder.filter(Some(&["INFO", "WARN", "ERROR"]), LogLevelFilter::Info),
                "DEBUG" => builder.filter(Some(&["DEBUG", "INFO", "WARN", "ERROR"]), LogLevelFilter::Debug),
                "TRACE" => builder.filter(Some(&["TRACE", "DEBUG", "INFO", "WARN", "ERROR"]), LogLevelFilter::Trace),
                _ => builder.filter(Some(&["ERROR"]), LogLevelFilter::Error),
            }
        } else {
            builder.filter(Some(&["ERROR"]), LogLevelFilter::Error);
        }
        
        // Set log format using a closure
        builder.format(|buf, record| {
            let level = match record.level() {
                log::Level::Error => "ERROR",
                log::Level::Warn => "WARN",
                log::Level::Info => "INFO",
                log::Level::Debug => "DEBUG",
                log::Level::Trace => "TRACE",
            };
            let formatted = format!(
                "[{} {} {}] {}",
                level,
                buf.timestamp(),
                record.module_path().unwrap_or("unknown"),
                record.args()
            );
            writeln!(buf, "{}", formatted)
        });
        
        // Initialize the logger
        builder.init();
    });
}
