fn create_unique_dir(base_name: &str) -> Result<String, std::io::Error> {
    let current_exe = env::current_exe()?;
    let mut path = Path::new(&current_exe).parent().unwrap().to_path_buf();
    
    // Remove 'deps' if it exists at the end of the path
    if let Some(stripped) = path.to_str().and_then(|s| s.strip_suffix("deps")) {
        path = Path::new(stripped).to_path_buf();
