    constant_time_compare(&code_bytes, signature)
}

fn constant_time_compare(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }

    let mut equal = 0;
    for i in 0..a.len() {
        equal |= a[i] ^ b[i];
    }

    equal == 0
