.unwrap(),
)
.await
.expect("Failed to obtain sqlite index");
let mut file = fs::File::create(&sqlite_path)
.await
.expect("Failed to create file sqlite file handle");

let total_size: u64 = response
.headers()
.get("Content-Length")
.unwrap()
.to_str()
