use std::path::{Path, PathBuf};
use std::fs;

fn real_path(path: &str) -> Result<String, Box<dyn std::error::Error>> {
    let path = Path::new(path);
    let mut resolved_path = PathBuf::new();
    let mut current_path = path.to_owned();

    while !current_path.starts_with(&resolved_path) {
        if resolved_path.is_empty() {
            resolved_path.push(current_path);
        } else {
            resolved_path.push(current_path.strip_prefix(&resolved_path)?.to_owned());
        }
        let metadata = fs::metadata(&resolved_path)?;
        if !metadata.is_symlink() {
            current_path = resolved_path.clone();
            resolved_path.pop();
        } else {
            let symlink_target = fs::read_link(&resolved_path)?;
            resolved_path.pop();
            resolved_path.push(symlink_target);
        }
    }

    Ok(resolved_path.to_str().unwrap().to_string())
}
