use std::env;
use std::fs;
use std::path::Path;
use std::time::SystemTime;

struct TempDir {
    path: String,
}

impl Drop for TempDir {
    fn drop(&mut self) {
        if let Err(e) = fs::remove_dir_all(&self.path) {
            eprintln!("Failed to remove temporary directory: {}", e);
        }
    }
}

fn create_temp_dir() -> TempDir {
    let temp_dir = env::temp_dir();
    let timestamp = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .expect("Time went backwards")
        .as_secs();
    let dir_name = format!("{}-{}", timestamp, rand::random::<u32>());
    let new_dir_path = temp_dir.join(dir_name);

    fs::create_dir(&new_dir_path).expect("Failed to create temporary directory");

    TempDir {
        path: new_dir_path.to_string_lossy().into(),
    }
}
