use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::PathBuf;

fn find_executable(exe: &str) -> Option<PathBuf> {
    let cargo_dir = env::var("CARGO_MANIFEST_DIR").ok()?;
    let current_dir = env::current_dir().ok()?;

    let search_dirs = [current_dir, PathBuf::from(&cargo_dir)];

    for dir in search_dirs {
        let path = dir.join(exe);
        if fs::metadata(path.clone()).is_ok() && path.exists() {
            return Some(path);
        }
    }

    None
}
