fn is_homebrew_receipt(file_path: &str) -> Result<bool, std::io::Error> {
    // On Windows, always return false
    if cfg!(windows) {
        return Ok(false);
    }

    // Check if the file exists and has the name 'INSTALL_RECEIPT.json' on Linux
    let path = Path::new(file_path);
    if !path.exists() {
        return Ok(false);
    }

    if path.file_name().unwrap().to_string_lossy() != "INSTALL_RECEIPT.json" {
        return Ok(false);
    }

    // If all checks are passed, return true
    Ok(true)
