fn determine_cargo_root() -> Option<String> {
    if let Some(root) = &*CARGO_ROOT.lock().unwrap() {
        return Some(root.clone());
    }

    let output = Command::new("cargo")
        .arg("--workspace")
        .arg("--message-format=json")
        .output()
        .ok()?;

    if !output.status.success() {
        return None;
