use hmac::{Hmac, Mac};
use sha1::Sha1;
use std::string::String;
use percent_encoding::{utf8_percent_encode, AsciiSet, CONTROLS};

fn create_signature(method: &str, uri: &str, query: &str, consumer_secret: &str) -> String {
    let method = method.to_string();
    let uri = uri.to_string();
    let query = query.to_string();
    let consumer_secret = consumer_secret.to_string();

    // Create the base string to be hashed for HMAC-SHA1 signature
    let base_string = format!("{}&{}{}", method, uri, query);

    // Create the key for HMAC-SHA1 from the consumer secret
    let mut mac = Hmac::<Sha1>::new_from_slice(consumer_secret.as_bytes())
        .expect("HMAC can take key of any size");

    // Update the MAC with the base string bytes
    mac.update(base_string.as_bytes());

    // Finalize and get the result as a byte array
    let result = mac.finalize();
    let code_bytes = result.into_bytes();

    // Convert the byte array to a hex string for the signature
    let mut signature = String::new();
    for byte in code_bytes {
        signature.push_str(&format!("{:02x}", byte));
    }

    signature
}
