use iron::prelude::*;
use iron::status;
use mount::Mount;
use staticfile::Static;
use std::net::SocketAddr;

struct Manager {
    addr: SocketAddr,
}

fn create_web_server(addr: &str) -> Manager {
    let mut mount = Mount::new();
    
    // API handler closure
    let api_handler = |request: Request| -> IronResult<Response> {
        Ok(Response::with((status::Ok, "API endpoint")))
    };
    
    // Serve static files from the current directory
    mount.mount("/", Static::new("."));
    
    // Mount API handler on /api path
    mount.mount("/api", api_handler);
    
    let iron = Iron::new(mount);
    let parsed_addr = addr.parse().expect("Invalid address");
    let server = iron.listen(parsed_addr).unwrap();
    
    Manager { addr: parsed_addr }
}
