use std::net::Ipv6Addr;

fn update_hosts_file(ip: &str, hostname: &str) -> io::Result<()> {
    let path = "/etc/hosts"; // Path to the hosts file
    let mut content = fs::read_to_string(path)?;

    // Check if the line already exists
    if !content.lines().any(|line| line.contains(&hostname)) {
        // Append the new line
        content.push_str("\n");
        content.push_str(ip);
        content.push_str(" ");
        content.push_str(hostname);
