use sha2::{Sha256, Digest};
use std::iter;

struct HashedSequence {
    input: String,
}

impl Iterator for HashedSequence {
    type Item = String;

    fn next(&mut self) -> Option<Self::Item> {
        if let Some(next_input) = &self.input.clone() {
            let mut hasher = Sha256::new();
            hasher.update(next_input);
            let hash = hasher.finalize();
            self.input = format!("{:x}", hash); // Convert the hash to a hexadecimal string
            Some(self.input.clone())
        } else {
            None
        }
    }
}

fn hashed_sequence_iter(input: String) -> HashedSequence {
    HashedSequence { input }
}
