use std::path::{Path, PathBuf};
use std::fs;

fn real_path(path: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut path = PathBuf::from(path);

    while let Some(parent) = path.parent() {
        if !path.is_symlink() {
            break;
        }

        let symlink_target = fs::read_link(&path)?;
        path = parent.join(symlink_target);
    }

    Ok(path.to_str().unwrap().to_string())
}

fn main() {
    match real_path("some/relative/or/symlinked/path") {
        Ok(abs_path) => println!("The absolute path is: {}", abs_path),
