use std::fs::File;
use std::io::{self, Write};

struct History {
    max_size: usize,
    entries: Vec<String>,
}

impl History {
    fn new(max_size: usize) -> Self {
        History {
            max_size,
            entries: Vec::new(),
        }
    }

    fn push(&mut self, entry: String) {
        if self.entries.len() >= self.max_size {
            self.entries.remove(0);
        }
        self.entries.push(entry);
    }

    fn commit(&self, filename: &str) -> io::Result<()> {
        let mut file = File::create(filename)?;
        for entry in &self.entries {
            writeln!(file, "{}", entry)?;
        }
        Ok(())
    }
}

fn main() -> io::Result<()> {
    let mut history = History::new(10);

    // Push some buffers to the history
    for i in 0..15 {
        history.push(format!("Buffer {}", i));
    }

    // Commit the history to a file
    history.commit("history.txt")?;

    // Assert that the length of the committed history is equal to 10
    let reloaded_history = History::new(10);
    let contents = std::fs::read_to_string("history.txt")?;
    for line in contents.lines() {
        reloaded_history.push(line.to_string());
    }
    assert_eq!(reloaded_history.entries.len(), 10);

    Ok(())
}
