#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

int create_temp_file(int *read_fd, int *write_fd) {
    char temp_path[] = "/tmp/temp_XXXXXX";
    int fd = mkstemp(temp_path);
    
    if (fd == -1) {
        perror("Error creating temporary file");
        return errno;
    }
    
    // Set the O_BINARY flag to ensure binary mode
    int flags = fcntl(fd, F_GETFL);
    if (flags == -1) {
        perror("Error getting file status flags");
        close(fd);
        return errno;
    }
    
    // Set the O_NOINHERIT flag to prevent child processes from inheriting the file descriptor
    flags |= O_BINARY | O_NOINHERIT;
    
    if (fcntl(fd, F_SETFL, flags) == -1) {
        perror("Error setting file status flags");
        close(fd);
        return errno;
    }
    
    // Duplicate the file descriptor for reading and writing
    *read_fd = dup(fd);
    if (*read_fd == -1) {
        perror("Error duplicating read file descriptor");
        close(fd);
        return errno;
    }
    
    *write_fd = fd;
    return 0; // Success
}
