use std::io::{self, ErrorKind};

fn open_file(path: &str) -> io::Result<String> {
    // Try to use the environment variable $BROWSER first
    if let Ok(browser) = env::var("BROWSER") {
        if !browser.is_empty() {
            Command::new(&browser).arg(path).spawn()?;
            return Ok(format!("Opened file with {}", browser));
        }
    }

    // Try a list of alternative programs
    let alternatives = ["xdg-open", "gnome-open", "kde-open"];
    for &program in &alternatives {
        match Command::new(program).arg(path).spawn() {
            Ok(_) => return Ok(format!("Opened file with {}", program)),
            Err(e) if e.kind() == ErrorKind::NotFound => continue,
            Err(e) => return Err(e),
        }
    }

    // If none of the programs work, return an error message containing the list of methods that were tried
    let methods_tried = alternatives.iter().map(|&p| p.to_string()).collect::<Vec<String>>().join(", ");
    Err(io::Error::new(ErrorKind::NotFound, format!("No program found to open the file. Tried: {}", methods_tried)))
}
