use uucore::error::{set_exit_code, ExitCode};
use std::process::Command;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <binary_path>", args[0]);
        set_exit_code(ExitCode::USAGE);
        return;
    }

    let binary_path = &args[1];
    print_binary_name(&binary_path);
}

fn print_binary_name<P: AsRef<Path>>(path: P) {
    let path = path.as_ref();
    if !path.is_file() || !path.exists() {
        eprintln!("The provided path is not a file or does not exist.");
        set_exit_code(ExitCode::FAILURE);
        return;
    }

    let output = Command::new("sh")
        .arg("-c")
        .arg(format!("basename {}", path.display()))
        .output()
        .expect("Failed to execute command");

    if !output.status.success() {
        eprintln!("Failed to get binary name.");
        set_exit_code(ExitCode::FAILURE);
        return;
    }

    let binary_name = String::from_utf8(output.stdout).expect("Invalid UTF-8 output");
    let formatted_name = fill(&binary_name, 80);
    println!("{}", formatted_name);
}
