use std::sync::mpsc;
use std::thread;
use std::time::Duration;
use tempfile::TempDir;
use std::fs;
use std::io;

struct RequestResponseChannel {
    request_channel: mpsc::Sender<String>,
    response_channel: mpsc::Receiver<String>,
    timeout: Duration,
    max_message_size: usize,
    temp_dir: TempDir,
}

impl RequestResponseChannel {
    fn new(request_channel_id: &str, response_channel_id: &str, timeout: Duration, max_message_size: usize) -> io::Result<Self> {
        let (tx, rx) = mpsc::channel();
        let temp_dir = TempDir::new()?;

        Ok(RequestResponseChannel {
            request_channel: tx,
            response_channel: rx,
            timeout,
            max_message_size,
            temp_dir,
        })
    }

    fn send_request(&self, message: String) -> io::Result<()> {
        self.request_channel.send(message)?;
        Ok(())
    }

    fn receive_response(&self) -> io::Result<String> {
        let response = self.response_channel.recv()?;
        Ok(response)
    }
}

struct Metadata {
    channel_id: String,
    timeout: Duration,
    max_message_size: usize,
    temp_dir_path: String,
}

impl Metadata {
    fn new(channel_id: &str, timeout: Duration, max_message_size: usize, temp_dir_path: &str) -> Self {
        Metadata {
            channel_id: channel_id.to_string(),
            timeout,
            max_message_size,
            temp_dir_path: temp_dir_path.to_string(),
        }
    }
}

fn create_request_response_channel(request_channel_id: &str, response_channel_id: &str, timeout: Duration, max_message_size: usize) -> io::Result<Metadata> {
