    command_pool: Arc<Mutex<CommandPool>>,
    answer_pool: Arc<Mutex<AnswerPool>>,
    client_connections: Arc<Mutex<ClientConnectionData>>,
}

fn create_thread_safe_pools(buffer_size: usize) -> ThreadSafePools {
    let command_pool = CommandPool {
        commands: vec![String::with_capacity(buffer_size); buffer_size],
    };
    let answer_pool = AnswerPool {
        answers: vec![String::with_capacity(buffer_size); buffer_size],
    };
    let client_connections = ClientConnectionData {
        connections: vec![String::with_capacity(buffer_size); buffer_size],
    };

    ThreadSafePools {
        command_pool: Arc::new(Mutex::new(command_pool)),
        answer_pool: Arc::new(Mutex::new(answer_pool)),
        client_connections: Arc::new(Mutex::new(client_connections)),
    }
}

fn main() {
