use std::env;
use std::process::Command;

fn open_file(path: &str) -> Result<String, String> {
    // Get the BROWSER environment variable or use a default list of commands if not found
    let browser = env::var("BROWSER").map_err(|e| format!("BROWSER environment variable not set: {}", e))?;
    
    // List of alternative commands to try if $BROWSER is not found
    let alternatives = vec![
        "xdg-open",  // Linux, FreeBSD, OpenBSD
        "open",      // macOS
        "explorer"   // Windows (not strictly necessary here since we handle it in the main command)
    ];
    
